INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19959, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指企业、产品或服务有意做出与他人不同的特点，以便和竞争者区分开来。", "primary_collocate": null, "pronunciation": "chā yì huà", "ipa": "ʈʂʰa˥ i˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "最终，合规不再仅是防御性策略，而成为塑造用户信任、构建市场差异化的核心竞争力。", "target_word": "差异化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两家店的差异化很明显。", "target_word": "差异化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想靠差异化赢得客户。", "target_word": "差异化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "产品太像了，就没有差异化。", "target_word": "差异化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "差异化能让小店在市场上活下来。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要做出差异化，别学别人。", "target_word": "差异化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格相同时，服务的差异化更重要。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机越来越多，差异化也越来越难。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，差异化是我们的优势。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的差异化做得很好，所以顾客喜欢。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差异", "label": "复合"}, {"form": "差异性", "label": "复合"}, {"form": "差異化", "label": "繁体"}], "register": "正式", "sense_fingerprint": "有意做出与竞争者不同的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be58e91-1e7c-48b9-beed-073729f7dde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差异化", "is_correct": true, "explanation": "正确。“差异化”是名词，与“核心竞争力”搭配，指与他人不同的特点。"}, {"text": "疫苗", "is_correct": false, "explanation": "语义：疫苗是药品，“构建市场疫苗的核心竞争力”与句意无关。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠是人的生理活动，不能作为“构建市场”的核心竞争力，句意不通。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：饥饿是生理状态，不能作为“构建市场”的核心竞争力。"}], "explanations": {"差异化": "正确。“差异化”是名词，与“核心竞争力”搭配，指与他人不同的特点。", "疫苗": "语义：疫苗是药品，“构建市场疫苗的核心竞争力”与句意无关。", "睡眠": "语义：睡眠是人的生理活动，不能作为“构建市场”的核心竞争力，句意不通。", "饥饿": "语义：饥饿是生理状态，不能作为“构建市场”的核心竞争力。"}, "sentence_index": 0, "correct_answer": "差异化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位同学的差异化很强，老师都说他很特别。", "explanation": "这里应该用〈个性〉。差异化指企业或产品为与他人区分而有意做出的不同，描写人的性格要用〈个性〉。"}, {"text": "这条路的差异化有四十公里长。", "explanation": "这里应该用〈长度〉。差异化说的是特点上的不同，不能用来表示路的长短；路有多长要用〈长度〉。"}, {"text": "这件衣服的差异化很结实，洗了很多次都没坏。", "explanation": "这里应该用〈质量〉。差异化说的是与别人不同的特点，说东西结实、耐用要用〈质量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差异化", "is_correct": true, "explanation": "正确。“服务的差异化”指服务之间的特点差别，与“价格相同时”的比较语境相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：句首“价格相同”已把价格设为前提，再说“服务的价格更重要”自相矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与服务的重要性无关，句意不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量说明物体的轻重，与服务是否重要无关，句意不通。"}], "explanations": {"差异化": "正确。“服务的差异化”指服务之间的特点差别，与“价格相同时”的比较语境相符。", "价格": "语义：句首“价格相同”已把价格设为前提，再说“服务的价格更重要”自相矛盾。", "颜色": "语义：颜色与服务的重要性无关，句意不通。", "重量": "语义：重量说明物体的轻重，与服务是否重要无关，句意不通。"}, "sentence_index": 6, "correct_answer": "差异化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的差异化很便宜，学生都买得起。", "explanation": "这里应该用〈价格〉。差异化说的是事物之间特点上的不同，说东西便宜、贵要用〈价格〉。"}, {"text": "这段路的差异化要走两个小时。", "explanation": "这里应该用〈路程〉。差异化指事物特点上的不同，不能用来说走路要花的距离或时间，描写路程要用〈路程〉。"}, {"text": "这张桌子的差异化是三十斤。", "explanation": "这里应该用〈重量〉。差异化指特点上的不同，说东西有多重要用〈重量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家小店想靠差异化了吸引顾客。", "corrected_sentence": "这家小店想靠差异化吸引顾客。", "error_description": "“差异化”在这里是名词，作“靠”的宾语，名词后面不能加完成体助词“了”，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两家店不有差异化，顾客很难分清。", "corrected_sentence": "这两家店没有差异化，顾客很难分清。", "error_description": "“有”的否定要用“没”，不能用“不”。正确形式是“没有差异化”，“不有”是错误的否定形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7920bec-511e-4978-abf0-7c5fcd4f53ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
