INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19961, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律规定的个人或组织必须履行的责任。", "primary_collocate": null, "pronunciation": "fǎ lǜ yì wù", "ipa": "fa˨˩˦ ly˥˩ i˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "那些能将法律义务转化为治理创新的企业，将在高度规制的AI时代确立不可替代的制度性优势。", "target_word": "法律义务", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "交税是每个公民的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司必须履行法律义务，不能做假账。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母有抚养孩子的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车要系安全带，这是法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道自己有哪些法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业有保护员工安全的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遵守交通规则是司机的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师给我们解释了公司的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护用户信息是网站的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "法律规定个人或组织必须履行的责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e52338-d86c-46e6-8c0d-e6c3d2a19ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法律义务", "is_correct": true, "explanation": "正确。“法律义务”指法律规定必须履行的责任，与“转化为治理创新”的制度语境一致。"}, {"text": "体力", "is_correct": false, "explanation": "语义：体力指人的身体力量，不能被“转化为治理创新”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指事物的色彩，与治理和制度无关，不能被“转化”。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语，常指人，与这句正式的书面语体不协调，也不能被转化。"}], "explanations": {"法律义务": "正确。“法律义务”指法律规定必须履行的责任，与“转化为治理创新”的制度语境一致。", "体力": "语义：体力指人的身体力量，不能被“转化为治理创新”。", "颜色": "语义：颜色指事物的色彩，与治理和制度无关，不能被“转化”。", "家伙": "语域：“家伙”是口语，常指人，与这句正式的书面语体不协调，也不能被转化。"}, "sentence_index": 0, "correct_answer": "法律义务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加班级活动是我的法律义务。", "explanation": "这里应该用〈责任〉或〈义务〉。参加班级活动不是法律规定的，不能说“法律义务”。"}, {"text": "这家公司承担了一张法律义务。", "explanation": "这里应该用〈项〉。“法律义务”是抽象的责任，量词用“项”；“张”用于纸张、桌子等平面物件。"}, {"text": "这次事故的法律义务在司机。", "explanation": "这里应该用〈责任〉。“法律义务”指法律规定必须做的事，不用来说事故的过错归属，那要说“责任在司机”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法律义务", "is_correct": true, "explanation": "正确。句子讲企业保护员工安全的责任，“法律义务”与之相合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是音乐作品，与保护员工安全无关，不能作为企业的责任。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体型，不能说“企业有保护员工安全的身材”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或事物存在的时长，与保护员工安全无关，“保护安全的年龄”说不通。"}], "explanations": {"法律义务": "正确。句子讲企业保护员工安全的责任，“法律义务”与之相合。", "歌曲": "语义：歌曲是音乐作品，与保护员工安全无关，不能作为企业的责任。", "身材": "体貌：身材描述人的体型，不能说“企业有保护员工安全的身材”。", "年龄": "语义：年龄指人或事物存在的时长，与保护员工安全无关，“保护安全的年龄”说不通。"}, "sentence_index": 6, "correct_answer": "法律义务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这周的法律义务是整理文件。", "explanation": "这里应该用〈任务〉。“任务”指工作中的安排；“法律义务”指法律规定的责任，不用来指一般工作。"}, {"text": "这家公司对员工有一首法律义务。", "explanation": "这里应该用〈项〉。“首”用于诗歌、歌曲等，不能量化抽象的“法律义务”。"}, {"text": "他对朋友的法律义务是每周请一次客。", "explanation": "这里应该用〈约定〉。请客是私人之间的约定，法律并不规定，不能说“法律义务”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开车时保持车距，这是司机的一只法律义务。", "corrected_sentence": "开车时保持车距，这是司机的一项法律义务。", "error_description": "量词错误：“法律义务”是抽象的责任，应说“一项法律义务”，不说“一只法律义务”；“只”用于动物等，不能用于责任。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直没有履行了这项法律义务。", "corrected_sentence": "他一直没有履行这项法律义务。", "error_description": "“了”位置错误：“没有”表示否定时不能再接“了”，应说“没有履行这项法律义务”，不说“没有履行了这项法律义务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
