INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19963, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指已经形成固定模式、成为系统一部分的规则或做法。", "primary_collocate": null, "pronunciation": "zhì dù xìng", "ipa": "tʂɻ̩˥˩ tu˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "那些能将法律义务转化为治理创新的企业，将在高度规制的AI时代确立不可替代的制度性优势。", "target_word": "制度性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这不是个人的错，而是制度性的问题。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把加班变成了制度性的做法。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女性升职难，是一种制度性歧视。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的制度性障碍还很多。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校做出了制度性的安排，每周都有检查。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要解决拖欠工资，需要制度性的保障。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的合作有制度性的基础，不靠个人关系。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革带来了制度性的变化。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板换了，但制度性的规定没有变。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制度性的", "label": "定语形式"}], "register": "书面语", "sense_fingerprint": "已成固定模式、属于系统的规则或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e52338-d86c-46e6-8c0d-e6c3d2a19ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制度性", "is_correct": true, "explanation": "“制度性”指成为系统一部分的固定模式，与“确立优势”的语境吻合。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”描写外貌或事物的美好，与“制度性优势”不合。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容声音粗糙，与“优势”无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型，不能修饰抽象的“优势”。"}], "explanations": {"制度性": "“制度性”指成为系统一部分的固定模式，与“确立优势”的语境吻合。", "美丽": "语义：“美丽”描写外貌或事物的美好，与“制度性优势”不合。", "沙哑": "语义：“沙哑”形容声音粗糙，与“优势”无关。", "高大": "体貌：“高大”形容体型，不能修饰抽象的“优势”。"}, "sentence_index": 0, "correct_answer": "制度性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他制度性地忘记带钥匙。", "explanation": "这里应该用〈习惯性〉。制度性指成为系统一部分的固定做法，不用于个人的习惯性失误。"}, {"text": "他每天七点起床，很有制度性。", "explanation": "这里应该用〈规律性〉。制度性指成为系统一部分的固定做法，不用于形容个人作息的规律。"}, {"text": "这次事故带有制度性，只是个意外。", "explanation": "这里应该用〈偶然性〉。制度性指固定模式，不指偶然发生的意外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制度性", "is_correct": true, "explanation": "“制度性”指稳定的制度层面，与“解决拖欠工资”需要的保障相符。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”指随便、不固定，不能用来形容保障。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能修饰“保障”。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容声音粗糙，不能修饰“保障”。"}], "explanations": {"制度性": "“制度性”指稳定的制度层面，与“解决拖欠工资”需要的保障相符。", "随意": "语义：“随意”指随便、不固定，不能用来形容保障。", "漂亮": "体貌：“漂亮”形容外貌，不能修饰“保障”。", "沙哑": "语义：“沙哑”形容声音粗糙，不能修饰“保障”。"}, "sentence_index": 6, "correct_answer": "制度性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "抽奖很有制度性，每个人的机会都一样。", "explanation": "这里应该用〈随机性〉。抽奖的结果由偶然决定，不是成为系统一部分的固定做法。"}, {"text": "这个游戏带有制度性，纯粹是为了好玩。", "explanation": "这里应该用〈娱乐性〉。制度性指固定的做法，不用于形容游戏的娱乐作用。"}, {"text": "他很有制度性，喜欢与众不同。", "explanation": "这里应该用〈个性〉。制度性指成为系统一部分的固定做法，不用于形容人的性格特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套流程已经形成了制度性地做法。", "corrected_sentence": "这套流程已经形成了制度性的做法。", "error_description": "结构错误：“制度性”修饰名词时要用“的”，不用“地”；“地”用于修饰动词。应说“制度性的做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司有制度性地保障，员工的权益不会因人而异。", "corrected_sentence": "公司有制度性的保障，员工的权益不会因人而异。", "error_description": "结构错误：“有”后面应接名词短语，“制度性地保障”把动词结构放在“有”后面，应改为“制度性的保障”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19965, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
