INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19965, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示动作或状态的持续，或表示补充、增加。", "primary_collocate": null, "pronunciation": "hái", "ipa": "xaɪ˧˥", "syllable_count": 1, "sentences": [{"text": "他还在睡觉，你别叫他。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在还早，我们再坐一会儿吧。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了苹果，还买了香蕉。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说英语，还会说日语。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面还下着雨，带上伞吧。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你吃完了吗？我还没吃完。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服很好看，价钱还很便宜。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还住在老房子里。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜已经很多了，还要点别的吗？", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲完课以后，还放了一段视频。", "target_word": "还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词hái：表示动作状态仍在持续，或在已有内容之外再补充", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19965, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。还读 hái，是副词，表示持续或补充。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 hái（第二声）声调不同，意思是海洋。"}, {"text": "害", "is_correct": false, "explanation": "hài（第四声）与 hái（第二声）声调不同，意思是伤害。"}, {"text": "寒", "is_correct": false, "explanation": "hán 与 hái 韵母不同（an 与 ai），意思是寒冷。"}, {"text": "回", "is_correct": false, "explanation": "huí（第二声）与 hái 韵母不同（ui 与 ai），意思是回来。"}], "explanations": {"还": "正确。还读 hái，是副词，表示持续或补充。", "海": "hǎi（第三声）与 hái（第二声）声调不同，意思是海洋。", "害": "hài（第四声）与 hái（第二声）声调不同，意思是伤害。", "寒": "hán 与 hái 韵母不同（an 与 ai），意思是寒冷。", "回": "huí（第二声）与 hái 韵母不同（ui 与 ai），意思是回来。"}, "sentence_index": null, "correct_answer": "还"}, "level_3": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。“还”表示动作仍在持续，与“在睡觉”和“你别叫他”的语境相符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去发生过，与表示正在进行的“在睡觉”冲突。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定了“在睡觉”，与“你别叫他”的提醒矛盾。"}, {"text": "业已", "is_correct": false, "explanation": "语义：“业已”表示“已经”，强调已然发生，与“还”表示动作仍在持续不同；且偏书面，在口语提醒句里生硬。"}], "explanations": {"还": "正确。“还”表示动作仍在持续，与“在睡觉”和“你别叫他”的语境相符。", "曾经": "语义：“曾经”指过去发生过，与表示正在进行的“在睡觉”冲突。", "不": "语义：“不”否定了“在睡觉”，与“你别叫他”的提醒矛盾。", "业已": "语义：“业已”表示“已经”，强调已然发生，与“还”表示动作仍在持续不同；且偏书面，在口语提醒句里生硬。"}, "sentence_index": 0, "correct_answer": "还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一到车站，车还开走了。", "explanation": "这里应该用〈就〉。“一…就…”表示前一动作紧接着发生，“还”不能表示这种紧接的先后关系。"}, {"text": "请你还说一遍，我没听清楚。", "explanation": "这里应该用〈再〉。“还”不表示重复一次，请人重说要用“再”。"}, {"text": "我还吃完晚饭，你就来了。", "explanation": "这里应该用〈刚〉。“刚”表示动作不久前完成，“还”不能表示刚刚发生，应说“刚吃完晚饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19965, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。还读 hái，是副词，表示持续或补充。"}, {"text": "嗨", "is_correct": false, "explanation": "hāi（第一声）与 hái（第二声）声调不同，是打招呼的感叹词。"}, {"text": "柴", "is_correct": false, "explanation": "chái 与 hái 声母不同（ch 与 h），意思是柴火。"}, {"text": "航", "is_correct": false, "explanation": "háng 与 hái 韵母不同（ang 与 ai），意思是航行。"}, {"text": "含", "is_correct": false, "explanation": "hán 与 hái 韵母不同（an 与 ai），意思是包含。"}], "explanations": {"还": "正确。还读 hái，是副词，表示持续或补充。", "嗨": "hāi（第一声）与 hái（第二声）声调不同，是打招呼的感叹词。", "柴": "chái 与 hái 声母不同（ch 与 h），意思是柴火。", "航": "háng 与 hái 韵母不同（ang 与 ai），意思是航行。", "含": "hán 与 hái 韵母不同（an 与 ai），意思是包含。"}, "sentence_index": null, "correct_answer": "还"}, "level_3": {"options": [{"text": "还", "is_correct": true, "explanation": "正确。“还”表示补充，与“价钱还很便宜”的并列语境相符。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”强调数量少或时间晚，与并列补充的语境不符。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”指过去，与描述现在的“很好看”“很便宜”不一致。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过较长过程后才出现，与并列评价衣服好看、价钱便宜的语境不符。"}], "explanations": {"还": "正确。“还”表示补充，与“价钱还很便宜”的并列语境相符。", "才": "语义：“才”强调数量少或时间晚，与并列补充的语境不符。", "曾": "语义：“曾”指过去，与描述现在的“很好看”“很便宜”不一致。", "终于": "语义：“终于”表示经过较长过程后才出现，与并列评价衣服好看、价钱便宜的语境不符。"}, "sentence_index": 6, "correct_answer": "还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她二十岁还学会做饭。", "explanation": "这里应该用〈才〉。“二十岁才学会”表示学会得晚，“还”不能表达这种晚到的意味。"}, {"text": "他七点还到了学校。", "explanation": "这里应该用〈就〉。表示时间早要说“七点就到了”，“还”不能表示早到。"}, {"text": "他一下飞机，还回家了。", "explanation": "这里应该用〈就〉。“一…就…”表示前一动作紧接着发生，“还”不能表示这种紧接的先后关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没还收到你的信。", "corrected_sentence": "我还没收到你的信。", "error_description": "副词位置错误：“还”要放在“没”前面，说“还没”，不能说“没还”。错误形式是“没还收到”，正确形式是“还没收到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间房子很大，房租很还便宜。", "corrected_sentence": "这间房子很大，房租还很便宜。", "error_description": "副词位置错误：“还”要放在“很”前面，说“还很便宜”，不能放在“很”后面。错误形式是“很还便宜”，正确形式是“还很便宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
