INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19966, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "完备美好，没有缺点。", "primary_collocate": null, "pronunciation": "wán měi", "ipa": "wan³⁵ mei̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "它现在还不完美，但以后会越来越好。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这幅画很完美，没有一点问题。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的表演完美极了，大家都鼓掌。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上没有完美的人，每个人都会犯错。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划看起来很完美，我们可以开始做了。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把工作做得完美，所以检查了三次。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好，朋友都在，真是完美的一天。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这篇文章还不够完美，要再改一改。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱得很完美，一个音都没错。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行从头到尾都很完美。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完美地", "label": "状语形式"}, {"form": "完美主义", "label": "复合词"}, {"form": "完美无缺", "label": "复合词"}], "register": "中性", "sense_fingerprint": "形容词：完备美好，没有缺点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完美", "is_correct": true, "explanation": "正确。「还不……，但以后会越来越好」表示目前未达到理想标准，正适合「完美」。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：「饱」形容肚子吃足的状态，不用来评价事物的状况。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：「年轻」多形容人或时代，不用来说事物的好坏程度。"}, {"text": "懒", "is_correct": false, "explanation": "语义：「懒」是贬义的品性，与「越来越好」的期待不合。"}], "explanations": {"完美": "正确。「还不……，但以后会越来越好」表示目前未达到理想标准，正适合「完美」。", "饱": "搭配：「饱」形容肚子吃足的状态，不用来评价事物的状况。", "年轻": "搭配：「年轻」多形容人或时代，不用来说事物的好坏程度。", "懒": "语义：「懒」是贬义的品性，与「越来越好」的期待不合。"}, "sentence_index": 0, "correct_answer": "完美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他完美地忘记了今天要交的作业。", "explanation": "这里应该用〈完全〉。「完美」形容好、没有缺点，忘记作业是缺点，不能用「完美」修饰；表示彻底时用「完全」。"}, {"text": "这次考试他考得很完美，只得了三十分。", "explanation": "这里应该用〈糟糕〉。「完美」指没有缺点，只得三十分的成绩不能说「完美」。"}, {"text": "这次比赛我们完美地输掉了。", "explanation": "这里应该用〈完全〉。「完美」形容好、没有缺点，「输掉」是坏结果，不能用「完美」修饰；表示彻底时用「完全」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完美", "is_correct": true, "explanation": "正确。前文「天气好，朋友都在」说明这一天很好、没有缺憾，「完美」正相符。"}, {"text": "残缺", "is_correct": false, "explanation": "语义：「残缺」指不完整、有损坏，与「天气好，朋友都在」的描述相反。"}, {"text": "糟糕", "is_correct": false, "explanation": "语义：「糟糕」与「天气好，朋友都在」矛盾，前后句意思冲突。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：「高大」形容体型或事物的高度，不能用来修饰「一天」。"}], "explanations": {"完美": "正确。前文「天气好，朋友都在」说明这一天很好、没有缺憾，「完美」正相符。", "残缺": "语义：「残缺」指不完整、有损坏，与「天气好，朋友都在」的描述相反。", "糟糕": "语义：「糟糕」与「天气好，朋友都在」矛盾，前后句意思冲突。", "高大": "搭配：「高大」形容体型或事物的高度，不能用来修饰「一天」。"}, "sentence_index": 6, "correct_answer": "完美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他完美地吃掉了半块蛋糕，剩下的还没动。", "explanation": "这里应该用〈只〉。「完美」形容做得没有缺点，只吃掉一半的事情不能用「完美」描述；表示仅限于其中一部分时用「只」。"}, {"text": "这次的旅行费用完美地涨了一倍。", "explanation": "这里应该用〈大幅〉。「完美」形容好的状态，费用翻倍是不利的变化，不能用「完美」修饰；描述上涨的幅度时用「大幅」。"}, {"text": "妈妈完美地发了一顿脾气。", "explanation": "这里应该用〈痛快〉。「完美」形容做得没有缺点，「发脾气」是负面行为，不能用「完美」修饰；表达畅快淋漓时用「痛快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅地图画得很很完美，连小路都标出来了。", "corrected_sentence": "这幅地图画得很完美，连小路都标出来了。", "error_description": "重复副词：程度副词「很」只用一次，修饰形容词「完美」。错误形式是「很很完美」，正确形式是「很完美」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很完美计划，大家都同意了。", "corrected_sentence": "这是一个很完美的计划，大家都同意了。", "error_description": "错误形式：「很完美计划」。正确形式：「很完美的计划」。「完美」是双音节形容词，修饰名词时一般要加「的」，否则不成词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19967, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏", "is_correct": true, "explanation": "正确：“坏”与“好”构成反义关系，指办法不合心意。"}, {"text": "慢", "is_correct": false, "explanation": "与“好”无反义或近义关系：“慢”是“快”的反义词。"}, {"text": "厚", "is_correct": false, "explanation": "与“好”无反义或近义关系：“厚”指厚度大。"}, {"text": "轻", "is_correct": false, "explanation": "与“好”无反义或近义关系：“轻”是“重”的反义词。"}], "correct_answer": "坏", "explanations": {"坏": "正确：“坏”与“好”构成反义关系，指办法不合心意。", "慢": "与“好”无反义或近义关系：“慢”是“快”的反义词。", "厚": "与“好”无反义或近义关系：“厚”指厚度大。", "轻": "与“好”无反义或近义关系：“轻”是“重”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
