INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指动物脚趾端的角质硬壳，用于抓握、攀爬或捕食。", "primary_collocate": null, "pronunciation": "zhuǎ", "ipa": "tʂwa˨˩˦", "syllable_count": 1, "sentences": [{"text": "小猫用爪抓住了桌上的一只虫子。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰的爪又尖又硬，可以抓住小鱼。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫总在沙发上磨爪，沙发都坏了。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟用爪抓着树枝，一动也不动。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊的爪很大，爬树的时候很有用。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑进屋里，爪上都是泥。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎的爪能抓住跑得很快的鹿。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫把爪伸出来，想抓桌上的玩具。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天雪很深，鸟的爪冻得通红。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "松鼠用爪抱着松果，吃得很开心。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爪子", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物脚趾端的角质硬壳，用来抓握、攀爬、捕食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3530f0c-2ea7-4f92-a396-cbac9f313f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19970, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爪", "is_correct": true, "explanation": "爪（zhuǎ，第三声）指动物脚趾端的角质硬壳，即本词。"}, {"text": "抓", "is_correct": false, "explanation": "抓（zhuā，第一声）与 zhuǎ 声调不同，意思是用手或爪握住。"}, {"text": "转", "is_correct": false, "explanation": "转（zhuǎn）与 zhuǎ 韵母不同，意思是转动。"}, {"text": "耍", "is_correct": false, "explanation": "耍（shuǎ）与 zhuǎ 声母不同（sh 与 zh），意思是玩耍。"}, {"text": "装", "is_correct": false, "explanation": "装（zhuāng）比 zhuǎ 多了 ng 韵尾且声调不同，意思是装载或装扮。"}], "explanations": {"爪": "爪（zhuǎ，第三声）指动物脚趾端的角质硬壳，即本词。", "抓": "抓（zhuā，第一声）与 zhuǎ 声调不同，意思是用手或爪握住。", "转": "转（zhuǎn）与 zhuǎ 韵母不同，意思是转动。", "耍": "耍（shuǎ）与 zhuǎ 声母不同（sh 与 zh），意思是玩耍。", "装": "装（zhuāng）比 zhuǎ 多了 ng 韵尾且声调不同，意思是装载或装扮。"}, "sentence_index": null, "correct_answer": "爪"}, "level_3": {"options": [{"text": "爪", "is_correct": true, "explanation": "正确：原句为“小猫用爪抓住了桌上的一只虫子”，空格应填“爪”。"}, {"text": "手", "is_correct": false, "explanation": "语义：“手”指人的手，猫用的是爪，不能说“用手抓住”。"}, {"text": "角", "is_correct": false, "explanation": "语义：猫没有角，“角”不能用来抓住东西。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：猫没有翅膀，不能用翅膀抓住虫子。"}], "explanations": {"爪": "正确：原句为“小猫用爪抓住了桌上的一只虫子”，空格应填“爪”。", "手": "语义：“手”指人的手，猫用的是爪，不能说“用手抓住”。", "角": "语义：猫没有角，“角”不能用来抓住东西。", "翅膀": "语义：猫没有翅膀，不能用翅膀抓住虫子。"}, "sentence_index": 0, "correct_answer": "爪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "马在草地上奔跑，爪踏起一阵尘土。", "explanation": "这里应该用〈蹄〉。马的脚端是蹄，“爪”指猫、鸟、虎等动物脚上的尖爪，不用于马。"}, {"text": "他用爪拿起了筷子。", "explanation": "这里应该用〈手〉。“爪”指动物脚上的硬爪，人拿东西要说用手，不能用爪。"}, {"text": "小鸟用爪唱着歌，声音很好听。", "explanation": "这里应该用〈嘴〉。鸟的叫声由嘴发出，“爪”是脚上的硬壳，不用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19970, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爪", "is_correct": true, "explanation": "爪（zhuǎ，第三声）指动物脚趾端的角质硬壳，即本词。"}, {"text": "刷", "is_correct": false, "explanation": "刷（shuā，第一声）与 zhuǎ 声母和声调都不同，意思是刷子或刷洗。"}, {"text": "撞", "is_correct": false, "explanation": "撞（zhuàng，第四声）比 zhuǎ 多了 ng 韵尾且声调不同，意思是碰撞。"}, {"text": "眨", "is_correct": false, "explanation": "眨（zhǎ）比 zhuǎ 少了介音 u，意思是眨眼。"}], "explanations": {"爪": "爪（zhuǎ，第三声）指动物脚趾端的角质硬壳，即本词。", "刷": "刷（shuā，第一声）与 zhuǎ 声母和声调都不同，意思是刷子或刷洗。", "撞": "撞（zhuàng，第四声）比 zhuǎ 多了 ng 韵尾且声调不同，意思是碰撞。", "眨": "眨（zhǎ）比 zhuǎ 少了介音 u，意思是眨眼。"}, "sentence_index": null, "correct_answer": "爪"}, "level_3": {"options": [{"text": "爪", "is_correct": true, "explanation": "正确：原句为“老虎的爪能抓住跑得很快的鹿”，空格应填“爪”。"}, {"text": "牙", "is_correct": false, "explanation": "搭配：“抓住”要用爪，牙齿是咬，不能说牙“抓住”鹿。"}, {"text": "嘴", "is_correct": false, "explanation": "搭配：嘴用来咬或吃，不能说嘴“抓住”鹿。"}, {"text": "蹄", "is_correct": false, "explanation": "语义：老虎没有蹄，蹄是鹿、马等有蹄动物的脚端，不能用于老虎。"}], "explanations": {"爪": "正确：原句为“老虎的爪能抓住跑得很快的鹿”，空格应填“爪”。", "牙": "搭配：“抓住”要用爪，牙齿是咬，不能说牙“抓住”鹿。", "嘴": "搭配：嘴用来咬或吃，不能说嘴“抓住”鹿。", "蹄": "语义：老虎没有蹄，蹄是鹿、马等有蹄动物的脚端，不能用于老虎。"}, "sentence_index": 6, "correct_answer": "爪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "树上长满了绿色的爪，风一吹就沙沙响。", "explanation": "这里应该用〈叶子〉。“爪”指动物脚上的硬爪，树上的叶子要说叶子，不能说爪。"}, {"text": "这棵苹果树结满了红红的爪。", "explanation": "这里应该用〈苹果〉。“爪”指动物脚上的硬爪，树上结的果实要说苹果，不能说爪。"}, {"text": "每朵花都长着一只白色的爪。", "explanation": "这里应该用〈花瓣〉。“爪”指动物脚上的硬爪，花的部分要说花瓣，不能说爪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老鹰用蹄抓住了小兔子。", "corrected_sentence": "老鹰用爪抓住了小兔子。", "error_description": "用词错误：老鹰的脚端是尖利的爪，“蹄”是马、牛、鹿等动物的脚端，老鹰没有蹄，应说“用爪抓住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫把爪收去回，躺在窗台上睡觉。", "corrected_sentence": "小猫把爪收回去，躺在窗台上睡觉。", "error_description": "补语语序错误：复合趋向补语“收回去”中“回”与“去”的顺序不能颠倒，应说“收回去”，“收去回”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
