INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19971, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示动作或情况重复发生，相当于‘再’、‘重新’。", "primary_collocate": null, "pronunciation": "yòu", "ipa": "joʊ˥˩", "syllable_count": 1, "sentences": [{"text": "他昨天迟到了，今天又迟到了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么又忘了带钥匙？", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末又下雨了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈又给我打了一个电话。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我又做错了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子又哭了，快去看看他。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了一遍，又看了一遍。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天又来了，花都开了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板今天又请我们吃饭了。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机又坏了，我只好去买新的。", "target_word": "又", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "同一动作或情况已经再次发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "又", "is_correct": true, "explanation": "正确答案：又 yòu，表示动作或情况再次发生。"}, {"text": "有", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，有的意思是拥有。"}, {"text": "油", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，油意思是油脂。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 yòu 声母不同（l 与 y），漏意思是漏出、漏洞。"}, {"text": "用", "is_correct": false, "explanation": "yòng 与 yòu 韵尾不同（-ng 与 -u），用意思是使用。"}], "explanations": {"又": "正确答案：又 yòu，表示动作或情况再次发生。", "有": "yǒu（第三声）与 yòu（第四声）声调不同，有的意思是拥有。", "油": "yóu（第二声）与 yòu（第四声）声调不同，油意思是油脂。", "漏": "lòu 与 yòu 声母不同（l 与 y），漏意思是漏出、漏洞。", "用": "yòng 与 yòu 韵尾不同（-ng 与 -u），用意思是使用。"}, "sentence_index": null, "correct_answer": "又"}, "level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "正确：“又”表示同样的迟到再次出现，与“昨天迟到了”形成重复。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未发生过，与“今天迟到了”的事实相矛盾。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，不能与已完成的“迟到了”搭配表示重复。"}, {"text": "简直", "is_correct": false, "explanation": "搭配：“简直”表示程度，不修饰“迟到”这类动作，句子无法成立。"}], "explanations": {"又": "正确：“又”表示同样的迟到再次出现，与“昨天迟到了”形成重复。", "从来": "语义：“从来”表示从未发生过，与“今天迟到了”的事实相矛盾。", "永远": "语义：“永远”表示持续不变，不能与已完成的“迟到了”搭配表示重复。", "简直": "搭配：“简直”表示程度，不修饰“迟到”这类动作，句子无法成立。"}, "sentence_index": 0, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从没去过北京，这次又去了。", "explanation": "这里应该删去〈又〉。“从没去过”表示以前从未去过，与“又”表示再次的意思矛盾。"}, {"text": "他又出生在北京。", "explanation": "这里应该删去〈又〉。出生只发生一次，不能再次出现，与“又”表示重复的意思矛盾。"}, {"text": "这是我第一次又去那里。", "explanation": "这里应该删去〈又〉。“第一次”说明是首次，与“又”表示再次的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19971, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "又", "is_correct": true, "explanation": "正确答案：又 yòu，表示动作或情况再次发生。"}, {"text": "游", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，游意思是游泳。"}, {"text": "友", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，友意思是朋友。"}, {"text": "后", "is_correct": false, "explanation": "hòu 与 yòu 声母不同（h 与 y），后意思是之后。"}, {"text": "优", "is_correct": false, "explanation": "yōu（第一声）与 yòu（第四声）声调不同，优意思是优秀。"}], "explanations": {"又": "正确答案：又 yòu，表示动作或情况再次发生。", "游": "yóu（第二声）与 yòu（第四声）声调不同，游意思是游泳。", "友": "yǒu（第三声）与 yòu（第四声）声调不同，友意思是朋友。", "后": "hòu 与 yòu 声母不同（h 与 y），后意思是之后。", "优": "yōu（第一声）与 yòu（第四声）声调不同，优意思是优秀。"}, "sentence_index": null, "correct_answer": "又"}, "level_3": {"options": [{"text": "又", "is_correct": true, "explanation": "正确：“又”表示看书这一动作再次发生，与前一个“看了一遍”形成重复。"}, {"text": "务必", "is_correct": false, "explanation": "语义：“务必”要求将来一定要做，不能用来叙述已经看过的事。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“看了一遍”这一已发生的事实矛盾。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于叮嘱，不与“看了一遍”这类叙述搭配。"}], "explanations": {"又": "正确：“又”表示看书这一动作再次发生，与前一个“看了一遍”形成重复。", "务必": "语义：“务必”要求将来一定要做，不能用来叙述已经看过的事。", "不必": "语义：“不必”表示没有必要，与“看了一遍”这一已发生的事实矛盾。", "千万": "搭配：“千万”多用于叮嘱，不与“看了一遍”这类叙述搭配。"}, "sentence_index": 6, "correct_answer": "又"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我最后一次又去那里。", "explanation": "这里应该删去〈又〉。“最后一次”表示之后不再发生，与“又”表示再次的意思矛盾。"}, {"text": "他直到昨天又回家。", "explanation": "这里应该用〈才〉。又表示再次发生，不表示事情到昨天才出现。"}, {"text": "他又小，不能上学。", "explanation": "这里应该用〈还〉。又表示再次，不表示年纪尚小；“还小”表示年龄不大，尚未长大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她又的忘记了锁门。", "corrected_sentence": "她又忘记了锁门。", "error_description": "错误：“又的”。正确：“又”。“又”是副词，后面不能直接加“的”，应删去“的”，说“她又忘记了锁门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨下又起来了。", "corrected_sentence": "雨又下起来了。", "error_description": "错误：“下又起来”。正确：“又下起来”。“又”表示重复，应位于“下起来”之前修饰整个动作，放在动词“下”之后语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
