INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协助他人完成工作的人。", "primary_collocate": null, "pronunciation": "zhù shǒu", "ipa": "ʈʂu˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "很多人开始请个人助手来帮助学习、工作和生活。", "target_word": "助手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "也许以后每个家庭都会雇一个家务助手。", "target_word": "助手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的助手正在准备药品。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我需要一个助手帮我整理文件。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是教授最好的助手。", "target_word": "助手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板请了一位新助手来管账。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位助手每天帮经理安排会议。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里有两个助手，都很努力。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做了三年校长的助手，很熟悉学校。", "target_word": "助手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有助手，我一个人忙不过来。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个助手", "label": "量词"}, {"form": "小助手", "label": "复合"}], "register": "中性", "sense_fingerprint": "协助他人完成工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f18f94-d445-4d0e-a98e-278af7fa0f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。"}, {"text": "祝寿", "is_correct": false, "explanation": "祝寿 zhùshòu 与助手的第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。"}, {"text": "注水", "is_correct": false, "explanation": "注水 zhùshuǐ 第二个音节韵母不同（shuǐ 与 shǒu），意思是把水灌入。"}, {"text": "猪手", "is_correct": false, "explanation": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。", "祝寿": "祝寿 zhùshòu 与助手的第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。", "注水": "注水 zhùshuǐ 第二个音节韵母不同（shuǐ 与 shǒu），意思是把水灌入。", "猪手": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“个人助手”指帮人处理学习、工作和生活事务的人，符合句中语境。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能帮助学习、工作和生活，与“帮助”的语境冲突。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机的职责是开车，不能帮助人学习，与句中“学习”的语境不符。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“请”后接的应是能帮人做事的人，“房间”不能被请来帮助学习、工作和生活。"}], "explanations": {"助手": "正确答案。“个人助手”指帮人处理学习、工作和生活事务的人，符合句中语境。", "玩具": "语义：玩具不能帮助学习、工作和生活，与“帮助”的语境冲突。", "司机": "语义：司机的职责是开车，不能帮助人学习，与句中“学习”的语境不符。", "房间": "搭配：“请”后接的应是能帮人做事的人，“房间”不能被请来帮助学习、工作和生活。"}, "sentence_index": 0, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "总经理是他秘书的助手，每天听秘书安排工作。", "explanation": "助手是协助上级完成工作的人。总经理是上级，不能说成秘书的助手，角色用反了。"}, {"text": "我的老板是我的助手，每天向我汇报工作。", "explanation": "助手指辅助别人的人，地位在被辅助者之下。这里把上级说成助手，用法不对，应该用〈下属〉或〈同事〉之类的词。"}, {"text": "医院里的助手负责主刀手术，医生只在一旁帮忙。", "explanation": "助手是协助主要人员的人。主刀手术的应是医生，这里把助手当成了主要操作者，角色用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。"}, {"text": "触手", "is_correct": false, "explanation": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是能够碰到的地方或章鱼的腕。"}, {"text": "出手", "is_correct": false, "explanation": "出手 chūshǒu 第一个音节声母不同（ch 与 zh），意思是卖出或动手。"}, {"text": "住宿", "is_correct": false, "explanation": "住宿 zhùsù 第二个音节的韵母和声调不同（sù 第四声，shǒu 第三声），意思是在某处住下来。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。", "触手": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是能够碰到的地方或章鱼的腕。", "出手": "出手 chūshǒu 第一个音节声母不同（ch 与 zh），意思是卖出或动手。", "住宿": "住宿 zhùsù 第二个音节的韵母和声调不同（sù 第四声，shǒu 第三声），意思是在某处住下来。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“这位助手”指协助经理的人，能安排会议。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不负责安排会议，与句中“安排会议”的语境冲突。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“这位”用于指人，不能指窗户，量词与名词搭配不当。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：出租车是交通工具，不能每天帮经理安排会议。"}], "explanations": {"助手": "正确答案。“这位助手”指协助经理的人，能安排会议。", "厨师": "语义：厨师负责做饭，不负责安排会议，与句中“安排会议”的语境冲突。", "窗户": "搭配：“这位”用于指人，不能指窗户，量词与名词搭配不当。", "出租车": "语义：出租车是交通工具，不能每天帮经理安排会议。"}, "sentence_index": 6, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在课堂上是老师的助手，负责给老师打分。", "explanation": "助手是协助别人完成工作的人，应辅助被帮助的一方，不能给对方打分。这里把学生说成老师的助手，还让他评判老师，角色用错了。"}, {"text": "教授是他学生的助手，学生决定他每天做什么实验。", "explanation": "助手是辅助别人的人，地位在被辅助者之下。教授不能当学生的助手并听学生安排，角色用反了。"}, {"text": "这家公司的老板是助手，每天负责发工资。", "explanation": "助手不能处于老板的位置。这里把决策者说成助手，与助手的身份不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找了一张助手帮我看店。", "corrected_sentence": "我找了一个助手帮我看店。", "error_description": "量词错误：“助手”指人，应用“个”或“位”，不能用“张”。“张”用于纸、桌子等扁平的东西，不能计量指人的助手。正确形式是“一个助手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她请了一把助手来帮她整理房间。", "corrected_sentence": "她请了一个助手来帮她整理房间。", "error_description": "量词用错了。“助手”指人，应用“个”或“位”，不能用“把”。“把”多用于有柄的器物，错误形式把“助手”当成了器物。正确形式是“一个助手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
