INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把新的事物、产品、政策等公开发布或开始实行。", "primary_collocate": null, "pronunciation": "tuī chū", "ipa": "tʰueɪ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "一些科技公司推出了开源的AI代理项目，让所有人都能查看和修改程序代码。", "target_word": "推出", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这家公司下个月要推出新手机。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店推出了一种新的蛋糕。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府推出了新政策，帮助老人。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家餐厅最近推出了便宜的午饭。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影公司明年要推出三部新电影。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校推出了网上学习的新办法。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个品牌每年都推出新衣服。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们推出过一个很有名的游戏。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行推出了新的手机服务，大家都很喜欢。", "target_word": "推出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推出了", "label": "体标"}, {"form": "推出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "公开发布新产品、新政策或新服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f18f94-d445-4d0e-a98e-278af7fa0f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。"}, {"text": "退出", "is_correct": false, "explanation": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。"}, {"text": "突出", "is_correct": false, "explanation": "突出 tūchū 与推出只差一个音位（tū 与 tuī），意思是高于周围或显眼。"}, {"text": "脱出", "is_correct": false, "explanation": "脱出 tuōchū 第一个音节韵母不同（uo 与 ui），意思是挣脱后从某处出来。"}], "explanations": {"推出": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。", "退出": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。", "突出": "突出 tūchū 与推出只差一个音位（tū 与 tuī），意思是高于周围或显眼。", "脱出": "脱出 tuōchū 第一个音节韵母不同（uo 与 ui），意思是挣脱后从某处出来。"}, "sentence_index": null, "correct_answer": "推出"}, "level_3": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。“推出了开源的AI代理项目”指公开发布，与“让所有人都能查看和修改”的语境一致。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除是去掉某物，与句末“让所有人都能查看和修改”的公开语境相反。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏是不让别人看见，与“开源”和“让所有人都能查看”的语境冲突。"}, {"text": "关闭", "is_correct": false, "explanation": "搭配：“关闭”的对象若是开源项目，会让人无法查看和修改，与句末的公开语境相反。"}], "explanations": {"推出": "正确答案。“推出了开源的AI代理项目”指公开发布，与“让所有人都能查看和修改”的语境一致。", "删除": "语义：删除是去掉某物，与句末“让所有人都能查看和修改”的公开语境相反。", "隐藏": "语义：隐藏是不让别人看见，与“开源”和“让所有人都能查看”的语境冲突。", "关闭": "搭配：“关闭”的对象若是开源项目，会让人无法查看和修改，与句末的公开语境相反。"}, "sentence_index": 0, "correct_answer": "推出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师推出了一道很难的数学题。", "explanation": "这里应该用〈出〉。推出用于公开发布新产品或政策，不能用来指出题目。"}, {"text": "他用力把车推出了车库，因为车坏了。", "explanation": "这里是“推出”的另一个意思，表示用力使某物离开。它不表示公开发布新产品，这里的用法与“公开发布”的意思不符。"}, {"text": "会议上大家推出了很多反对意见。", "explanation": "这里应该用〈提出〉。提出用于意见、建议、问题；推出用于可供购买或使用的新产品和服务，不能用于意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。"}, {"text": "吹出", "is_correct": false, "explanation": "吹出 chuīchū 第一个音节声母不同（ch 与 t），意思是用力把气或东西吹出来。"}, {"text": "追出", "is_correct": false, "explanation": "追出 zhuīchū 第一个音节声母不同（zh 与 t），意思是追赶着跑到外面去。"}, {"text": "退出", "is_correct": false, "explanation": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。"}], "explanations": {"推出": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。", "吹出": "吹出 chuīchū 第一个音节声母不同（ch 与 t），意思是用力把气或东西吹出来。", "追出": "追出 zhuīchū 第一个音节声母不同（zh 与 t），意思是追赶着跑到外面去。", "退出": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。"}, "sentence_index": null, "correct_answer": "推出"}, "level_3": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。“推出了网上学习的新办法”指公开提出并开始实行，与“新办法”的语境一致。"}, {"text": "废除", "is_correct": false, "explanation": "语义：废除是取消既有的规定，与“新办法”的语境相反。"}, {"text": "停止", "is_correct": false, "explanation": "语义：停止是中断已经开始的事，与“推出新办法”的语境冲突。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记是记不住某事，不能用来表示学校把新办法公开实行。"}], "explanations": {"推出": "正确答案。“推出了网上学习的新办法”指公开提出并开始实行，与“新办法”的语境一致。", "废除": "语义：废除是取消既有的规定，与“新办法”的语境相反。", "停止": "语义：停止是中断已经开始的事，与“推出新办法”的语境冲突。", "忘记": "语义：忘记是记不住某事，不能用来表示学校把新办法公开实行。"}, "sentence_index": 6, "correct_answer": "推出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我推出这本书给你，你一定要看。", "explanation": "这里应该用〈推荐〉。推荐指把好的东西介绍给别人让人选用；推出是公开发布新产品或服务，不能用来对个人介绍书籍。"}, {"text": "老师把那个学生推出了教室，让他站在外面。", "explanation": "这里是“推出”的另一个意思，表示用力使人离开某处。它不表示公开发布，这里的用法与句意不符。"}, {"text": "店员把旧衣服推出给顾客，说是新款。", "explanation": "这里应该用〈推销〉。推销是主动向顾客介绍并卖出商品；推出是公开发布新商品，不能用来指向顾客卖旧货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司去年推出了过一款新游戏。", "corrected_sentence": "这家公司去年推出过一款新游戏。", "error_description": "体标叠加错误：「推出」后已用「过」表示曾经做过，不能再加「了」。错误形式是「推出了过」，正确形式是「推出过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店今年推出着一套新书。", "corrected_sentence": "这家书店今年推出了一套新书。", "error_description": "体标错误：「推出」是一次性完成的动作，不能用表示持续的「着」，应改为「推出了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
