INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "计算机程序中的指令集合，由程序员编写，计算机可以理解并执行。", "primary_collocate": null, "pronunciation": "chéng xù dài mǎ", "ipa": "ʈʂʰɤŋ˧˥ ɕy˥˩ taɪ̯˥˩ ma˨˩˦", "syllable_count": 4, "sentences": [{"text": "一些科技公司推出了开源的AI代理项目，意思是把程序代码公开，让所有人都能查看和修改。", "target_word": "程序代码", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他每天写很多程序代码。", "target_word": "程序代码", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这段程序代码有一个错误。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把程序代码发给我。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这行程序代码是什么意思？", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了一下程序代码，就找到了问题。", "target_word": "程序代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的程序代码是公开的。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们读这段程序代码。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "程序代码太长了，我看不懂。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写的程序代码很清楚。", "target_word": "程序代码", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段程序代码", "label": "量词"}, {"form": "一行程序代码", "label": "量词"}], "register": "中性", "sense_fingerprint": "程序员编写的、可被计算机执行的指令集合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f18f94-d445-4d0e-a98e-278af7fa0f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "程序代码", "is_correct": true, "explanation": "正确：指“开源项目”中可以公开、查看和修改的程序指令。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不是可以“开源”、让所有人修改的科技项目。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：“开源”一般修饰软件或代码，不修饰菜谱，与“AI代理项目”也不相符。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报是气象信息，与科技公司推出的AI代理项目无关。"}], "explanations": {"程序代码": "正确：指“开源项目”中可以公开、查看和修改的程序指令。", "小说": "语义：小说是文学作品，不是可以“开源”、让所有人修改的科技项目。", "菜谱": "搭配：“开源”一般修饰软件或代码，不修饰菜谱，与“AI代理项目”也不相符。", "天气预报": "语义：天气预报是气象信息，与科技公司推出的AI代理项目无关。"}, "sentence_index": 0, "correct_answer": "程序代码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一只程序代码。", "explanation": "这里应该用〈段〉或〈行〉。程序代码按段、行计量，“只”用于动物等，不能用来数程序代码。"}, {"text": "这个会议的程序代码很简单。", "explanation": "这里应该用〈流程〉。“程序代码”指计算机指令，不能指会议的先后步骤。"}, {"text": "他是一名很棒的程序代码。", "explanation": "这里应该用〈程序员〉。程序代码是指令，不是人；指编写代码的人要说程序员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "程序代码", "is_correct": true, "explanation": "正确：“这个软件的”后接软件的指令，“公开”指代码可以开放给人查看。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：软件里没有歌词，“软件的歌词”说不通。"}, {"text": "身份证", "is_correct": false, "explanation": "搭配：“软件的”后面应接软件的组成部分，身份证不属于软件。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是病人的医疗记录，与软件无关。"}], "explanations": {"程序代码": "正确：“这个软件的”后接软件的指令，“公开”指代码可以开放给人查看。", "歌词": "语义：软件里没有歌词，“软件的歌词”说不通。", "身份证": "搭配：“软件的”后面应接软件的组成部分，身份证不属于软件。", "病历": "语义：病历是病人的医疗记录，与软件无关。"}, "sentence_index": 6, "correct_answer": "程序代码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她写的一首程序代码很清楚。", "explanation": "这里应该用〈段〉或〈行〉。“首”用于歌曲、诗词，不用于程序代码。"}, {"text": "这段文字的程序代码是UTF-8。", "explanation": "这里应该用〈编码〉。“程序代码”指计算机指令，不能指文字的字符编码方式。"}, {"text": "她的程序代码是“白狐”。", "explanation": "这里应该用〈代号〉。“代码”在这里指代号，程序代码只指计算机指令，不能用来称呼人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写了三只程序代码。", "corrected_sentence": "他写了三段程序代码。", "error_description": "量词错误：程序代码应用“段”或“行”计量，“只”用于动物等，应把“三只”改为“三段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一朵程序代码。", "corrected_sentence": "他写了一段程序代码。", "error_description": "量词错误：程序代码应用「段」或「行」计量，「朵」用于花等，应把「朵」改为「段」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0a2b70-9da1-43f2-b93f-cae70927e0b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
