INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过文字表达思想或记录事情，形成一篇完整的作品。", "primary_collocate": null, "pronunciation": "xiě wén zhāng", "ipa": "ɕjɛ˨˩˦ wən˧˥ ʈʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "它不仅能回答问题、写文章，还能理解复杂的指令，帮用户完成多步骤的任务。", "target_word": "写文章", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他每天晚上都在家写文章。", "target_word": "写文章", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "作家需要安静的地方写文章。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想写文章，可是没有好题目。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写文章的时候，喜欢听轻音乐。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们用三十分钟写文章。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢写文章，把自己的想法记下来。", "target_word": "写文章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章前，你要先想好开头。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位记者写文章又快又好。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我在咖啡馆写文章，不在家。", "target_word": "写文章", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "写了文章", "label": "体标（了）"}, {"form": "写过文章", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "用文字表达思想、记录事情，写成完整的文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a6cad1-527d-4756-8bdd-654c381daff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃饭", "is_correct": false, "explanation": "语义：它是程序，不吃饭，与前面“回答问题”这类能力不能并列。"}, {"text": "写文章", "is_correct": true, "explanation": "正确。写文章指用文字写成完整的作品，与“回答问题”并列，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：它不需要睡觉，这里列举的是它的能力，睡觉不成立。"}, {"text": "散步", "is_correct": false, "explanation": "语义：它是程序，不能散步，与前面「回答问题」这类能力不能并列。"}], "explanations": {"吃饭": "语义：它是程序，不吃饭，与前面“回答问题”这类能力不能并列。", "写文章": "正确。写文章指用文字写成完整的作品，与“回答问题”并列，符合句意。", "睡觉": "语义：它不需要睡觉，这里列举的是它的能力，睡觉不成立。", "散步": "语义：它是程序，不能散步，与前面「回答问题」这类能力不能并列。"}, "sentence_index": 0, "correct_answer": "写文章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在黑板上写文章，只写了一个“好”字。", "explanation": "这里应该用〈写字〉。写文章指成篇的文字作品，只写一个字要用写字。"}, {"text": "他在支票上写文章。", "explanation": "这里应该用〈写金额〉。支票上只填金额，不能写成篇的文章。"}, {"text": "妈妈在灯下给我写文章，只写了一句“晚安”。", "explanation": "这里应该用〈写便条〉。便条只有几句话，不是成篇的文字作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与后面“把想法记下来”的意思相反，句子矛盾。"}, {"text": "写文章", "is_correct": true, "explanation": "正确。写文章与“把自己的想法记下来”相配，表示用文字记录想法。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆时不会把想法记下来，与后半句的动作不相符。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉内容，与后半句“把想法记下来”意思相反，句子矛盾。"}], "explanations": {"忘记": "语义：“忘记”与后面“把想法记下来”的意思相反，句子矛盾。", "写文章": "正确。写文章与“把自己的想法记下来”相配，表示用文字记录想法。", "发呆": "语义：发呆时不会把想法记下来，与后半句的动作不相符。", "删除": "语义：“删除”是去掉内容，与后半句“把想法记下来”意思相反，句子矛盾。"}, "sentence_index": 6, "correct_answer": "写文章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在墙上写文章，写的是口号。", "explanation": "这里应该用〈写标语〉。墙上写的是口号，不是成篇的文章。"}, {"text": "他在名片上写文章。", "explanation": "这里应该用〈写名字〉。名片上只写姓名和电话，不能写成篇的文章。"}, {"text": "春节时，他们在门上写文章。", "explanation": "这里应该用〈写对联〉。门上贴的是对联，不是成篇的文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写文章写很快。", "corrected_sentence": "他写文章写得很快。", "error_description": "补语错误：“写”后面的程度补语要用“得”连接，应说“写得很快”，不能省掉“得”直接说“写很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很写文章。", "corrected_sentence": "他很喜欢写文章。", "error_description": "搭配错误：“很”是程度副词，要修饰形容词或“喜欢”这类心理动词，不能直接放在“写文章”前，应说“很喜欢写文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
