INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指从事软件开发、编写程序的人。", "primary_collocate": null, "pronunciation": "kāi fā zhě", "ipa": "kʰaɪ̯⁵⁵ fa⁵⁵ ʈʂɤ²¹⁴", "syllable_count": 3, "sentences": [{"text": "从生态演进视角看，OpenClaw的开源属性加速了全球开发者对其架构的解构与重构。", "target_word": "开发者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "因为它对所有人开放，研究人员、开发者和普通用户都可以测试它、提出建议或增加新功能。", "target_word": "开发者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个软件的开发者是一位年轻人。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发者每天都要写很多代码。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发者发现了手机应用里的错误。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当一名游戏开发者。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在招聘新的开发者。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发者把新版本放到了网站上。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发者听了用户的意见，改好了软件。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多开发者喜欢在晚上工作。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位开发者", "label": "量词"}, {"form": "一名开发者", "label": "量词"}, {"form": "開發者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从事软件开发、编写程序的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6400fda1-5aa5-4407-a552-0ac0924ed60e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开发者", "is_correct": true, "explanation": "正确。“开发者”指从事软件开发、编写程序的人，符合句中对架构进行解构与重构的语境。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不会对软件架构进行解构与重构，与句子主语的语义不合。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡无法解构与重构架构，与“加速”的语境不符。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语词，与这段书面的技术论述语体不符。"}], "explanations": {"开发者": "正确。“开发者”指从事软件开发、编写程序的人，符合句中对架构进行解构与重构的语境。", "植物": "语义：植物不会对软件架构进行解构与重构，与句子主语的语义不合。", "灯泡": "语义：灯泡无法解构与重构架构，与“加速”的语境不符。", "哥们": "语域：“哥们”是口语词，与这段书面的技术论述语体不符。"}, "sentence_index": 0, "correct_answer": "开发者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的开发者是一位年轻的音乐人。", "explanation": "这里应该用〈作曲家〉。开发者指编写程序的人，不指创作歌曲的人。"}, {"text": "公司刚来了一只开发者，每天负责写代码。", "explanation": "量词用错了。“只”用于动物，开发者是人，应用“位”或“名”。"}, {"text": "这部小说的开发者是一位年轻人。", "explanation": "这里应该用〈作家〉。开发者指编写软件程序的人，不用于写小说的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发者", "is_correct": true, "explanation": "正确。“开发者”指编写程序的人，符合公司招聘技术人员的语境。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是家用电器，不能被“招聘”，与公司招聘人员的语境冲突。"}, {"text": "侠客", "is_correct": false, "explanation": "语域：“侠客”是文学或武侠用语，与公司招聘的日常语体不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被招聘，与句子的语境不符。"}], "explanations": {"开发者": "正确。“开发者”指编写程序的人，符合公司招聘技术人员的语境。", "空调": "语义：空调是家用电器，不能被“招聘”，与公司招聘人员的语境冲突。", "侠客": "语域：“侠客”是文学或武侠用语，与公司招聘的日常语体不符。", "石头": "语义：石头不能被招聘，与句子的语境不符。"}, "sentence_index": 6, "correct_answer": "开发者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里的开发者每天照顾病人。", "explanation": "这里应该用〈护士〉。开发者指编写程序的人，不负责照顾病人。"}, {"text": "公司刚来了一棵开发者，负责写代码。", "explanation": "量词用错了。“棵”用于植物，开发者是人，应用“位”或“名”。"}, {"text": "这所学校的开发者每天都要备课。", "explanation": "这里应该用〈老师〉。开发者指编写程序的人，不从事备课授课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位年轻人每天都在开发者新软件。", "corrected_sentence": "这位年轻人每天都在开发新软件。", "error_description": "词类错误。“开发者”是名词，指人，不能当动词用；此处应用动词“开发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们公司有两开发者。", "corrected_sentence": "他们公司有两位开发者。", "error_description": "量词漏掉。数词“两”后要加量词，应说“两位开发者”，不说“两开发者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
