INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19985, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指品德恶劣、行为不端的人。", "primary_collocate": null, "pronunciation": "huài rén", "ipa": "xwaɪ⁵¹ ɻən³⁵", "syllable_count": 2, "sentences": [{"text": "他有时被坏人用来做坏事。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人偷了老人的钱。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把坏人抓住了。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子，不要跟坏人说话。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来不像坏人。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上有好人，也有坏人。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人总是做坏事，没有好结果。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能相信坏人的话。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是个坏人，现在变好了。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影里的坏人很聪明。", "target_word": "坏人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个坏人", "label": "量词：个"}], "register": "中性", "sense_fingerprint": "品德恶劣、行为不端的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a6cad1-527d-4756-8bdd-654c381daff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坏人", "is_correct": true, "explanation": "正确：“坏人”指品德恶劣的人，能被坏人用来做坏事，符合句意。"}, {"text": "好人", "is_correct": false, "explanation": "语义：“好人”与“用来做坏事”的意思相反，句子说不通。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“用来做坏事”的对象须是能做事的人，猫不能被这样使用。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花”是植物，无法做坏事，与“用来做坏事”矛盾。"}], "explanations": {"坏人": "正确：“坏人”指品德恶劣的人，能被坏人用来做坏事，符合句意。", "好人": "语义：“好人”与“用来做坏事”的意思相反，句子说不通。", "猫": "搭配：“用来做坏事”的对象须是能做事的人，猫不能被这样使用。", "花": "语义：“花”是植物，无法做坏事，与“用来做坏事”矛盾。"}, "sentence_index": 0, "correct_answer": "坏人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上走过一只坏人，吓了我一跳。", "explanation": "这里应该用〈个〉。“只”用于动物，指人要用“个”或“位”。"}, {"text": "那只狗是坏人，见了人就咬。", "explanation": "这里应该用〈凶〉。坏人指做坏事的人，形容狗的性情要说“凶”，狗不能被称作坏人。"}, {"text": "今天的天气是坏人，我们别出去了。", "explanation": "这里应该用〈恶劣〉。坏人指做坏事的人，形容天气不好要说“恶劣”，天气不能被称作坏人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坏人", "is_correct": true, "explanation": "正确：“坏人”指品德恶劣的人，与“总是做坏事”搭配，符合句意。"}, {"text": "善人", "is_correct": false, "explanation": "语义：“善人”指品德好的人，与“总是做坏事”矛盾。"}, {"text": "圣人", "is_correct": false, "explanation": "语义：“圣人”指品德极高的人，与“做坏事”矛盾，且是书面词，口语句子不协调。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：“做坏事”的主语须是人，太阳不能做坏事。"}], "explanations": {"坏人": "正确：“坏人”指品德恶劣的人，与“总是做坏事”搭配，符合句意。", "善人": "语义：“善人”指品德好的人，与“总是做坏事”矛盾。", "圣人": "语义：“圣人”指品德极高的人，与“做坏事”矛盾，且是书面词，口语句子不协调。", "太阳": "搭配：“做坏事”的主语须是人，太阳不能做坏事。"}, "sentence_index": 6, "correct_answer": "坏人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是坏人，打不开了。", "explanation": "这里应该用〈坏的〉（指东西出了故障）。坏人是指做坏事的人的名词，不能用来说电脑。"}, {"text": "村里来了一棵坏人，大家都很害怕。", "explanation": "这里应该用〈个〉。“棵”用于植物，指人要用“个”或“位”。"}, {"text": "这个苹果是坏人，不能吃了。", "explanation": "这里应该用〈坏的〉（指食物变质）。坏人指做坏事的人，不能用来说食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上有一个坏人们在偷东西。", "corrected_sentence": "街上有一个坏人在偷东西。", "error_description": "错误在“们”。“们”表示复数，不能与“一个”这样的单数数量词同用，应删去“们”，说“一个坏人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被一只坏人骗了钱。", "corrected_sentence": "他被一个坏人骗了钱。", "error_description": "错误在量词。“坏人”指人，量词应用“个”。“只”是用于动物的量词，不能用于人。应改为“一个坏人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19986, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好事", "is_correct": true, "explanation": "正确：「好事」与「坏事」为反义词，指好的事情。"}, {"text": "礼物", "is_correct": false, "explanation": "无关：「礼物」指送人的物品，与「坏事」没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：「桌子」是家具，与「坏事」不构成反义。"}, {"text": "天空", "is_correct": false, "explanation": "无关：「天空」指自然景物，与「坏事」不构成反义。"}], "correct_answer": "好事", "explanations": {"好事": "正确：「好事」与「坏事」为反义词，指好的事情。", "礼物": "无关：「礼物」指送人的物品，与「坏事」没有反义关系。", "桌子": "无关：「桌子」是家具，与「坏事」不构成反义。", "天空": "无关：「天空」指自然景物，与「坏事」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19986, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好事", "is_correct": true, "explanation": "正确：「好事」与「坏事」为反义词，指好的事情。"}, {"text": "石头", "is_correct": false, "explanation": "无关：「石头」是矿物，与「坏事」没有反义关系。"}, {"text": "树林", "is_correct": false, "explanation": "无关：「树林」指成片的树木，与「坏事」不构成反义。"}, {"text": "书包", "is_correct": false, "explanation": "无关：「书包」是装东西的用具，与「坏事」不构成反义。"}], "correct_answer": "好事", "explanations": {"好事": "正确：「好事」与「坏事」为反义词，指好的事情。", "石头": "无关：「石头」是矿物，与「坏事」没有反义关系。", "树林": "无关：「树林」指成片的树木，与「坏事」不构成反义。", "书包": "无关：「书包」是装东西的用具，与「坏事」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不好的、有害的事情或行为。", "primary_collocate": null, "pronunciation": "huài shì", "ipa": "xwai˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "比如被坏人用来做坏事。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他从小就不爱做坏事。", "target_word": "坏事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师常说，不能做坏事。", "target_word": "坏事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人做过很多坏事。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子做了坏事，要说对不起。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人不会去做坏事。", "target_word": "坏事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直记着，不能做坏事。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人又做了一件坏事。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在找做坏事的人。", "target_word": "坏事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷告诉我，做坏事一定会后悔。", "target_word": "坏事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "做坏事", "label": "复合"}], "register": "中性", "sense_fingerprint": "坏事：不好的、有害的行为，常说做坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19986, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坏事", "is_correct": true, "explanation": "正确：huài shì，指不好的、有害的事情或行为。"}, {"text": "画室", "is_correct": false, "explanation": "huà 与 huài 韵母不同（少了 -i），意思是画室，与本词不同。"}, {"text": "会是", "is_correct": false, "explanation": "huì 与 huài 韵母不同，「会是」意思是「可能是」，不是坏事。"}, {"text": "坏书", "is_correct": false, "explanation": "shū 与 shì 韵母不同，意思是坏的书，与「坏事」不同。"}], "explanations": {"坏事": "正确：huài shì，指不好的、有害的事情或行为。", "画室": "huà 与 huài 韵母不同（少了 -i），意思是画室，与本词不同。", "会是": "huì 与 huài 韵母不同，「会是」意思是「可能是」，不是坏事。", "坏书": "shū 与 shì 韵母不同，意思是坏的书，与「坏事」不同。"}, "sentence_index": null, "correct_answer": "坏事"}, "level_3": {"options": [{"text": "坏事", "is_correct": true, "explanation": "正确：「被坏人用来做坏事」符合不良行为的语境。"}, {"text": "好事", "is_correct": false, "explanation": "语义：与前文「坏人」矛盾，坏人不会被用来做好事。"}, {"text": "坏话", "is_correct": false, "explanation": "搭配：「做」不搭配「坏话」，应说「说坏话」。"}, {"text": "好人", "is_correct": false, "explanation": "语义：「被坏人用来做好人」语义冲突，与句意不符。"}], "explanations": {"坏事": "正确：「被坏人用来做坏事」符合不良行为的语境。", "好事": "语义：与前文「坏人」矛盾，坏人不会被用来做好事。", "坏话": "搭配：「做」不搭配「坏话」，应说「说坏话」。", "好人": "语义：「被坏人用来做好人」语义冲突，与句意不符。"}, "sentence_index": 0, "correct_answer": "坏事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被法院判了坏事。", "explanation": "这里应该用〈罪〉。法院判的是「罪」，「坏事」不能被「判」，应说「判罪」。"}, {"text": "他每个月都给孤儿院捐钱，做了一件坏事。", "explanation": "这里应该用〈善举〉。捐钱帮助孤儿是善举，「坏事」指不好的行为，不能用来形容善行。"}, {"text": "这次救援行动，他做了件坏事，帮助了很多人。", "explanation": "这里应该用〈好事〉。救人帮人是好事，「坏事」指不好的行为，与句中帮助人的内容矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坏事", "is_correct": true, "explanation": "正确：「不能做坏事」与「一直记着」的劝诫语境相符。"}, {"text": "坏话", "is_correct": false, "explanation": "搭配：「做」不搭配「坏话」，应说「说坏话」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「做天气」没有意义，与句子语境不符。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：「做脸色」指摆脸色给人看，与劝诫「不能做坏事」的语境无关。"}], "explanations": {"坏事": "正确：「不能做坏事」与「一直记着」的劝诫语境相符。", "坏话": "搭配：「做」不搭配「坏话」，应说「说坏话」。", "天气": "语义：「做天气」没有意义，与句子语境不符。", "脸色": "语义：「做脸色」指摆脸色给人看，与劝诫「不能做坏事」的语境无关。"}, "sentence_index": 6, "correct_answer": "坏事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那件坏事抢走了我的钱包。", "explanation": "这里应该用〈坏人〉。能抢东西的是人，「坏事」指事情，不能作施事主语。"}, {"text": "他每天帮奶奶做饭，真是做了一件坏事。", "explanation": "这里应该用〈好事〉。帮奶奶做饭是好的行为，「坏事」指不好的、有害的事情，与句意矛盾。"}, {"text": "他是村里的坏事。", "explanation": "这里应该用〈祸害〉。指人要用「祸害」或「坏人」，「坏事」只指事情，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做了一只坏事，后来很后悔。", "corrected_sentence": "他做了一件坏事，后来很后悔。", "error_description": "量词错误：「坏事」应用量词「件」，「只」用于动物，不用于事情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做坏事人应该受到惩罚。", "corrected_sentence": "做坏事的人应该受到惩罚。", "error_description": "结构错误：修饰性短语「做坏事」后要加「的」，应说「做坏事的人」，不说「做坏事人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
