INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "支持者指在观点、行动或事业上表示赞同、拥护并给予帮助的人。", "primary_collocate": null, "pronunciation": "zhī chí zhě", "ipa": "ʈʂɻ̩˥ ʈʂʰɻ̩˧˥ ʈʂɤ˨˩˧", "syllable_count": 3, "sentences": [{"text": "但支持者认为，只要管理得当，开放的好处远大于风险。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个计划有很多支持者。", "target_word": "支持者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是环保工作的支持者。", "target_word": "支持者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "支持者们在门口等着他。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对者和支持者一起开了会。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "支持者越来越多，大家都很高兴。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师是我们最大的支持者。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的支持者给了他很多帮助。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "支持者认为这个办法很好。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长感谢了所有支持者。", "target_word": "支持者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "支持者们", "label": "复合"}], "register": "中性", "sense_fingerprint": "支持者：赞同并帮助某观点、行动或事业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支持者", "is_correct": true, "explanation": "正确：「支持者认为」中的主语指赞同此观点的人，符合句意。"}, {"text": "风险", "is_correct": false, "explanation": "配价：「认为」的主语须是人，「风险」不能「认为」。"}, {"text": "好处", "is_correct": false, "explanation": "配价：「认为」的主语须是人，「好处」不能作判断的主体。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会「认为」，与句中表达判断的主体相冲突。"}], "explanations": {"支持者": "正确：「支持者认为」中的主语指赞同此观点的人，符合句意。", "风险": "配价：「认为」的主语须是人，「风险」不能「认为」。", "好处": "配价：「认为」的主语须是人，「好处」不能作判断的主体。", "桌子": "语义：桌子不会「认为」，与句中表达判断的主体相冲突。"}, "sentence_index": 0, "correct_answer": "支持者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这次比赛的支持者，正在场上踢球。", "explanation": "这里应该用〈球员〉。支持者是场外表示拥护的人，场上踢球的是球员。"}, {"text": "场上的支持者正在吹哨子，判了对方犯规。", "explanation": "这里应该用〈裁判〉。吹哨判罚的是裁判，「支持者」只是拥护者，不能在场上判罚。"}, {"text": "这个方案的支持者一直在痛骂它，要求立即废除。", "explanation": "这里应该用〈反对者〉。痛骂方案、要求废除的是反对者，支持者应当赞同和拥护这个方案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支持者", "is_correct": true, "explanation": "正确：「这位老师是我们最大的支持者」指拥护我们的人，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」不能指「老师」，句子表达的是人物身份，与之冲突。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「最大的」多修饰人或可比较的事物，「天气」不宜用于此句。"}, {"text": "书包", "is_correct": false, "explanation": "语义：「书包」是物品，不能指「老师」，与句子的人物身份矛盾。"}], "explanations": {"支持者": "正确：「这位老师是我们最大的支持者」指拥护我们的人，符合句意。", "桌子": "语义：「桌子」不能指「老师」，句子表达的是人物身份，与之冲突。", "天气": "搭配：「最大的」多修饰人或可比较的事物，「天气」不宜用于此句。", "书包": "语义：「书包」是物品，不能指「老师」，与句子的人物身份矛盾。"}, "sentence_index": 6, "correct_answer": "支持者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "支持者宣布了所有选举结果。", "explanation": "这里应该用〈选举委员会〉。宣布结果的是负责机构，支持者只是拥护者，不能作此主语。"}, {"text": "市长感谢了那些一直在背后拆台的支持者。", "explanation": "这里应该用〈反对者〉。在背后拆台的是反对者，「支持者」应当站在这边，不会拆台。"}, {"text": "这位支持者在场上踢进了一个球。", "explanation": "这里应该用〈球员〉。场上踢球的是球员，「支持者」只是拥护者，不在场上比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师支持者我们的计划。", "corrected_sentence": "这位老师支持我们的计划。", "error_description": "词性错误：「支持者」是名词，指人，不能带宾语当动词用；这里要用动词「支持」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找了一座支持者，一起去说服领导。", "corrected_sentence": "他找了一位支持者，一起去说服领导。", "error_description": "量词错误：「支持者」指人，应用「位」或「个」，「座」用于山、楼等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19988, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失当", "is_correct": true, "explanation": "失当：处理或言行不合适、不恰当，与“得当”是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：明白、不模糊，与“得当”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速：速度快，与“得当”没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "高大：体形或地位高，与“得当”没有反义关系。"}], "correct_answer": "失当", "explanations": {"失当": "失当：处理或言行不合适、不恰当，与“得当”是反义关系。", "清楚": "清楚：明白、不模糊，与“得当”没有反义关系。", "迅速": "迅速：速度快，与“得当”没有反义关系。", "高大": "高大：体形或地位高，与“得当”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19988, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失当", "is_correct": true, "explanation": "失当：办法不恰当，与“得当”是反义关系。"}, {"text": "缓慢", "is_correct": false, "explanation": "缓慢：速度慢，与“得当”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：有光、亮堂，与“得当”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔：面积大、范围广，与“得当”没有反义关系。"}], "correct_answer": "失当", "explanations": {"失当": "失当：办法不恰当，与“得当”是反义关系。", "缓慢": "缓慢：速度慢，与“得当”没有反义关系。", "明亮": "明亮：有光、亮堂，与“得当”没有反义关系。", "宽阔": "宽阔：面积大、范围广，与“得当”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19988, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指行为、言语或处理方法合适、恰当。", "primary_collocate": null, "pronunciation": "dé dàng", "ipa": "tɤ˧˥ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "但支持者认为，只要管理得当，开放的好处远大于风险。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他处理这件事很得当。", "target_word": "得当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话很得当。", "target_word": "得当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次的安排很得当。", "target_word": "得当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用词得当，句子就好懂。", "target_word": "得当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理的做法得当，大家都同意。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她处理问题得当，没有吵架。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对客人的态度很得当。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样回答很得当。", "target_word": "得当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办法得当，事情很快做完了。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处理得当", "label": "复合"}, {"form": "应对得当", "label": "复合"}], "register": "书面", "sense_fingerprint": "得当：行为、言语或处理方法合适恰当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得当", "is_correct": true, "explanation": "得当：管理的方法合适恰当，与后句“好处远大于风险”构成条件关系。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：“管理混乱”与“只要……好处远大于风险”的条件相悖，不能成立。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”指做事不认真、不周密，与“好处远大于风险”的前提矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：「粗糙」指管理不精细，与「只要管理…」的前提相悖，句子论证不成立。"}], "explanations": {"得当": "得当：管理的方法合适恰当，与后句“好处远大于风险”构成条件关系。", "混乱": "语义：“管理混乱”与“只要……好处远大于风险”的条件相悖，不能成立。", "草率": "语义：“草率”指做事不认真、不周密，与“好处远大于风险”的前提矛盾。", "粗糙": "语义：「粗糙」指管理不精细，与「只要管理…」的前提相悖，句子论证不成立。"}, "sentence_index": 0, "correct_answer": "得当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的身高很得当。", "explanation": "这里应该用〈正常〉。得当形容做事、说话的方式，身高这类身体状况要用正常。"}, {"text": "这块石头的重量很得当。", "explanation": "这里应该用〈适中〉。得当形容做事、说话的分寸，重量、数量的程度要用适中。"}, {"text": "这间屋子的温度很得当。", "explanation": "这里应该用〈适宜〉。得当不用于环境条件，温度、湿度等要用适宜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得当", "is_correct": true, "explanation": "得当：处理问题恰当，所以没有发生争吵。"}, {"text": "激烈", "is_correct": false, "explanation": "语义：“激烈”指冲突猛烈，与“没有吵架”矛盾。"}, {"text": "冲动", "is_correct": false, "explanation": "搭配：“冲动”多修饰人或行为，“处理问题冲动”不自然，且与“没有吵架”不合。"}, {"text": "粗暴", "is_correct": false, "explanation": "语义：“粗暴”指态度蛮横，容易引发争吵，与“没有吵架”相反。"}], "explanations": {"得当": "得当：处理问题恰当，所以没有发生争吵。", "激烈": "语义：“激烈”指冲突猛烈，与“没有吵架”矛盾。", "冲动": "搭配：“冲动”多修饰人或行为，“处理问题冲动”不自然，且与“没有吵架”不合。", "粗暴": "语义：“粗暴”指态度蛮横，容易引发争吵，与“没有吵架”相反。"}, "sentence_index": 6, "correct_answer": "得当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的口语能力很得当。", "explanation": "这里应该用〈强〉。得当形容行为、言语或办法合适，能力、水平的高低要用强。"}, {"text": "这次考试的成绩很得当。", "explanation": "这里应该用〈理想〉。得当指做法合适，成绩的好坏要用理想。"}, {"text": "她的性格很得当。", "explanation": "这里应该用〈开朗〉。得当只用于做事、说话的方式，性格要用开朗之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他安排得当得，大家都很满意。", "corrected_sentence": "他安排得当，大家都很满意。", "error_description": "多字错误：「得当」后多出一个「得」，「得当得」不成词，应删去多余的「得」，说「安排得当」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她处理问题很得当得，大家都服她。", "corrected_sentence": "她处理问题很得当，大家都服她。", "error_description": "多字错误：「得当」后多出一个「得」，「得当得」不成词，应删去多余的「得」，说「很得当」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
