INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示数量或程度上远远超过比较的对象。", "primary_collocate": null, "pronunciation": "yuǎn dà yú", "ipa": "ɥɛn˨˩˦ ta˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "但支持者认为，只要管理得当，开放的好处远大于风险。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家公司的收入远大于支出。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的收获远大于付出的努力。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的好处远大于坏处。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的影响力远大于其他人。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实际困难远大于我们的想象。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的难度远大于上次。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的游客人数远大于去年。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习外语的收益远大于成本。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划带来的价值远大于它的费用。", "target_word": "远大于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远远大于", "label": "强调形式"}], "register": "书面", "sense_fingerprint": "数量或程度上远远超过比较对象，多用于抽象比较（好处、收益、影响等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19989, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远大于", "is_correct": true, "explanation": "远大于：好处远远超过风险，与“只要管理得当”的积极论证一致。"}, {"text": "小于", "is_correct": false, "explanation": "语义：“小于”说好处比风险少，与“只要管理得当”的前提和论证方向相反。"}, {"text": "远逊于", "is_correct": false, "explanation": "语义：“远逊于”指远不如，与前句对开放的积极判断相反。"}, {"text": "等于", "is_correct": false, "explanation": "语义：「等于」表示二者相当，与「好处远大于风险」的论证相悖，不能承接。"}], "explanations": {"远大于": "远大于：好处远远超过风险，与“只要管理得当”的积极论证一致。", "小于": "语义：“小于”说好处比风险少，与“只要管理得当”的前提和论证方向相反。", "远逊于": "语义：“远逊于”指远不如，与前句对开放的积极判断相反。", "等于": "语义：「等于」表示二者相当，与「好处远大于风险」的论证相悖，不能承接。"}, "sentence_index": 0, "correct_answer": "远大于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的长度远大于它的作者。", "explanation": "这里误把〈远大于〉当作“差别悬殊”来用。它只比较同类事物的数量或程度，诗的长度与作者不是同类的量，无法比较大小。"}, {"text": "他的年龄远大于他的鞋码。", "explanation": "这里误把〈远大于〉当作“差别悬殊”来用。它只比较同类事物的数量或程度，年龄与鞋码不是同类的量，无法比较大小。"}, {"text": "这次演出的票价远大于它的座位。", "explanation": "这里误把〈远大于〉当作“差别悬殊”来用。它只比较同类事物的数量或程度，票价与座位不是同类的量，无法比较大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远大于", "is_correct": true, "explanation": "远大于：难度远远超过上次，与句意相符。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离”指距离变远，不能用来比较难度的高低。"}, {"text": "远眺", "is_correct": false, "explanation": "搭配：“远眺”的对象是风景或远处的地点，不能用于“难度”。"}, {"text": "远航", "is_correct": false, "explanation": "搭配：“远航”指船只或人远行，不能作“难度”的谓语。"}], "explanations": {"远大于": "远大于：难度远远超过上次，与句意相符。", "远离": "语义：“远离”指距离变远，不能用来比较难度的高低。", "远眺": "搭配：“远眺”的对象是风景或远处的地点，不能用于“难度”。", "远航": "搭配：“远航”指船只或人远行，不能作“难度”的谓语。"}, "sentence_index": 6, "correct_answer": "远大于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的颜色远大于它的价格。", "explanation": "这里误把〈远大于〉当作“格外突出”来用。颜色与价格不是同类的量，无法比较大小。"}, {"text": "这首歌的旋律远大于它的节奏。", "explanation": "这里误把〈远大于〉当作“某一方面格外突出”来用。旋律与节奏不是同类的量，无法比较大小。"}, {"text": "他的笑容远大于那张桌子的温度。", "explanation": "这里误把〈远大于〉当作“格外显眼”来用。笑容与温度不是同类的量，无法比较大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项投资的收益远大于。", "corrected_sentence": "这项投资的收益远大于成本。", "error_description": "错误形式“远大于。”；正确形式“远大于成本”。“远大于”是动词，后面必须带比较的对象，漏掉“成本”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划的收益很远大于成本。", "corrected_sentence": "这个计划的收益远大于成本。", "error_description": "错误位置：多出了副词“很”。“远”本身已表示程度，前面不能再加“很”，应说“远大于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19990, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
