INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19990, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指值得相信、值得信赖的。", "primary_collocate": null, "pronunciation": "kě xìn", "ipa": "kʰɤ˨˩˦ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他们相信，通过合作，可以让AI更透明、更公平、更可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个消息来自官方，很可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话听起来一点也不可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家的意见比网上的传言更可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告的数据真实可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个诚实的人，说的话很可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事太夸张，一点都不可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认为这个证据不够可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这家店的评价比较可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友告诉我的消息，我觉得可信。", "target_word": "可信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可信", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "消息、证据、人等值得信赖，可作谓语或定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可信", "is_correct": true, "explanation": "正确答案：可信（kěxìn），指值得相信。"}, {"text": "可心", "is_correct": false, "explanation": "可心（kěxīn）与可信只差第二个音节的声调：「心」为第一声，「信」为第四声。可心意思是称心、合意。"}, {"text": "可行", "is_correct": false, "explanation": "可行（kěxíng）第二个音节的韵母为 íng，与可信的 ìn 不同，意思是行得通、能实施。"}, {"text": "口信", "is_correct": false, "explanation": "口信（kǒuxìn）第一个音节的韵母为 ou，与可（kě）的 e 不同，意思是口头传达的消息。"}], "explanations": {"可信": "正确答案：可信（kěxìn），指值得相信。", "可心": "可心（kěxīn）与可信只差第二个音节的声调：「心」为第一声，「信」为第四声。可心意思是称心、合意。", "可行": "可行（kěxíng）第二个音节的韵母为 íng，与可信的 ìn 不同，意思是行得通、能实施。", "口信": "口信（kǒuxìn）第一个音节的韵母为 ou，与可（kě）的 e 不同，意思是口头传达的消息。"}, "sentence_index": null, "correct_answer": "可信"}, "level_3": {"options": [{"text": "可信", "is_correct": true, "explanation": "正确答案：“可信”指值得相信，句中形容AI值得信赖，与“更透明、更公平”的正面语境相符。"}, {"text": "可疑", "is_correct": false, "explanation": "语义：“可疑”指令人怀疑，与“更透明、更公平”的正面要求相反，说AI“更可疑”不通。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”形容反应慢，不能用来形容AI的透明程度与公平程度。"}, {"text": "好笑", "is_correct": false, "explanation": "搭配：“好笑”修饰可笑的人或事，不能修饰“透明”“公平”这类抽象品质。"}], "explanations": {"可信": "正确答案：“可信”指值得相信，句中形容AI值得信赖，与“更透明、更公平”的正面语境相符。", "可疑": "语义：“可疑”指令人怀疑，与“更透明、更公平”的正面要求相反，说AI“更可疑”不通。", "迟钝": "语义：“迟钝”形容反应慢，不能用来形容AI的透明程度与公平程度。", "好笑": "搭配：“好笑”修饰可笑的人或事，不能修饰“透明”“公平”这类抽象品质。"}, "sentence_index": 0, "correct_answer": "可信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新冰箱很可信，三年来从没坏过。", "explanation": "这里应该用〈可靠〉。“可信”用于消息、话语等，机器设备的稳定性要用“可靠”。"}, {"text": "他的歌声很可信，大家都听得很感动。", "explanation": "这里应该用〈动听〉。“可信”用于消息、说法，不用来形容歌声。"}, {"text": "这座桥很可信，车辆都能安全通过。", "explanation": "这里应该用〈牢固〉。“可信”说的是值得相信，桥梁的结实程度要用“牢固”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可信", "is_correct": true, "explanation": "正确答案：“可信”与“一点都不”搭配，说明故事的真实性不高。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”形容速度，与“故事太夸张”所说的真实程度无关，句子说不通。"}, {"text": "宽广", "is_correct": false, "explanation": "搭配：“宽广”形容空间或范围，不能用来形容故事。"}, {"text": "灵巧", "is_correct": false, "explanation": "搭配：“灵巧”形容人或手工动作的敏捷，不能修饰“故事”。"}], "explanations": {"可信": "正确答案：“可信”与“一点都不”搭配，说明故事的真实性不高。", "迅速": "语义：“迅速”形容速度，与“故事太夸张”所说的真实程度无关，句子说不通。", "宽广": "搭配：“宽广”形容空间或范围，不能用来形容故事。", "灵巧": "搭配：“灵巧”形容人或手工动作的敏捷，不能修饰“故事”。"}, "sentence_index": 6, "correct_answer": "可信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是一名很可信的舞者，动作非常精彩。", "explanation": "这里应该用〈出色〉。“可信”说的是值得相信，形容一个人的能力要用“出色”。"}, {"text": "这辆车很可信，开了十年都没出过毛病。", "explanation": "这里应该用〈可靠〉。“可信”用于消息、话语、证据等，车辆性能稳定要用“可靠”。"}, {"text": "这间房子很可信，阳光充足又安静。", "explanation": "这里应该用〈舒适〉。“可信”不用于描述房屋的居住感受，要用“舒适”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息没可信。", "corrected_sentence": "这个消息不可信。", "error_description": "错误在“没”：形容词“可信”的否定要用“不”，不能用“没”。应改为“这个消息不可信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个可信得人。", "corrected_sentence": "他是个可信的人。", "error_description": "错误在「得」：修饰名词时应用结构助词「的」，「得」只用于补语，不能作定语，应说「可信的人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
