INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19991, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示到达某个地点、时间或状态。", "primary_collocate": null, "pronunciation": "dào", "ipa": "taʊ˥˩", "syllable_count": 1, "sentences": [{"text": "我每天走到学校。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天工作到晚上十点。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路可以一直走到海边。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡到十点才起床。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从一楼跑到五楼。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐车坐到北京站。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音大到隔壁都能听见。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨一直下到下午三点。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书送到我家了。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我们学到第五课。", "target_word": "到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到了", "label": "体标"}, {"form": "直到", "label": "复合"}], "register": "中性", "sense_fingerprint": "到：放在动词或形容词后作补语，表示动作达到某地、某时或某种程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19991, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到", "is_correct": true, "explanation": "正确答案：到（dào），结果补语，表示动作达到某个地点、时间或状态。"}, {"text": "刀", "is_correct": false, "explanation": "刀（dāo）与到（dào）声调不同（第一声／第四声），意思是“刀子”。"}, {"text": "岛", "is_correct": false, "explanation": "岛（dǎo）与到（dào）声调不同（第三声／第四声），意思是“岛屿”。"}, {"text": "套", "is_correct": false, "explanation": "套（tào）与到（dào）声母不同（t／d），声调相同，意思是“套子”。"}], "explanations": {"到": "正确答案：到（dào），结果补语，表示动作达到某个地点、时间或状态。", "刀": "刀（dāo）与到（dào）声调不同（第一声／第四声），意思是“刀子”。", "岛": "岛（dǎo）与到（dào）声调不同（第三声／第四声），意思是“岛屿”。", "套": "套（tào）与到（dào）声母不同（t／d），声调相同，意思是“套子”。"}, "sentence_index": null, "correct_answer": "到"}, "level_3": {"options": [{"text": "到", "is_correct": true, "explanation": "到作结果补语，表示走的动作达到学校，与“我每天走”的语境相符。"}, {"text": "完", "is_correct": false, "explanation": "语义：“完”表示完成或走尽，与“走到学校”的到达义不合。"}, {"text": "好", "is_correct": false, "explanation": "搭配：“好”作补语表示完成或妥当，“走好学校”不能成立。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”表示停止或稳固，不能表示走到某处，“走住学校”不通。"}], "explanations": {"到": "到作结果补语，表示走的动作达到学校，与“我每天走”的语境相符。", "完": "语义：“完”表示完成或走尽，与“走到学校”的到达义不合。", "好": "搭配：“好”作补语表示完成或妥当，“走好学校”不能成立。", "住": "搭配：“住”表示停止或稳固，不能表示走到某处，“走住学校”不通。"}, "sentence_index": 0, "correct_answer": "到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把衣服洗到了。", "explanation": "这里应该用〈好〉。到表示到达，表示衣服洗完要用“洗好”，应说“我把衣服洗好了”。"}, {"text": "我把钱借到他。", "explanation": "这里应该用〈给〉。到表示到达某处，把东西交付他人要用“给”，应说“我把钱借给他”。"}, {"text": "他把门关到了。", "explanation": "这里应该用〈上〉。到表示到达，关门要用“关上”，应说“他把门关上了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19991, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "到", "is_correct": true, "explanation": "正确答案：到（dào），结果补语，表示动作达到某个地点、时间或状态。"}, {"text": "刀", "is_correct": false, "explanation": "刀（dāo）与到（dào）声调不同（第一声／第四声），意思是“刀子”。"}, {"text": "导", "is_correct": false, "explanation": "导（dǎo）与到（dào）声调不同（第三声／第四声），意思是“引导”。"}, {"text": "讨", "is_correct": false, "explanation": "讨（tǎo）与到（dào）声母、声调都不同，听感相近，意思是“讨论”。"}], "explanations": {"到": "正确答案：到（dào），结果补语，表示动作达到某个地点、时间或状态。", "刀": "刀（dāo）与到（dào）声调不同（第一声／第四声），意思是“刀子”。", "导": "导（dǎo）与到（dào）声调不同（第三声／第四声），意思是“引导”。", "讨": "讨（tǎo）与到（dào）声母、声调都不同，听感相近，意思是“讨论”。"}, "sentence_index": null, "correct_answer": "到"}, "level_3": {"options": [{"text": "到", "is_correct": true, "explanation": "到作结果补语，表示声音大到能让隔壁听见的程度，与句意相符。"}, {"text": "透", "is_correct": false, "explanation": "搭配：“透”表示透彻，不能接在“大”后表示程度，“声音大透”不通。"}, {"text": "烂", "is_correct": false, "explanation": "搭配：“烂”表示腐坏，不能接在“大”后表示程度，“声音大烂”不通。"}, {"text": "坏", "is_correct": false, "explanation": "语义：“坏”表示不好的结果，与“隔壁都能听见”的程度义不合。"}], "explanations": {"到": "到作结果补语，表示声音大到能让隔壁听见的程度，与句意相符。", "透": "搭配：“透”表示透彻，不能接在“大”后表示程度，“声音大透”不通。", "烂": "搭配：“烂”表示腐坏，不能接在“大”后表示程度，“声音大烂”不通。", "坏": "语义：“坏”表示不好的结果，与“隔壁都能听见”的程度义不合。"}, "sentence_index": 6, "correct_answer": "到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从老师那里到了这本书。", "explanation": "这里应该用〈拿〉。到表示到达，获得东西要用“拿到”，应说“我从老师那里拿到了这本书”。"}, {"text": "他到了一个电话。", "explanation": "这里应该用〈接〉。到表示到达，不能带“电话”作宾语，应说“他接了一个电话”或“接到一个电话”。"}, {"text": "我们今天听到第五课。", "explanation": "这里应该用〈学〉。“听到”表示听见，不能用来说学习进度；应说“学到第五课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直走了到海边。", "corrected_sentence": "他一直走到了海边。", "error_description": "“了”应放在结果补语“到”之后，表示完成，应说“走到了海边”。“走了到海边”把了放在动词与补语之间，语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河一直到流大海。", "corrected_sentence": "这条河一直流到大海。", "error_description": "错误：“这条河一直到流大海”。正确：“这条河一直流到大海”。结果补语“到”应紧跟在动词“流”之后，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
