INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把内在的能力、特点或思想充分表现出来。", "primary_collocate": null, "pronunciation": "fā huī", "ipa": "fa˥ xwei˥", "syllable_count": 2, "sentences": [{"text": "虽然现在还有挑战，但很多专家认为，开源模式将在其中发挥重要作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他在比赛中发挥得很好。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家发挥自己的想象力。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员充分发挥了自己的才能。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李考试时没有发挥好。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让孩子们发挥创意。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队发挥出了真正的水平。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老板会让员工发挥长处。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的特点发挥得很充分。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要发挥自己的优势。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发挥了", "label": "完成体"}, {"form": "发挥着", "label": "持续体"}, {"form": "发挥过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "充分表现出自己的能力、特长、水平或想象力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47fde9d4-8425-4c39-a479-f50644aa2214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发挥", "is_correct": true, "explanation": "正确答案：“发挥”与“重要作用”搭配，表示产生效果。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多用于能量、资源，“作用”不能被消耗，与“重要作用”搭配不当。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”指拿回，与“开源模式将在其中……重要作用”的语义不合。"}, {"text": "扣除", "is_correct": false, "explanation": "语义：“扣除”指减去，“重要作用”不能被扣除，句子说不通。"}], "explanations": {"发挥": "正确答案：“发挥”与“重要作用”搭配，表示产生效果。", "消耗": "搭配：“消耗”多用于能量、资源，“作用”不能被消耗，与“重要作用”搭配不当。", "收回": "语义：“收回”指拿回，与“开源模式将在其中……重要作用”的语义不合。", "扣除": "语义：“扣除”指减去，“重要作用”不能被扣除，句子说不通。"}, "sentence_index": 0, "correct_answer": "发挥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爱迪生发挥了电灯。", "explanation": "这里应该用〈发明〉。“发挥”指充分表现已有的能力，表示创造出新事物要用“发明”。"}, {"text": "中国经济发挥得很快。", "explanation": "这里应该用〈发展〉。“发挥”指表现能力，描述经济、事业的进步要用“发展”。"}, {"text": "他把心里的不满发挥了出来。", "explanation": "这里应该用〈发泄〉。“发挥”指充分表现能力、特点，宣泄不满、情绪要用“发泄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发挥", "is_correct": true, "explanation": "正确答案：“发挥出”表示充分表现出来，与“真正的水平”相符。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：“浪费”不能与“出了”组合表示展现，“真正的水平”也不会被浪费。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“真正的水平”应有的展现之义相反，句子说不通。"}, {"text": "耗尽", "is_correct": false, "explanation": "配价：“耗尽”不能带“水平”作宾语，也无法与“出了”搭配。"}], "explanations": {"发挥": "正确答案：“发挥出”表示充分表现出来，与“真正的水平”相符。", "浪费": "搭配：“浪费”不能与“出了”组合表示展现，“真正的水平”也不会被浪费。", "隐藏": "语义：“隐藏”与“真正的水平”应有的展现之义相反，句子说不通。", "耗尽": "配价：“耗尽”不能带“水平”作宾语，也无法与“出了”搭配。"}, "sentence_index": 6, "correct_answer": "发挥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你要发挥自己的缺点。", "explanation": "这里应该用〈克服〉。“发挥”只用于能力、优势等正面的东西，缺点要用“克服”。"}, {"text": "你要发挥自己的问题。", "explanation": "这里应该用〈解决〉。“发挥”用于能力、特长，问题要用“解决”。"}, {"text": "这件事让我发挥了很大的压力。", "explanation": "这里应该用〈承受〉。“发挥”用于能力、才能，压力要用“承受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她今天状态好，把发挥得很出色。", "corrected_sentence": "她今天状态好，发挥得很出色。", "error_description": "错误在「把」：「把」字句要有处置对象，「把发挥得」缺少宾语，应去掉「把」，说「发挥得很出色」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我要充分发挥了自己的优势。", "corrected_sentence": "我要充分发挥自己的优势。", "error_description": "错误在“了”：“要”表示意愿或将来，句中已有“要”，不能再加“了”，应说“我要充分发挥自己的优势”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c3f5fa8-bceb-48bf-a01e-53c7073abd69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
