INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "共同相处，彼此在一起生活或工作。", "primary_collocate": null, "pronunciation": "gòng chǔ", "ipa": "kʊŋ˥˩ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这不仅改变了技术的发展方式，也可能改变我们与AI共处的方式。", "target_word": "共处", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我们要学会和不同的人共处。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人和自然应该和平共处。", "target_word": "共处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在一个小房子里共处了三年。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "室友之间要互相帮助，才能好好共处。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子和祖父母共处得很愉快。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里新人和老同事共处得很好。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我跟他共处过一段时间，知道他很细心。", "target_word": "共处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家希望能长期和平共处。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和同学共处时，要尊重对方的习惯。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "和平共处", "label": "复合"}, {"form": "共处过", "label": "体标"}], "register": "中性", "sense_fingerprint": "共处·人与人或人与事物彼此相处、共同生活工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共处", "is_correct": true, "explanation": "共处：指人与人或人与事物长期相互相处，与“与AI……的方式”搭配自然。"}, {"text": "施肥", "is_correct": false, "explanation": "语义：施肥是给植物或土地加肥料，AI不能被施肥，句子不通。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指烤面包、饼干等食物，不能用来描述人与AI的关系。"}, {"text": "装订", "is_correct": false, "explanation": "配价：装订的对象是纸张、书本等，不能说“与AI装订”。"}], "explanations": {"共处": "共处：指人与人或人与事物长期相互相处，与“与AI……的方式”搭配自然。", "施肥": "语义：施肥是给植物或土地加肥料，AI不能被施肥，句子不通。", "烘焙": "语义：烘焙指烤面包、饼干等食物，不能用来描述人与AI的关系。", "装订": "配价：装订的对象是纸张、书本等，不能说“与AI装订”。"}, "sentence_index": 0, "correct_answer": "共处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在车站共处，聊了很久。", "explanation": "这里应该用〈相遇〉。共处强调长时间一起生活或工作，偶然碰面聊天要用相遇。"}, {"text": "两国军队在边境共处了三天，谁也不肯退让。", "explanation": "这里应该用〈对峙〉。共处表示和睦地待在一起，双方相持不下时要用对峙。"}, {"text": "两家企业共处了五年，抢了无数客户。", "explanation": "这里应该用〈竞争〉。共处表示和睦地相处，互相争抢客户要说竞争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共处", "is_correct": true, "explanation": "共处：“共处得很好”指人与人在一起相处融洽，符合句意。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵指面团、食物的变化过程，不能用来描述人际关系。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：砍伐指砍树木，不能用来形容人与人的关系。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：登记指办理手续，不能说“新人和老同事登记得很好”。"}], "explanations": {"共处": "共处：“共处得很好”指人与人在一起相处融洽，符合句意。", "发酵": "语义：发酵指面团、食物的变化过程，不能用来描述人际关系。", "砍伐": "语义：砍伐指砍树木，不能用来形容人与人的关系。", "登记": "搭配：登记指办理手续，不能说“新人和老同事登记得很好”。"}, "sentence_index": 6, "correct_answer": "共处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们共处了一段路，然后各自回家。", "explanation": "这里应该用〈同行〉。共处强调长时间在一起生活或工作，只一起走一段路要说同行。"}, {"text": "两家公司为了市场共处得很激烈。", "explanation": "这里应该用〈争夺〉。共处表示和睦地相处，不能用来形容为抢占市场的激烈竞争。"}, {"text": "他一个人共处了三年，从不和别人来往。", "explanation": "这里应该用〈独处〉。共处指多人一起相处，一个人待着要说独处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个孩子共处地很融洽。", "corrected_sentence": "两个孩子共处得很融洽。", "error_description": "“共处”后面的程度补语要用“得”，不能用“地”。正确：共处得很融洽；错误：共处地很融洽。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对室友共处得很愉快。", "corrected_sentence": "我跟室友共处得很愉快。", "error_description": "与人共同相处要用“跟”或“和”引出对象，“对”表示对待，不能和“共处”搭配。正确：跟室友共处；错误：对室友共处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "渺小", "is_correct": true, "explanation": "渺小与宏大互为反义，指规模小、气势弱，与“场面宏大”相对。"}, {"text": "精巧", "is_correct": false, "explanation": "精巧指精细灵巧，与规模或气势无关，不是宏大的反义词。"}, {"text": "轻盈", "is_correct": false, "explanation": "轻盈指轻快灵活，与规模和气势无关，不构成反义。"}, {"text": "甜美", "is_correct": false, "explanation": "甜美形容声音、味道或笑容，与规模、气势无关，不构成反义。"}], "correct_answer": "渺小", "explanations": {"渺小": "渺小与宏大互为反义，指规模小、气势弱，与“场面宏大”相对。", "精巧": "精巧指精细灵巧，与规模或气势无关，不是宏大的反义词。", "轻盈": "轻盈指轻快灵活，与规模和气势无关，不构成反义。", "甜美": "甜美形容声音、味道或笑容，与规模、气势无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "渺小", "is_correct": true, "explanation": "渺小与宏大互为反义，指规模小、气势弱，与“很大”相对。"}, {"text": "酸涩", "is_correct": false, "explanation": "酸涩形容味道或心情，与宏大的规模或气势无关，不构成反义。"}, {"text": "浅显", "is_correct": false, "explanation": "浅显指容易理解，与宏大的规模或气势无关。"}, {"text": "柔弱", "is_correct": false, "explanation": "柔弱指柔和而软弱，与宏大的规模或气势不构成反义。"}], "correct_answer": "渺小", "explanations": {"渺小": "渺小与宏大互为反义，指规模小、气势弱，与“很大”相对。", "酸涩": "酸涩形容味道或心情，与宏大的规模或气势无关，不构成反义。", "浅显": "浅显指容易理解，与宏大的规模或气势无关。", "柔弱": "柔弱指柔和而软弱，与宏大的规模或气势不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容规模、范围、气势等非常大。", "primary_collocate": null, "pronunciation": "hóng dà", "ipa": "xʊŋ˧˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "在当代人工智能发展的宏大叙事中，开源自主AI代理的崛起正重新定义技术演进的边界。", "target_word": "宏大", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个计划很宏大，需要很多人一起做。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个宏大的梦想，想让全国的孩子都读书。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的场面宏大，让人难忘。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐的气势宏大，大厅里很安静。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座新城的规模宏大，路也很宽。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一个宏大的故事，从古代说到现在。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工程太宏大了，十年也做不完。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，宏大的目标要一步一步实现。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园的建筑群非常宏大。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宏大的", "label": "结构助词"}, {"form": "宏大叙事", "label": "复合"}], "register": "书面", "sense_fingerprint": "规模、范围、气势非常大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宏大", "is_correct": true, "explanation": "宏大修饰“叙事”，构成“宏大叙事”，指规模和气势都很大的叙述框架，与句中的技术演进语境相符。"}, {"text": "渺小", "is_correct": false, "explanation": "语义：渺小指微不足道，与“崛起”“重新定义技术演进的边界”的宏大语境相反。"}, {"text": "简陋", "is_correct": false, "explanation": "搭配：简陋多用于房屋、设施等实物，不用来修饰“叙事”。"}, {"text": "老旧", "is_correct": false, "explanation": "语义：老旧表示陈旧，与“当代”“崛起”“重新定义”的语境相矛盾。"}], "explanations": {"宏大": "宏大修饰“叙事”，构成“宏大叙事”，指规模和气势都很大的叙述框架，与句中的技术演进语境相符。", "渺小": "语义：渺小指微不足道，与“崛起”“重新定义技术演进的边界”的宏大语境相反。", "简陋": "搭配：简陋多用于房屋、设施等实物，不用来修饰“叙事”。", "老旧": "语义：老旧表示陈旧，与“当代”“崛起”“重新定义”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "宏大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的人口很宏大。", "explanation": "这里应该用〈庞大〉。宏大用于规模、范围、气势等，人口、人数这类数量要用庞大。"}, {"text": "他是一位宏大的科学家，获得了很多奖。", "explanation": "这里应该用〈伟大〉。宏大形容规模或气势，不用来评价人的贡献与品格，称赞人物要用伟大。"}, {"text": "这双鞋很宏大，穿着走路很舒服。", "explanation": "这里应该用〈宽大〉。宏大指规模很大，鞋子、衣服的宽松要用宽大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宏大", "is_correct": true, "explanation": "宏大修饰“故事”，表示故事的范围广、跨度大，与“从古代说到现在”相符。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：短暂指时间很短，与“从古代说到现在”的时间跨度矛盾。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：狭窄多用于空间，不用来形容故事的范围。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清形容场所或气氛，不用来修饰故事。"}], "explanations": {"宏大": "宏大修饰“故事”，表示故事的范围广、跨度大，与“从古代说到现在”相符。", "短暂": "语义：短暂指时间很短，与“从古代说到现在”的时间跨度矛盾。", "狭窄": "搭配：狭窄多用于空间，不用来形容故事的范围。", "冷清": "搭配：冷清形容场所或气氛，不用来修饰故事。"}, "sentence_index": 6, "correct_answer": "宏大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次事故造成了宏大的损失。", "explanation": "这里应该用〈巨大〉。宏大指规模、范围很大，损失、压力这类程度上的大要用巨大。"}, {"text": "这项政策受到了宏大群众的欢迎。", "explanation": "这里应该用〈广大〉。宏大不用来修饰人群，指人多、范围广要用广大。"}, {"text": "他犯了一个宏大的错误，大家都很失望。", "explanation": "这里应该用〈重大〉。宏大形容规模、范围或气势，不修饰错误、事件的严重程度，这类要用重大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项改革的规模非常宏大过，影响了全国。", "corrected_sentence": "这项改革的规模非常宏大，影响了全国。", "error_description": "体标错误：形容词“宏大”后不能加动态助词“过”，应删去“过”，说“规模非常宏大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动办地很宏大，来了很多人。", "corrected_sentence": "这次活动办得很宏大，来了很多人。", "error_description": "错误：补语前应用“得”而不是“地”。“地”用于修饰动词，“办得很宏大”的“得”引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
