INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19995, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫做，名称是。", "primary_collocate": null, "pronunciation": "míng wéi", "ipa": "miŋ˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我们学校有一个名为“书海”的图书馆。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本名为《春天》的小说。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口有一条名为“清水”的小河。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李养了一只名为“黑豆”的狗。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖一种名为“雪梨膏”的饮料。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上正在演一部名为《回家》的电影。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们去了一个名为“白云山”的地方。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司推出了一个名为“学习通”的新软件。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听过一首名为《故乡》的老歌。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上住着一位名为“老林”的老人。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名為", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "放在名词前，介绍人或事物的名称，常见于「名为X的Y」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19995, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名为", "is_correct": true, "explanation": "名为修饰“图书馆”，说明它的名称是“书海”。"}, {"text": "借阅", "is_correct": false, "explanation": "搭配：借阅的对象是书籍，不能用来修饰“图书馆”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：参观是去看某个场所的动作，不能用来说明图书馆叫什么。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美表示称颂的态度，与说明名称无关。"}], "explanations": {"名为": "名为修饰“图书馆”，说明它的名称是“书海”。", "借阅": "搭配：借阅的对象是书籍，不能用来修饰“图书馆”。", "参观": "搭配：参观是去看某个场所的动作，不能用来说明图书馆叫什么。", "赞美": "语义：赞美表示称颂的态度，与说明名称无关。"}, "sentence_index": 0, "correct_answer": "名为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛名为三天，每天都很热闹。", "explanation": "这里应该用〈持续〉。名为表示名称是什么，不表示时间长短，说持续多久要用持续。"}, {"text": "学校每周都名为一次家长会。", "explanation": "这里应该用〈召开〉。名为只说明名称是什么，不表示举行活动，召开会议要说召开。"}, {"text": "我们给这只猫名为“小白”。", "explanation": "这里应该用〈取名为〉。给事物起名要说“取名为”，名为不能接在“给……”之后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名为", "is_correct": true, "explanation": "名为修饰“地方”，说明地方的名称是“白云山”。"}, {"text": "放映", "is_correct": false, "explanation": "语义：放映是播放影片的动作，与“地方”的名称无关。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是器物，不能用来修饰“地方”。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：翻译的对象是语言文字，不能用来说明地方的名称。"}], "explanations": {"名为": "名为修饰“地方”，说明地方的名称是“白云山”。", "放映": "语义：放映是播放影片的动作，与“地方”的名称无关。", "修理": "搭配：修理的对象是器物，不能用来修饰“地方”。", "翻译": "搭配：翻译的对象是语言文字，不能用来说明地方的名称。"}, "sentence_index": 6, "correct_answer": "名为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在山上大声名为老林。", "explanation": "这里应该用〈叫〉（呼唤）。名为只说明名称，不表示大声呼唤某人。"}, {"text": "我们都名为她“小林”。", "explanation": "这里应该用〈称为〉。称呼某人为某名要说“称她为”，名为不能带人作对象。"}, {"text": "那位老人的名字名为“老林”。", "explanation": "这里应该用〈是〉。名为已包含“名字是”的意思，前面再加“名字”就重复了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅名为了“海鲜楼”，很多人都来吃饭。", "corrected_sentence": "这家餐厅名为“海鲜楼”，很多人都来吃饭。", "error_description": "错误：“名为”后面不加“了”。“名为”是说明名称的动词，不表示动作完成，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天在书店买到一本名为《夜航》小说。", "corrected_sentence": "我昨天在书店买到一本名为《夜航》的小说。", "error_description": "错误：“名为”引出的名称后面，要用“的”连接所修饰的名词，“的”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19996, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有关", "is_correct": true, "explanation": "与“无关”相对，指事情之间有牵涉、有联系，是反义词。"}, {"text": "相似", "is_correct": false, "explanation": "不构成反义，“相似”指有共同之处，与“无关”的“没有联系”不对应。"}, {"text": "清楚", "is_correct": false, "explanation": "不构成反义，“清楚”形容明白，与“无关”没有对应关系。"}, {"text": "巨大", "is_correct": false, "explanation": "不构成反义，“巨大”形容体积或程度，与“无关”没有对应关系。"}], "correct_answer": "有关", "explanations": {"有关": "与“无关”相对，指事情之间有牵涉、有联系，是反义词。", "相似": "不构成反义，“相似”指有共同之处，与“无关”的“没有联系”不对应。", "清楚": "不构成反义，“清楚”形容明白，与“无关”没有对应关系。", "巨大": "不构成反义，“巨大”形容体积或程度，与“无关”没有对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19996, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有关", "is_correct": true, "explanation": "与“无关”相对，指事情之间有牵涉、有联系，是反义词。"}, {"text": "高兴", "is_correct": false, "explanation": "不构成反义，“高兴”形容心情，与“无关”没有对应关系。"}, {"text": "安静", "is_correct": false, "explanation": "不构成反义，“安静”形容环境或状态，与“无关”没有对应关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "不构成反义，“宽阔”形容空间大，与“无关”没有对应关系。"}], "correct_answer": "有关", "explanations": {"有关": "与“无关”相对，指事情之间有牵涉、有联系，是反义词。", "高兴": "不构成反义，“高兴”形容心情，与“无关”没有对应关系。", "安静": "不构成反义，“安静”形容环境或状态，与“无关”没有对应关系。", "宽阔": "不构成反义，“宽阔”形容空间大，与“无关”没有对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19996, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指没有关联或牵涉，彼此之间没有联系。", "primary_collocate": null, "pronunciation": "wú guān", "ipa": "u˧˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "这件事与我无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这个问题与钱无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的决定与你无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试成绩与运气无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病与吃饭无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起事故与天气无关，是人的错。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个故事与历史无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的快乐与钱无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛与我们班无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话与今天的会无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無關", "label": "繁体"}], "register": "中性", "sense_fingerprint": "常用「与X无关」，说明某事与某人或某事没有牵涉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相似", "is_correct": false, "explanation": "语义：“相似”指两样事物有共同之处，“这件事”和“我”之间不能说相似。"}, {"text": "一致", "is_correct": false, "explanation": "搭配：“一致”多用于看法、结果之间，不能说“这件事与我一致”。"}, {"text": "无关", "is_correct": true, "explanation": "正确：“与……无关”表示某事与某人没有牵涉，符合句意。"}, {"text": "相同", "is_correct": false, "explanation": "语义：“相同”要求比较的双方是同类事物，“这件事”和“我”不能相同。"}], "explanations": {"相似": "语义：“相似”指两样事物有共同之处，“这件事”和“我”之间不能说相似。", "一致": "搭配：“一致”多用于看法、结果之间，不能说“这件事与我一致”。", "无关": "正确：“与……无关”表示某事与某人没有牵涉，符合句意。", "相同": "语义：“相同”要求比较的双方是同类事物，“这件事”和“我”不能相同。"}, "sentence_index": 0, "correct_answer": "无关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书讲的是历史，与历史无关。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“讲的是历史”自相矛盾，这里要表示相关，应说“有关”。"}, {"text": "这次事故是因为司机疲劳驾驶引起的，与司机的疲劳无关。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“是因为疲劳驾驶引起的”自相矛盾，应说“有关”。"}, {"text": "他的成功全靠努力，却与努力无关。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“全靠努力”自相矛盾，应说“有关”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相等", "is_correct": false, "explanation": "语义：“相等”多指数量或价值一样，“故事”与“历史”不能比较相等。"}, {"text": "对等", "is_correct": false, "explanation": "搭配：“对等”多用于关系、地位之间，不能用来说“故事”与“历史”对等。"}, {"text": "无关", "is_correct": true, "explanation": "正确：“与……无关”表示某事与某人或某事没有牵涉，符合句意。"}, {"text": "对称", "is_correct": false, "explanation": "语义：“对称”指图形或布局两边相互对应，不能用来形容故事与历史。"}], "explanations": {"相等": "语义：“相等”多指数量或价值一样，“故事”与“历史”不能比较相等。", "对等": "搭配：“对等”多用于关系、地位之间，不能用来说“故事”与“历史”对等。", "无关": "正确：“与……无关”表示某事与某人或某事没有牵涉，符合句意。", "对称": "语义：“对称”指图形或布局两边相互对应，不能用来形容故事与历史。"}, "sentence_index": 6, "correct_answer": "无关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告的结论完全来自实验数据，却与数据无关。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“结论完全来自实验数据”自相矛盾，应说“有关”。"}, {"text": "这次比赛的胜负与球员的表现无关，全看球员怎么踢。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“全看球员怎么踢”矛盾，应说“有关”。"}, {"text": "他对我的请求给予了无关的支持。", "explanation": "这里应该用〈无条件〉。“无关”指没有牵涉，不能用来修饰“支持”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事与政治无关的。", "corrected_sentence": "这件事与政治无关。", "error_description": "“无关”作谓语时句末不能加“的”。应说“这件事与政治无关”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个消息与他的工作很无关。", "corrected_sentence": "那个消息与他的工作无关。", "error_description": "“无关”表示没有牵涉，不能受程度副词“很”修饰。应说“与他的工作无关”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19997, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "来", "is_correct": true, "explanation": "“来”与“去”相对，表示朝说话人所在处移动。"}, {"text": "听", "is_correct": false, "explanation": "“听”表示用耳朵感知声音，与“去”不构成反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”表示书写，与“去”不构成反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”表示入睡，与“去”不构成反义关系。"}], "correct_answer": "来", "explanations": {"来": "“来”与“去”相对，表示朝说话人所在处移动。", "听": "“听”表示用耳朵感知声音，与“去”不构成反义关系。", "写": "“写”表示书写，与“去”不构成反义关系。", "睡": "“睡”表示入睡，与“去”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
