INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19997, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从说话人所在位置向另一地点移动。", "primary_collocate": null, "pronunciation": "qù", "ipa": "tɕʰy˥˩", "syllable_count": 1, "sentences": [{"text": "你在这儿等我，我去买杯水。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经去机场了。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我不去上班，在家休息。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去海边走走。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你去楼下拿一下快递。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐地铁去公司吧。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过很多地方。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我去办公室找她。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天你想去哪儿？", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地去动物园了。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去了", "label": "完成体"}, {"form": "去过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "离开说话人所在位置，移向另一地点（与“来”相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "去", "is_correct": true, "explanation": "去 qù：离开说话人所在位置，移向另一地点，是本词的读音和义项。"}, {"text": "取", "is_correct": false, "explanation": "取 qǔ（第三声）与 qù（第四声）声调不同，意思是拿、取。"}, {"text": "区", "is_correct": false, "explanation": "区 qū（第一声）与 qù（第四声）声调不同，意思是地区。"}, {"text": "句", "is_correct": false, "explanation": "句 jù 与 qù 声母不同（j 与 q），声调相同，意思是句子。"}, {"text": "具", "is_correct": false, "explanation": "具 jù 与 qù 声母不同（j 与 q），声调相同，意思是工具、具备。"}], "explanations": {"去": "去 qù：离开说话人所在位置，移向另一地点，是本词的读音和义项。", "取": "取 qǔ（第三声）与 qù（第四声）声调不同，意思是拿、取。", "区": "区 qū（第一声）与 qù（第四声）声调不同，意思是地区。", "句": "句 jù 与 qù 声母不同（j 与 q），声调相同，意思是句子。", "具": "具 jù 与 qù 声母不同（j 与 q），声调相同，意思是工具、具备。"}, "sentence_index": null, "correct_answer": "去"}, "level_3": {"options": [{"text": "去", "is_correct": true, "explanation": "“去”表示离开此处前往买水，符合句意。"}, {"text": "等", "is_correct": false, "explanation": "语义：“等”与前句的“等我”重复，且“我等着买杯水”与句意不符。"}, {"text": "帮", "is_correct": false, "explanation": "搭配：“帮”需要受益的对象，“帮买杯水”缺少受益者，不成立。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”与“买”意思相反，句子变成卖水，与句意相悖。"}], "explanations": {"去": "“去”表示离开此处前往买水，符合句意。", "等": "语义：“等”与前句的“等我”重复，且“我等着买杯水”与句意不符。", "帮": "搭配：“帮”需要受益的对象，“帮买杯水”缺少受益者，不成立。", "卖": "语义：“卖”与“买”意思相反，句子变成卖水，与句意相悖。"}, "sentence_index": 0, "correct_answer": "去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在公司等你，你快去公司吧。", "explanation": "这里应该用〈来〉。说话人已在“公司”，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}, {"text": "这台电脑去了十年，已经不能用了。", "explanation": "这里应该用〈用〉。“去”不能表示器物使用了多长时间，应说“用了十年”。"}, {"text": "你在门口等我，我马上就去你这儿。", "explanation": "这里应该用〈来〉。目的地是对方“你这儿”，说话人朝对方所在处移动，习惯上用“来”或“过去”，不说“去你这儿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19997, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "去", "is_correct": true, "explanation": "去 qù：离开说话人所在位置，移向另一地点，是本词的读音和义项。"}, {"text": "娶", "is_correct": false, "explanation": "娶 qǔ（第三声）与 qù（第四声）声调不同，意思是娶妻。"}, {"text": "驱", "is_correct": false, "explanation": "驱 qū（第一声）与 qù（第四声）声调不同，意思是驱赶。"}, {"text": "据", "is_correct": false, "explanation": "据 jù 与 qù 声母不同（j 与 q），声调相同，意思是根据。"}, {"text": "屈", "is_correct": false, "explanation": "屈 qū（第一声）与 qù（第四声）声调不同，意思是弯曲、屈服。"}], "explanations": {"去": "去 qù：离开说话人所在位置，移向另一地点，是本词的读音和义项。", "娶": "娶 qǔ（第三声）与 qù（第四声）声调不同，意思是娶妻。", "驱": "驱 qū（第一声）与 qù（第四声）声调不同，意思是驱赶。", "据": "据 jù 与 qù 声母不同（j 与 q），声调相同，意思是根据。", "屈": "屈 qū（第一声）与 qù（第四声）声调不同，意思是弯曲、屈服。"}, "sentence_index": null, "correct_answer": "去"}, "level_3": {"options": [{"text": "去", "is_correct": true, "explanation": "“去过”表示曾经前往，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“地方”搭配，“吃过很多地方”不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，“写过很多地方”没有意义。"}, {"text": "毁", "is_correct": false, "explanation": "语义：“毁”是毁坏，句子变成毁坏了很多地方，与句意不符。"}], "explanations": {"去": "“去过”表示曾经前往，符合句意。", "吃": "搭配：“吃”不能与“地方”搭配，“吃过很多地方”不通。", "写": "搭配：“写”的对象是文字，“写过很多地方”没有意义。", "毁": "语义：“毁”是毁坏，句子变成毁坏了很多地方，与句意不符。"}, "sentence_index": 6, "correct_answer": "去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的味道很好，我想再去一碗。", "explanation": "这里应该用〈来〉。要再添一碗饭时说“再来一碗”，“去”不能表示这种添加。"}, {"text": "我已经回到家了，你快去家里吧。", "explanation": "这里应该用〈来〉。说话人已在家中，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}, {"text": "他昨天在晚会上去了一首歌。", "explanation": "这里应该用〈唱〉。“去”表示离开此处移向别处，不能带“一首歌”作宾语表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_