INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学术界，指从事教学、研究的知识群体及其活动范围。", "primary_collocate": null, "pronunciation": "xué jiè", "ipa": "ɕɥɛ˧˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "其中，一种名为OpenClaw的模型无关架构，凭借其去中心化的设计哲学和高度可适配的代理范式，正在引发学界与产业界的深层思辨：它是否将在2026年成为个人AI代理的标准模板？", "target_word": "学界", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个发现引起了学界的注意。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界对这个问题有不同看法。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人是学界很有名的人。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界和企业界常常一起做研究。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章在学界引起了讨论。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界一直在研究这种病。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的新书得到了学界的好评。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多学界的朋友来参加了会议。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法在学界还没有定论。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學界", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "指学术界，常与产业界、企业界并说，如「学界的看法」「引起学界注意」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，不是知识群体，不能与产业界并列讨论思辨。"}, {"text": "学界", "is_correct": true, "explanation": "正确：“学界”指学术界，与“产业界”并列，符合句意。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语，指谋生的职业，与句中书面语的“深层思辨”不协调。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：“幼儿园”指学前教育机构，不是研究群体，句意不通。"}], "explanations": {"厨房": "语义：“厨房”是做饭的地方，不是知识群体，不能与产业界并列讨论思辨。", "学界": "正确：“学界”指学术界，与“产业界”并列，符合句意。", "饭碗": "语域：“饭碗”是口语，指谋生的职业，与句中书面语的“深层思辨”不协调。", "幼儿园": "语义：“幼儿园”指学前教育机构，不是研究群体，句意不通。"}, "sentence_index": 0, "correct_answer": "学界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人是很有名的学界。", "explanation": "这里应该用〈学者〉。“学界”指学术界这个领域，不指一个人。"}, {"text": "这位老人学界很深。", "explanation": "这里应该用〈学问〉。“学界”指学术界，不能用来说一个人知识的深浅。"}, {"text": "这位老人教过很多学界。", "explanation": "这里应该用〈学生〉。“学界”不指一个个受教育的人，不能作“教”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "搭配：“研究”的主体应是人或机构，“汽车”不能研究疾病。"}, {"text": "学界", "is_correct": true, "explanation": "正确：“学界”指学术界，是研究疾病的群体，符合句意。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“鞋子”不能作“研究”的主语，句子不通。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：“菜市场”指买卖蔬菜的场所，不是研究疾病的群体。"}], "explanations": {"汽车": "搭配：“研究”的主体应是人或机构，“汽车”不能研究疾病。", "学界": "正确：“学界”指学术界，是研究疾病的群体，符合句意。", "鞋子": "搭配：“鞋子”不能作“研究”的主语，句子不通。", "菜市场": "语义：“菜市场”指买卖蔬菜的场所，不是研究疾病的群体。"}, "sentence_index": 6, "correct_answer": "学界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在学界门口见面吧。", "explanation": "这里应该用〈学校〉。“学界”指学术界这个群体，不指学校的地点，不能说“学界门口”。"}, {"text": "这个学界一共有三个月。", "explanation": "这里应该用〈学期〉。“学界”指学术界，不指一段学习的时间，不能用来计算“三个月”。"}, {"text": "他有很高的学界。", "explanation": "这里应该用〈学历〉。“学界”指学术界，不指一个人受教育的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位学界都在讨论这个问题。", "corrected_sentence": "学界都在讨论这个问题。", "error_description": "量词错误：“学界”指学术界这一整体，不能用“位”计量。应说“学界都在讨论这个问题”，去掉“一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位教授的观点受到了学界们的重视。", "corrected_sentence": "这位教授的观点受到了学界的重视。", "error_description": "“学界”指学术界这一整体，是集合名词，不能加“们”。应删去“们”，说“受到了学界的重视”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
