INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使个体成为具有独特性的独立存在的过程或结果。", "primary_collocate": null, "pronunciation": "gè tǐ huà", "ipa": "kɤ˥˩ tʰi˨˩˦ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这一命题不仅关乎技术路径的选择，更触及智能个体化时代的伦理架构、知识主权与人类认知协同的根本问题。", "target_word": "个体化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代社会的个体化使人们更重视自己的选择。", "target_word": "个体化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个体化让每个人都有自己的生活方式。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市生活加快了社会的个体化。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "个体化的结果是人们越来越独立。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者认为个体化是现代社会的特点。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随着经济发展，个体化的趋势越来越明显。", "target_word": "个体化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个过程叫个体化，也就是成为独立的人。", "target_word": "个体化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭变小是个体化的一个表现。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社会个体化以后，人们更少依靠家族。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "個體化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "个体化：使个体成为独特、独立存在的过程或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2e370e-2ea2-4fb6-b66c-628b6aedac9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个体化", "is_correct": true, "explanation": "正确答案。“智能个体化时代”指个体化成为时代特征。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能与“智能”组合成时代的特征。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土是具体物质，无法作为时代的特征。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：口语化的俗称，与本句的书面语域不合。"}], "explanations": {"个体化": "正确答案。“智能个体化时代”指个体化成为时代特征。", "颜色": "语义：颜色不能与“智能”组合成时代的特征。", "泥土": "语义：泥土是具体物质，无法作为时代的特征。", "玩意儿": "语域：口语化的俗称，与本句的书面语域不合。"}, "sentence_index": 0, "correct_answer": "个体化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用个体化去上学。", "explanation": "这里应该用〈自行车〉。个体化是抽象的社会过程，不能作交通工具。"}, {"text": "他用个体化买了一本书。", "explanation": "这里应该用〈钱〉。个体化是抽象过程，不能用来付款。"}, {"text": "这个个体化很聪明。", "explanation": "这里应该用〈个体〉。个体化指社会层面个人独立化的过程或结果，不指具体的人，说某个人聪明要用个体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个体化", "is_correct": true, "explanation": "正确答案。“个体化的趋势”指个体化这一变化方向。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是具体材料，不能表示变化的趋势。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，与社会变化的趋势无关。"}, {"text": "货色", "is_correct": false, "explanation": "语域：口语化的贬义说法，与本句的书面语域不合。"}], "explanations": {"个体化": "正确答案。“个体化的趋势”指个体化这一变化方向。", "木头": "语义：木头是具体材料，不能表示变化的趋势。", "饺子": "语义：饺子是食物，与社会变化的趋势无关。", "货色": "语域：口语化的贬义说法，与本句的书面语域不合。"}, "sentence_index": 6, "correct_answer": "个体化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服是个体化的。", "explanation": "这里应该用〈定制〉。成品衣服不说个体化，个体化强调社会层面的独立化过程。"}, {"text": "妈妈用个体化煮了一锅饭。", "explanation": "这里应该用〈锅〉。个体化是抽象过程，不能用来烹饪。"}, {"text": "这次改革带来了一只个体化。", "explanation": "这里应该用〈种〉。个体化是抽象的过程，不能用“只”计数，应说“一种个体化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经济发展加快了社会的个体化了。", "corrected_sentence": "经济发展加快了社会的个体化。", "error_description": "错误在“个体化了”。“个体化”是名词，后面不能直接加“了”，应写作“社会的个体化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次研究证明了社会的个体化化。", "corrected_sentence": "这次研究证明了社会的个体化。", "error_description": "错误在“个体化化”。“化”不能重复，应去掉多余的“化”，写作“个体化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
