INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20005, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从已知的事实或前提得出新结论的思维过程。", "primary_collocate": null, "pronunciation": "tuī lǐ", "ipa": "tʰweɪ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "OpenClaw的核心突破在于其“代理可移植性”理念——它不依赖特定基础模型的封闭生态，而是让代理在动态环境中根据已知信息自行推理，并据此决定行动策略。", "target_word": "推理", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "医生根据检查结果推理病因。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从已知的事实出发，才能推理出结论。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "侦探根据线索推理出了真相。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用数据推理出了新的结论。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做数学题时，要一步一步地推理。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一步一步推理，最后得出结论。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先有前提，再推理，才会得到结论。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计算机也可以根据规则进行推理。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前提错了，推理的结果就不可靠。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "推理了", "label": "体标"}, {"form": "推理过", "label": "体标"}], "register": "中性", "sense_fingerprint": "推理：从已知事实或前提得出新结论的思维过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2e370e-2ea2-4fb6-b66c-628b6aedac9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，与根据已知信息进行判断无关。"}, {"text": "唠叨", "is_correct": false, "explanation": "语域：“唠叨”是口语，与这段专业描述的语域不合。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”指呆坐不动，无法表示根据已知信息进行判断。"}, {"text": "推理", "is_correct": true, "explanation": "正确：推理指从已知信息得出结论，与“根据已知信息自行……并据此决定”前后呼应。"}], "explanations": {"烹饪": "语义：“烹饪”指做饭，与根据已知信息进行判断无关。", "唠叨": "语域：“唠叨”是口语，与这段专业描述的语域不合。", "发呆": "语义：“发呆”指呆坐不动，无法表示根据已知信息进行判断。", "推理": "正确：推理指从已知信息得出结论，与“根据已知信息自行……并据此决定”前后呼应。"}, "sentence_index": 0, "correct_answer": "推理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这杯水推理光了。", "explanation": "这里应该用〈喝〉。推理是思维活动，不能用来喝水。"}, {"text": "他在脑子里推理出了一座城堡。", "explanation": "这里应该用〈想象〉。想象是凭空构造画面，推理必须从已知前提出发得出结论。"}, {"text": "他努力推理那辆童年的自行车。", "explanation": "这里应该用〈推着〉。推理是根据已知前提得出结论的思维活动，不能用来指推动自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与得出结论无关，这里需要的是思维活动。"}, {"text": "撒娇", "is_correct": false, "explanation": "语域：“撒娇”是口语，与这句的书面叙述不合。"}, {"text": "哼唱", "is_correct": false, "explanation": "语义：“哼唱”是发出歌声，无法一步一步推出结论。"}, {"text": "推理", "is_correct": true, "explanation": "正确：推理指一步一步从前提推出结论，与“最后得出结论”前后呼应。"}], "explanations": {"跳舞": "语义：“跳舞”与得出结论无关，这里需要的是思维活动。", "撒娇": "语域：“撒娇”是口语，与这句的书面叙述不合。", "哼唱": "语义：“哼唱”是发出歌声，无法一步一步推出结论。", "推理": "正确：推理指一步一步从前提推出结论，与“最后得出结论”前后呼应。"}, "sentence_index": 6, "correct_answer": "推理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用了一个小时推理一盘炒饭。", "explanation": "这里应该用〈炒〉。炒是烹饪动作，推理是思维活动，不能用来做饭。"}, {"text": "他用力推理门，门却没开。", "explanation": "这里应该用〈推动〉。推动是用力使物体移动；推理是思维活动，不能用来推门。"}, {"text": "他在抽屉里推理钥匙。", "explanation": "这里应该用〈寻找〉。寻找是去找实物；推理是思维过程，不能用来找钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他推理了出正确的结论。", "corrected_sentence": "他推理出了正确的结论。", "error_description": "补语位置错误：结果补语“出”应紧接动词“推理”，应说“推理出了”，不能说“推理了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们推理了了很久。", "corrected_sentence": "我们推理了很久。", "error_description": "体标重复错误：“了”只用一次，应说“推理了很久”，不能说“推理了了很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
