INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "指在系统或结构中，具有独立功能、可组合或替换的单元。", "primary_collocate": null, "pronunciation": "mó kuài", "ipa": "mwo˧˥ kʰwai˥˩", "syllable_count": 2, "sentences": [{"text": "OpenClaw的核心突破在于其“代理可移植性”理念——它不依赖特定基础模型的封闭生态，而是通过标准化接口协议，实现推理引擎、记忆模块、行动策略与外部环境的动态耦合。", "target_word": "模块", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个软件分成三个模块，每个模块负责一项工作。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某个模块坏了，只换这一个就行。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的每个模块都可以单独更换。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在测试新的支付模块。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登录模块出了问题，所以用户进不去。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的系统由许多独立的模块组成。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责写数据模块的程序。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个模块之间用接口连接。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模块的功能是自动保存文件。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "功能模块", "label": "复合"}, {"form": "软件模块", "label": "复合"}], "register": "书面", "sense_fingerprint": "系统中有独立功能、可组合替换的单元", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fabc475-dc5d-4670-9ae4-ea63fd54f0fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模块", "is_correct": true, "explanation": "正确。模块指系统中具有独立功能、可组合替换的单元，与推理引擎、行动策略并列，符合句意。"}, {"text": "人员", "is_correct": false, "explanation": "语义：“人员”指人，不是可以与推理引擎、行动策略并列、彼此耦合的系统单元。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”不是系统的组成部分，放进这串技术组件的列表中说不通。"}, {"text": "俗语", "is_correct": false, "explanation": "语义：“俗语”是通俗的说法，不是能与推理引擎、行动策略并列耦合的系统单元，“记忆俗语”也不成词。"}], "explanations": {"模块": "正确。模块指系统中具有独立功能、可组合替换的单元，与推理引擎、行动策略并列，符合句意。", "人员": "语义：“人员”指人，不是可以与推理引擎、行动策略并列、彼此耦合的系统单元。", "音乐": "语义：“音乐”不是系统的组成部分，放进这串技术组件的列表中说不通。", "俗语": "语义：“俗语”是通俗的说法，不是能与推理引擎、行动策略并列耦合的系统单元，“记忆俗语”也不成词。"}, "sentence_index": 0, "correct_answer": "模块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个模块是用来观赏的，摆在客厅里很好看。", "explanation": "这里应该用〈摆件〉。模块指系统中具有独立功能的单元，不是供人观赏的摆设。"}, {"text": "妈妈把模块炒进了菜里，味道很好。", "explanation": "这里应该用〈食材〉。模块指系统中的功能单元，不是可以下锅炒的食材。"}, {"text": "他的模块很健康，每天都去跑步。", "explanation": "这里应该用〈身体〉。模块指系统中的功能单元，不能用来指人的身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模块", "is_correct": true, "explanation": "正确。“好的系统由许多独立的模块组成”，模块是系统中可以独立组合的单元。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：“花瓣”是植物的部分，不能作为系统的组成单元。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”描述人的外形，不能用作系统的组成部分。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是可以组合成系统的单元。"}], "explanations": {"模块": "正确。“好的系统由许多独立的模块组成”，模块是系统中可以独立组合的单元。", "花瓣": "语义：“花瓣”是植物的部分，不能作为系统的组成单元。", "身材": "语义：“身材”描述人的外形，不能用作系统的组成部分。", "天气": "语义：“天气”是自然现象，不是可以组合成系统的单元。"}, "sentence_index": 6, "correct_answer": "模块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位模块身材很好，常在大型活动中走秀。", "explanation": "这里应该用〈模特〉。模特指做展示、走秀的人，模块是系统中的单元，不能指人。"}, {"text": "妈妈把模块放进了冰箱，留着明天吃。", "explanation": "这里应该用〈食物〉。模块指系统中的功能单元，不是可以放进冰箱的食物。"}, {"text": "孩子最喜欢的模块是一辆小火车。", "explanation": "这里应该用〈玩具〉。玩具指供孩子玩耍的物品，可以说“一辆小火车”；模块指系统中的功能单元，不能指这样的玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个系统有两只模块需要升级。", "corrected_sentence": "这个系统有两个模块需要升级。", "error_description": "量词错误：“模块”应与量词“个”搭配，不能用“只”（“只”多用于动物或成对物件中的一个）。正确说法是：两个模块。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把模块换了好。", "corrected_sentence": "我们已经把模块换好了。", "error_description": "补语位置错误：“换好”是动词加结果补语，“好”要紧跟动词，应说“换好了”，不能说“换了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
