INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20008, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体表面没有缝隙或漏洞，也比喻事物之间连接紧密，没有破绽。", "primary_collocate": null, "pronunciation": "wú fèng", "ipa": "u˧˥ fəŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这意味着，同一代理可在不同计算平台间无缝迁移，其长期记忆与行为模式不受底层模型更迭的影响。", "target_word": "无缝", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两个系统可以无缝连接。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台新设备能和手机无缝配合。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个部门的工作无缝衔接。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件内衣是无缝的，穿起来很舒服。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机换到新的网络后，视频还能无缝播放。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新城市后，他无缝融入了当地生活。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件让文件在电脑和手机间无缝传送。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堵墙是无缝的，水进不去。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐一首接一首，无缝播放。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无缝连接", "label": "复合"}, {"form": "无缝衔接", "label": "复合"}], "register": "书面", "sense_fingerprint": "没有缝隙；比喻连接紧密、没有破绽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fabc475-dc5d-4670-9ae4-ea63fd54f0fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无缝", "is_correct": true, "explanation": "“无缝”指连接处没有缝隙、过程不中断，与“不受影响”的语境相合。"}, {"text": "断续", "is_correct": false, "explanation": "语义：“断续”指时断时续，与“不受底层模型更迭的影响”所表达的连贯性相矛盾。"}, {"text": "残缺", "is_correct": false, "explanation": "语义：“残缺”指不完整，与“长期记忆与行为模式不受影响”相矛盾。"}, {"text": "杂乱", "is_correct": false, "explanation": "语义：“杂乱”表示没有条理，与“记忆与行为模式不受影响”的平稳迁移相矛盾。"}], "explanations": {"无缝": "“无缝”指连接处没有缝隙、过程不中断，与“不受影响”的语境相合。", "断续": "语义：“断续”指时断时续，与“不受底层模型更迭的影响”所表达的连贯性相矛盾。", "残缺": "语义：“残缺”指不完整，与“长期记忆与行为模式不受影响”相矛盾。", "杂乱": "语义：“杂乱”表示没有条理，与“记忆与行为模式不受影响”的平稳迁移相矛盾。"}, "sentence_index": 0, "correct_answer": "无缝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的颜色很无缝。", "explanation": "这里应该用〈鲜艳〉。无缝指物体没有缝隙或衔接紧密，不用来形容颜色。"}, {"text": "这个孩子的脾气很无缝。", "explanation": "这里应该用〈温和〉。无缝指物体没有缝隙或衔接紧密，不用来形容脾气好坏。"}, {"text": "这盆花的香味很无缝，闻起来很舒服。", "explanation": "这里应该用〈清香〉。无缝说的是衔接处没有缝隙，不用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无缝", "is_correct": true, "explanation": "“无缝”修饰“融入”，说明融入的过程自然、没有隔阂。"}, {"text": "孤立", "is_correct": false, "explanation": "语义：“孤立”与“融入”方向相反，句子说他融入了当地生活，不能说孤立地融入。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：“疏远”指关系不亲近，与“融入当地生活”的语境冲突。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：“陌生”描述人或事物的状态，不能修饰“融入”这种动作。"}], "explanations": {"无缝": "“无缝”修饰“融入”，说明融入的过程自然、没有隔阂。", "孤立": "语义：“孤立”与“融入”方向相反，句子说他融入了当地生活，不能说孤立地融入。", "疏远": "语义：“疏远”指关系不亲近，与“融入当地生活”的语境冲突。", "陌生": "搭配：“陌生”描述人或事物的状态，不能修饰“融入”这种动作。"}, "sentence_index": 6, "correct_answer": "无缝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的音量是无缝的，听起来很舒服。", "explanation": "这里应该用〈适中〉。无缝说的是衔接处没有缝隙，不用来形容音量的大小。"}, {"text": "这辆车的速度是无缝的。", "explanation": "这里应该用〈快速〉。无缝说的是连接处没有缝隙，不用来形容速度的快慢。"}, {"text": "他的记忆力是无缝的。", "explanation": "这里应该用〈牢固〉。无缝说的是衔接处没有缝隙，不用来形容记忆是否稳固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个程序可以无缝得对接。", "corrected_sentence": "这两个程序可以无缝对接。", "error_description": "错误：在状语“无缝”后加了“得”。应直接说“无缝对接”；“得”用于动词或形容词后的补语（如“对接得无缝”），不能放在作状语的“无缝”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根铁管是无缝地，可以放心使用。", "corrected_sentence": "这根铁管是无缝的，可以放心使用。", "error_description": "错误：“是……的”结构中应用“的”，不能用“地”；“地”只用在修饰动词的状语后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
