INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20009, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指替换、交替、更换。例如：季节更迭，岁月流转。", "primary_collocate": null, "pronunciation": "gēng dié", "ipa": "kɤŋ˥ tjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这意味着，同一代理可在不同计算平台间无缝迁移，其长期记忆与行为模式不受底层模型更迭的影响。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "四季更迭，花开花落，一年又过去了。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝代更迭，但这座古城一直留在这里。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的新旧更迭很快，每年都有新款。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司高层更迭频繁，员工都很担心。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春夏秋冬不断更迭，时间过得真快。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，王朝更迭常常带来战争。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着季节更迭，天气也慢慢变冷了。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术更迭得很快，我们要不停地学习。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新旧更迭是自然的事，不用太难过。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更迭了", "label": "体标：了"}], "register": "书面", "sense_fingerprint": "事物或时间依次替换、交替", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fabc475-dc5d-4670-9ae4-ea63fd54f0fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更迭", "is_correct": true, "explanation": "“更迭”指模型先后替换，与“不受影响”的语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不是模型能够产生影响的对象，“底层模型颜色”不成立。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“花朵”与底层模型无关，句中无法接受“底层模型花朵的影响”。"}, {"text": "乐谱", "is_correct": false, "explanation": "搭配：“乐谱”与底层模型无关，句中无法接受“底层模型乐谱的影响”。"}], "explanations": {"更迭": "“更迭”指模型先后替换，与“不受影响”的语境相合。", "颜色": "搭配：“颜色”不是模型能够产生影响的对象，“底层模型颜色”不成立。", "花朵": "搭配：“花朵”与底层模型无关，句中无法接受“底层模型花朵的影响”。", "乐谱": "搭配：“乐谱”与底层模型无关，句中无法接受“底层模型乐谱的影响”。"}, "sentence_index": 0, "correct_answer": "更迭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的裙子很更迭，颜色很漂亮。", "explanation": "这里应该用〈好看〉。更迭是动词，指替换、交替，不能用来形容裙子的样子。"}, {"text": "他把这首歌更迭得很熟，一句都不忘。", "explanation": "这里应该用〈背〉。更迭指替换、交替，不指记住内容。"}, {"text": "他把这个问题更迭得很清楚。", "explanation": "这里应该用〈说明〉。更迭指替换、交替，不指把问题讲清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更迭", "is_correct": true, "explanation": "“更迭”指王朝一个接一个地替换，主语和句意都正确。"}, {"text": "停留", "is_correct": false, "explanation": "搭配：“王朝停留”不成立，“停留”的主语通常是人或车辆。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”要求有生命的主体，不能说“王朝微笑”。"}, {"text": "歌唱", "is_correct": false, "explanation": "配价：“歌唱”需要有生命的主体，与“王朝”搭配不当。"}], "explanations": {"更迭": "“更迭”指王朝一个接一个地替换，主语和句意都正确。", "停留": "搭配：“王朝停留”不成立，“停留”的主语通常是人或车辆。", "微笑": "配价：“微笑”要求有生命的主体，不能说“王朝微笑”。", "歌唱": "配价：“歌唱”需要有生命的主体，与“王朝”搭配不当。"}, "sentence_index": 6, "correct_answer": "更迭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这个故事更迭给孩子听。", "explanation": "这里应该用〈讲〉。更迭指替换、交替，不指把故事讲给别人听。"}, {"text": "她的眼睛更迭得很亮，像星星一样。", "explanation": "这里应该用〈闪〉。更迭指替换、交替，不用来形容眼睛的亮度。"}, {"text": "这份报告他更迭得很快，半小时就写完了。", "explanation": "这里应该用〈写〉。更迭指替换、交替，不指动笔写作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他更迭了一部新手机。", "corrected_sentence": "他更换了一部新手机。", "error_description": "用词错误：“更迭”指事物依次交替，不能带宾语；个人换东西应说“更换”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新款手机更迭的很快。", "corrected_sentence": "新款手机更迭得很快。", "error_description": "错误：“的”应为“得”。“更迭”后的补语要用“得”连接，“更迭的很快”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20010, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系", "is_correct": true, "explanation": "“系”与“解”相对，指把绳子、带子扎紧，正与“解下领带”的动作相反。"}, {"text": "拿", "is_correct": false, "explanation": "“拿”指用手握取，与“解”不构成反义关系。"}, {"text": "扔", "is_correct": false, "explanation": "“扔”指抛掷，与解开束缚之物不构成反义关系。"}, {"text": "摸", "is_correct": false, "explanation": "“摸”指用手接触，与“解”不构成反义关系。"}], "correct_answer": "系", "explanations": {"系": "“系”与“解”相对，指把绳子、带子扎紧，正与“解下领带”的动作相反。", "拿": "“拿”指用手握取，与“解”不构成反义关系。", "扔": "“扔”指抛掷，与解开束缚之物不构成反义关系。", "摸": "“摸”指用手接触，与“解”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20010, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系", "is_correct": true, "explanation": "“系”与“解”相对，指把绳子扎紧，正与“解缆绳”的动作相反。"}, {"text": "推", "is_correct": false, "explanation": "“推”指用力使物体移动，与“解”不构成反义关系。"}, {"text": "按", "is_correct": false, "explanation": "“按”指用手压，与解开绳子不构成反义关系。"}, {"text": "抱", "is_correct": false, "explanation": "“抱”指用手臂环绕，与“解”不构成反义关系。"}], "correct_answer": "系", "explanations": {"系": "“系”与“解”相对，指把绳子扎紧，正与“解缆绳”的动作相反。", "推": "“推”指用力使物体移动，与“解”不构成反义关系。", "按": "“按”指用手压，与解开绳子不构成反义关系。", "抱": "“抱”指用手臂环绕，与“解”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20010, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把束缚着或封闭着的东西打开。", "primary_collocate": null, "pronunciation": "jiě", "ipa": "tɕjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他慢慢解绳子上的结。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把包上的绳子解了，拿出里面的书。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先解扣子，再脱外套。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解下领带，坐在沙发上休息。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子过去解狗身上的绳子。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结太紧，我解了很久。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她解围裙，走进了客厅。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解衣服的扣子，发现手在发抖。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我解一下这条项链，好吗？", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船到了，工人上去解缆绳。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解了", "label": "体标：了"}, {"form": "解过", "label": "体标：过"}, {"form": "解开", "label": "复合"}], "register": "中性", "sense_fingerprint": "解开绳结、扣子等束缚之物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fabc475-dc5d-4670-9ae4-ea63fd54f0fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解", "is_correct": true, "explanation": "jiě（第三声）是正确答案，指把束缚着的东西打开。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是借入或借出。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是节日或段落。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是接住或接受。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。"}], "explanations": {"解": "jiě（第三声）是正确答案，指把束缚着的东西打开。", "借": "jiè（第四声）与 jiě（第三声）声调不同，意思是借入或借出。", "节": "jié（第二声）与 jiě（第三声）声调不同，意思是节日或段落。", "接": "jiē（第一声）与 jiě（第三声）声调不同，意思是接住或接受。", "街": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。"}, "sentence_index": null, "correct_answer": "解"}, "level_3": {"options": [{"text": "解", "is_correct": true, "explanation": "“解”指打开束缚着的绳结，与“慢慢”和“绳子上的结”搭配，句子通顺。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”多用于纸张、布料，不能用来松开绳子上的结。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”指描绘图形，与松开绳结的动作不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于清洁，不能说洗绳子上的结。"}], "explanations": {"解": "“解”指打开束缚着的绳结，与“慢慢”和“绳子上的结”搭配，句子通顺。", "撕": "搭配：“撕”多用于纸张、布料，不能用来松开绳子上的结。", "画": "语义：“画”指描绘图形，与松开绳结的动作不符。", "洗": "搭配：“洗”用于清洁，不能说洗绳子上的结。"}, "sentence_index": 0, "correct_answer": "解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他解门，走了进去。", "explanation": "这里应该用〈开〉。解指解开绳结、纽扣等被束缚的东西，门是推拉或转动打开的，要用“开”。"}, {"text": "他把饭解到了碗里，然后开始吃。", "explanation": "这里应该用〈盛〉。解表示打开束缚，不能表示把饭装进碗里；装饭要用“盛”。"}, {"text": "他很快就把感冒解好了。", "explanation": "这里应该用〈治〉。解指打开束缚，不能用于疾病，治好感冒要用“治”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20010, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "解", "is_correct": true, "explanation": "jiě（第三声）是正确答案，指把束缚着的东西打开。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是绳结或结束。"}, {"text": "介", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍或介于之间。"}, {"text": "戒", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒除或戒指。"}, {"text": "界", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是界限或界别。"}], "explanations": {"解": "jiě（第三声）是正确答案，指把束缚着的东西打开。", "结": "jié（第二声）与 jiě（第三声）声调不同，意思是绳结或结束。", "介": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍或介于之间。", "戒": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒除或戒指。", "界": "jiè（第四声）与 jiě（第三声）声调不同，意思是界限或界别。"}, "sentence_index": null, "correct_answer": "解"}, "level_3": {"options": [{"text": "解", "is_correct": true, "explanation": "“解”指解开、松开，“解围裙”是把系在身上的围裙取下来，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与解开围裙的动作无关。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物或水，不能说煮围裙。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或事情，不能用于围裙。"}], "explanations": {"解": "“解”指解开、松开，“解围裙”是把系在身上的围裙取下来，句子通顺。", "吃": "语义：“吃”指进食，与解开围裙的动作无关。", "煮": "搭配：“煮”用于食物或水，不能说煮围裙。", "讨论": "搭配：“讨论”的对象是问题或事情，不能用于围裙。"}, "sentence_index": 6, "correct_answer": "解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙解在墙上。", "explanation": "这里应该用〈挂〉。解表示打开束缚，不表示把东西固定在墙上，挂东西要用“挂”。"}, {"text": "渔夫把鱼解到了岸边。", "explanation": "这里的〈解〉是打开或松开束缚的意思，不能表示把鱼拉上岸；拖鱼上岸应该用〈拖〉。"}, {"text": "他给我解了一杯水。", "explanation": "这里应该用〈倒〉。解不能表示把液体注入杯中，倒水要用“倒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把绳子开解了。", "corrected_sentence": "他把绳子解开了。", "error_description": "错误：“开解”；正确：“解开”。“开”是结果补语，必须紧跟动词之后，应说“解开”，表示绳子被打开。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前过解这个结。", "corrected_sentence": "我以前解过这个结。", "error_description": "错误：“过解”；正确：“解过”。体标“过”必须紧跟动词之后，表示曾经有过这样的经历，应说“解过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20012, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解绑", "is_correct": true, "explanation": "正确。“解绑”与“绑定”相反，指解除账号与手机号等之间的关联。"}, {"text": "下载", "is_correct": false, "explanation": "无反义关系：“下载”指把文件从网上存到本地，与账号关联无关。"}, {"text": "注册", "is_correct": false, "explanation": "无反义关系：“注册”指新建账号，与解除已有关联不构成相反的关系。"}, {"text": "分享", "is_correct": false, "explanation": "无反义关系：“分享”指把内容给别人看，与账号和手机号的关联无关。"}], "correct_answer": "解绑", "explanations": {"解绑": "正确。“解绑”与“绑定”相反，指解除账号与手机号等之间的关联。", "下载": "无反义关系：“下载”指把文件从网上存到本地，与账号关联无关。", "注册": "无反义关系：“注册”指新建账号，与解除已有关联不构成相反的关系。", "分享": "无反义关系：“分享”指把内容给别人看，与账号和手机号的关联无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
