INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20012, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过某种方式使两个事物建立固定联系，例如账号与手机号关联。", "primary_collocate": null, "pronunciation": "bǎng dìng", "ipa": "pɑŋ˨˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我把手机号绑定到这个账号上了。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的银行卡已经绑定了吗？", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册以后，请先绑定你的邮箱。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件要绑定手机号才能登录。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给孩子的手表绑定了家长的手机。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的微信还没绑定银行卡。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他绑定过两个手机号，现在只用一个。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换新手机前，先看看账号绑定的是哪个号码。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在设置里绑定你的支付宝账号。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏账号绑定着我的手机号。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绑定了", "label": "体标（了）"}, {"form": "绑定过", "label": "体标（过）"}, {"form": "绑定着", "label": "体标（着）"}, {"form": "解绑", "label": "复合"}], "register": "中性", "sense_fingerprint": "使账号、银行卡等与手机号、邮箱建立固定关联", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83dd7b11-4fd5-4148-b4dd-c5c3bc797d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绑定", "is_correct": true, "explanation": "正确。“绑定到这个账号上”表示把手机号与账号建立固定关联，与“已经……了”的完成语气相符。"}, {"text": "退出", "is_correct": false, "explanation": "配价：“退出”的宾语是账号或软件，不能说“把手机号退出”，也不能接“到这个账号上”。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”是去掉已有信息，不能与“到这个账号上”组合表示把手机号放进账号。"}, {"text": "拆分", "is_correct": false, "explanation": "语义：“拆分”是分开，与句中“连到这个账号上”的连接义正相反。"}], "explanations": {"绑定": "正确。“绑定到这个账号上”表示把手机号与账号建立固定关联，与“已经……了”的完成语气相符。", "退出": "配价：“退出”的宾语是账号或软件，不能说“把手机号退出”，也不能接“到这个账号上”。", "删除": "搭配：“删除”是去掉已有信息，不能与“到这个账号上”组合表示把手机号放进账号。", "拆分": "语义：“拆分”是分开，与句中“连到这个账号上”的连接义正相反。"}, "sentence_index": 0, "correct_answer": "绑定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把这根数据线绑定到电脑的接口上。", "explanation": "这里应该用〈连接〉。连接用于线路、设备等实体之间的接通，绑定专指账号、服务等抽象的固定关联，不能用来说数据线。"}, {"text": "这份合同已经绑定了两个人的签名。", "explanation": "这里应该用〈签〉。签是在文件上写下名字，绑定指账号、卡号等之间的固定关联，不能用来说签名。"}, {"text": "这个月会从卡里绑定十块钱。", "explanation": "这里应该用〈扣〉。扣是从账户里减去钱款，绑定指账号与卡号等之间的固定关联，不能用来说从卡里绑定钱款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绑定", "is_correct": true, "explanation": "正确。“绑定过两个手机号”表示曾与账号建立过关联，“现在只用一个”与之衔接。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或物品，不能说“修理手机号”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能带手机号作宾语，句子无法成立。"}, {"text": "放大", "is_correct": false, "explanation": "语义：“放大”指使变大，与“两个手机号”及“现在只用一个”的语境不符。"}], "explanations": {"绑定": "正确。“绑定过两个手机号”表示曾与账号建立过关联，“现在只用一个”与之衔接。", "修理": "搭配：“修理”的对象是机器或物品，不能说“修理手机号”。", "唱": "语义：“唱”不能带手机号作宾语，句子无法成立。", "放大": "语义：“放大”指使变大，与“两个手机号”及“现在只用一个”的语境不符。"}, "sentence_index": 6, "correct_answer": "绑定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这几页纸绑定成了一本书。", "explanation": "这里应该用〈装订〉。装订是把纸张订成册，绑定指账号、卡号等之间的固定关联，不能用于纸张。"}, {"text": "他的感冒已经绑定了两天。", "explanation": "这里应该用〈持续〉。持续指延续一段时间，绑定指账号、卡号等之间的固定关联，不能用于病情。"}, {"text": "这个软件的新功能今天已经绑定了。", "explanation": "这里应该用〈启用〉。启用是打开某项功能，绑定指账号、卡号等之间的固定关联，不能用来说功能已绑定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把你的银行卡绑定这个账号上。", "corrected_sentence": "请把你的银行卡绑定到这个账号上。", "error_description": "错误：“绑定这个账号上”；正确：“绑定到这个账号上”。“绑定”表示与某处建立关联，后面引出去向时要用介词“到”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的支付宝还没绑定了手机号。", "corrected_sentence": "我的支付宝还没绑定手机号。", "error_description": "错误：“还没绑定了”；正确：“还没绑定”。“没”否定的是尚未发生的动作，“没……了”不能成立，动词后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
