INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20013, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20013, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对某事物或局面进行掌控、支配的权力。", "primary_collocate": null, "pronunciation": "kòng zhì quán", "ipa": "kʰʊŋ˥˩ ʈʂɻ̩˥˩ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这种解耦设计，从根本上挑战了当前主流AI系统“模型绑定代理”的固化范式，为用户提供了前所未有的自主控制权。", "target_word": "控制权", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司的控制权在老板手里。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想拿到这家店的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子也需要一点自己的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人都想要球队的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把公司的控制权交给了儿子。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户应该有自己数据的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上半场我们一直拥有球的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不想放弃家里生意的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有他有网站的控制权，别人不能改。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "控制", "label": "词根（动词）"}], "register": "中性", "sense_fingerprint": "对事物或局面进行掌控、支配的权力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83dd7b11-4fd5-4148-b4dd-c5c3bc797d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控制权", "is_correct": true, "explanation": "正确。“自主控制权”指用户能自主掌控系统的权利，与前文“挑战了固化范式”相符。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“自主体积”不成立，“自主”不能修饰“体积”。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“饮食”与设计、系统的语境无关，句子意思不通。"}, {"text": "时令", "is_correct": false, "explanation": "语义：“时令”指季节或时节，与“前所未有的自主”无法组合。"}], "explanations": {"控制权": "正确。“自主控制权”指用户能自主掌控系统的权利，与前文“挑战了固化范式”相符。", "体积": "搭配：“自主体积”不成立，“自主”不能修饰“体积”。", "饮食": "语义：“饮食”与设计、系统的语境无关，句子意思不通。", "时令": "语义：“时令”指季节或时节，与“前所未有的自主”无法组合。"}, "sentence_index": 0, "correct_answer": "控制权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位舞者的控制权很强，动作非常稳。", "explanation": "这里应该用〈控制力〉。控制力指对身体动作的掌握能力，控制权指支配事物的权利，不能说“控制权很强”。"}, {"text": "孩子也有受教育的控制权。", "explanation": "这里应该用〈权利〉。受教育是应有的权利，与掌控事物无关，“控制权”不能这样用。"}, {"text": "电视的控制权找不到了，没法换台。", "explanation": "这里应该用〈遥控器〉。遥控器是用来换台的实物，控制权指支配事物的权力，不能“找不到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控制权", "is_correct": true, "explanation": "正确。“用户应该有自己数据的控制权”表示用户对自己的数据有支配的权利。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“数据的颜色”与“用户应该有……的”所表达的支配权不相关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：数据没有味道，“自己数据的味道”无法表示权利。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能与“数据”搭配。"}], "explanations": {"控制权": "正确。“用户应该有自己数据的控制权”表示用户对自己的数据有支配的权利。", "颜色": "语义：“数据的颜色”与“用户应该有……的”所表达的支配权不相关。", "味道": "语义：数据没有味道，“自己数据的味道”无法表示权利。", "体重": "搭配：“体重”只用于人或动物，不能与“数据”搭配。"}, "sentence_index": 6, "correct_answer": "控制权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工程师的修理控制权很强，任何机器都能修好。", "explanation": "这里应该用〈能力〉。修理能力指动手修理的本领，控制权是支配事物的权利，不能用来形容修理的本事。"}, {"text": "这间屋子的控制权很大，足够放下一张床。", "explanation": "这里应该用〈面积〉。面积指平面的大小，控制权指支配事物的权利，不能用来形容房间大小。"}, {"text": "这辆车的控制权很好，转弯很灵活。", "explanation": "这里应该用〈操控性〉。操控性指车辆操纵的灵活程度，控制权指支配事物的权利，不能用来形容车的性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于吃到了这家工厂的控制权。", "corrected_sentence": "他终于拿到了这家工厂的控制权。", "error_description": "错误：“吃到”；正确：“拿到”。“控制权”是抽象的权力，只能“拿到、得到”，不能“吃到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家银行的控制权已经喝到了别人手里。", "corrected_sentence": "这家银行的控制权已经落到了别人手里。", "error_description": "错误：“喝到”；正确：“落到”。说“控制权”转到别人那里，要用“落到……手里”，不能用“喝到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20014, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
