INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20014, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指使用某物或利用某种方式做事的人。", "primary_collocate": null, "pronunciation": "shǐ yòng zhě", "ipa": "ʂɻ̩˨˩ jʊŋ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "使用者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个软件有很多使用者。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每位使用者都要先注册账号。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新使用者可以免费试用一个月。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的使用者是一位老人。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的使用者越来越年轻了。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请使用者先看说明书。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多使用者说这个应用很好用。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子的使用者是我奶奶。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用者常常忘记自己的密码。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "使用某物或某种方式的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83dd7b11-4fd5-4148-b4dd-c5c3bc797d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "使用者", "is_correct": true, "explanation": "正确答案。shǐ yòng zhě，指使用某物或利用某种方式做事的人。"}, {"text": "试用者", "is_correct": false, "explanation": "“试” shì（第四声）与“使” shǐ（第三声）声调不同，意思是试用某物的人。"}, {"text": "施用者", "is_correct": false, "explanation": "“施” shī（第一声）与“使” shǐ（第三声）声调不同，意思是施用（如农药）的人。"}, {"text": "食用者", "is_correct": false, "explanation": "“食” shí（第二声）与“使” shǐ（第三声）声调不同，意思是食用某物的人，多指吃的东西。"}], "explanations": {"使用者": "正确答案。shǐ yòng zhě，指使用某物或利用某种方式做事的人。", "试用者": "“试” shì（第四声）与“使” shǐ（第三声）声调不同，意思是试用某物的人。", "施用者": "“施” shī（第一声）与“使” shǐ（第三声）声调不同，意思是施用（如农药）的人。", "食用者": "“食” shí（第二声）与“使” shǐ（第三声）声调不同，意思是食用某物的人，多指吃的东西。"}, "sentence_index": null, "correct_answer": "使用者"}, "level_3": {"options": [{"text": "使用者", "is_correct": true, "explanation": "正确：“终端使用者”指使用终端设备的人，与“被动接受”的角色相符。"}, {"text": "设计者", "is_correct": false, "explanation": "语义：“设计者”是设计东西的人，与“被动接受预设行为逻辑”的角色相反。"}, {"text": "生产者", "is_correct": false, "explanation": "搭配：“终端使用者”是固定说法，“终端生产者”不是常用搭配。"}, {"text": "决策者", "is_correct": false, "explanation": "语义：“决策者”主动拍板，与“被动接受”的句意矛盾。"}], "explanations": {"使用者": "正确：“终端使用者”指使用终端设备的人，与“被动接受”的角色相符。", "设计者": "语义：“设计者”是设计东西的人，与“被动接受预设行为逻辑”的角色相反。", "生产者": "搭配：“终端使用者”是固定说法，“终端生产者”不是常用搭配。", "决策者": "语义：“决策者”主动拍板，与“被动接受”的句意矛盾。"}, "sentence_index": 0, "correct_answer": "使用者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区最近来了很多使用者在偷东西。", "explanation": "这里应该用〈小偷〉。“使用者”指使用某物的人，偷东西的人要说“小偷”。"}, {"text": "这家餐厅今天来了很多使用者。", "explanation": "这里应该用〈顾客〉。“使用者”指使用某物或做事的人，到餐厅消费的人要说“顾客”。"}, {"text": "这场比赛吸引了很多使用者。", "explanation": "这里应该用〈观众〉。“使用者”指使用某物的人，看比赛的人要说“观众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用者", "is_correct": true, "explanation": "正确：这里指需要先看说明书的人，即使用者。"}, {"text": "目击者", "is_correct": false, "explanation": "语义：“目击者”指亲眼看见事情的人，与看说明书无关。"}, {"text": "旁观者", "is_correct": false, "explanation": "语义：“旁观者”指不参与其中的人，与“请……先看说明书”的要求相悖。"}, {"text": "流浪者", "is_correct": false, "explanation": "语义：“流浪者”没有使用物品的需要，与“请……先看说明书”的语境不符。"}], "explanations": {"使用者": "正确：这里指需要先看说明书的人，即使用者。", "目击者": "语义：“目击者”指亲眼看见事情的人，与看说明书无关。", "旁观者": "语义：“旁观者”指不参与其中的人，与“请……先看说明书”的要求相悖。", "流浪者": "语义：“流浪者”没有使用物品的需要，与“请……先看说明书”的语境不符。"}, "sentence_index": 6, "correct_answer": "使用者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本小说的使用者是一位年轻作家。", "explanation": "这里应该用〈作者〉。“使用者”指使用某物的人，写小说的人要说“作者”。"}, {"text": "这部电影的使用者都是知名演员。", "explanation": "这里应该用〈影星〉。“使用者”指使用某物的人，参演电影的人要说“影星”。"}, {"text": "这支球队有很多使用者。", "explanation": "这里应该用〈球迷〉。“使用者”指使用某物或做事的人，支持球队的人要说“球迷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台服务器有两台使用者。", "corrected_sentence": "这台服务器有两位使用者。", "error_description": "错误在量词：“台”应改为“位”。“台”用于机器、设备，“使用者”指人，应用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只使用者都说这个应用很好用。", "corrected_sentence": "两名使用者都说这个应用很好用。", "error_description": "错误在量词：“只”应改为“名”。“只”多用于动物或小件物品，“使用者”指人，应用“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
