INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20018, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "言行所依据的标准或原则。", "primary_collocate": null, "pronunciation": "zhǔn zé", "ipa": "tʂuən˨˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "准则", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "诚实是我们做人的基本准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有一套行为准则，每个人都要遵守。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把“不说谎”当作自己的准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要按照职业准则来工作。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条准则告诉我们，做事要公平。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说，做人要有自己的准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者的工作准则是说真话。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用同样的准则要求自己和别人。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "道德是人们生活的重要准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "行为准则", "label": "复合"}, {"form": "準則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "准则：言行所依据的标准或原则，多指价值观、做人做事的原则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79065f31-2ba5-42e7-956e-ce5a49842aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "准则", "is_correct": true, "explanation": "正确：准则指言行所依据的原则，可以“嵌入”价值观与伦理，句意通顺。"}, {"text": "限额", "is_correct": false, "explanation": "搭配：限额指数量上的上限，不与“伦理”组合。"}, {"text": "节拍", "is_correct": false, "explanation": "语义：节拍指音乐或动作的节奏，不能作为伦理内容嵌入认知循环。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律指音乐的音高组织，与价值观、偏好等抽象内容无关。"}], "explanations": {"准则": "正确：准则指言行所依据的原则，可以“嵌入”价值观与伦理，句意通顺。", "限额": "搭配：限额指数量上的上限，不与“伦理”组合。", "节拍": "语义：节拍指音乐或动作的节奏，不能作为伦理内容嵌入认知循环。", "旋律": "语义：旋律指音乐的音高组织，与价值观、偏好等抽象内容无关。"}, "sentence_index": 0, "correct_answer": "准则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把尺子的长度准则是一厘米。", "explanation": "这里应该用〈标准〉。准则指言行所依据的原则，不用于长度这类可测量的数值。"}, {"text": "这个星期他的准则排满了会议。", "explanation": "这里应该用〈日程〉。准则指言行所依据的原则，不指安排好的时间表。"}, {"text": "这个蛋糕的准则很简单。", "explanation": "这里应该用〈配方〉。准则指言行的原则，不指做菜的材料配比和步骤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准则", "is_correct": true, "explanation": "正确：准则指做人应遵循的原则，与“做人要有自己的”搭配，句意通顺。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是人的体形特征，不能说“做人要有自己的身材”。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量指吃饭的分量，与做人的原则无关。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重描述身体的重量，不能作为做人的特征。"}], "explanations": {"准则": "正确：准则指做人应遵循的原则，与“做人要有自己的”搭配，句意通顺。", "身材": "体貌：身材是人的体形特征，不能说“做人要有自己的身材”。", "饭量": "语义：饭量指吃饭的分量，与做人的原则无关。", "体重": "体貌：体重描述身体的重量，不能作为做人的特征。"}, "sentence_index": 6, "correct_answer": "准则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的准则很高。", "explanation": "这里应该用〈配置〉。准则指言行所依据的原则，不用于描述电脑的硬件性能。"}, {"text": "这首歌的准则很动听。", "explanation": "这里应该用〈旋律〉。准则指言行的原则，不指乐曲的音调进行。"}, {"text": "这张图的准则是一比一。", "explanation": "这里应该用〈比例〉。准则指言行的原则，不用来描述图纸上的比例关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司有三件行为准则。", "corrected_sentence": "公司有三条行为准则。", "error_description": "量词错误：“件”多用于衣物、事情，准则应用“条”或“项”计数，应说“三条行为准则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "律师要遵守一根职业准则。", "corrected_sentence": "律师要遵守职业准则。", "error_description": "量词多余且错误：准则不用“根”计量，应去掉“一根”；若要计数，应说“一条职业准则”或“一项职业准则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
