INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20021, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对自己的思想、情感、行为进行观察和反思。", "primary_collocate": null, "pronunciation": "nèi xǐng", "ipa": "nei˥˩ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每晚都会内省，想想今天做错了什么。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架以后，她一个人坐着内省。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先内省，再写总结。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常内省的人更容易发现自己的问题。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，他开始认真内省了。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内省不是责怪自己，而是看清自己。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少内省，总觉得错的是别人。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个周末，我都安静地内省半小时。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写日记的目的，就是为了内省。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他内省过很多次，知道自己太急了。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "内省了", "label": "完成体"}, {"form": "内省过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "对自己的思想、情感、行为进行观察和反思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79065f31-2ba5-42e7-956e-ce5a49842aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内省", "is_correct": true, "explanation": "正确：内省是对自己的思想和行为进行反思，与“想想今天做错了什么”一致。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与“想想今天做错了什么”的反思活动毫不相干，句子不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞不是反思活动，与后半句“想想今天做错了什么”的内容矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”与“想想今天做错了什么”的反思内容不相干，句意不通。"}], "explanations": {"内省": "正确：内省是对自己的思想和行为进行反思，与“想想今天做错了什么”一致。", "游泳": "语义：游泳与“想想今天做错了什么”的反思活动毫不相干，句子不通。", "跳舞": "语义：跳舞不是反思活动，与后半句“想想今天做错了什么”的内容矛盾。", "洗": "语义：“洗”与“想想今天做错了什么”的反思内容不相干，句意不通。"}, "sentence_index": 0, "correct_answer": "内省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在内省这个问题的答案。", "explanation": "这里应该用〈思考〉。内省针对自己的思想、情感和行为，不能用来对外部问题。"}, {"text": "妈妈正在内省这份作业。", "explanation": "这里应该用〈检查〉。内省的对象是自己，不能用来指检查外面的作业。"}, {"text": "我们在内省那只小鸟。", "explanation": "这里应该用〈观察〉。内省只指对自己内心的观察，不能用来观察外物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内省", "is_correct": true, "explanation": "正确：“很少内省”与“总觉得错的是别人”相呼应，说明他不反思自己。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋与“总觉得错的是别人”没有关系，句子不通。"}, {"text": "种菜", "is_correct": false, "explanation": "语义：种菜与后半句的心理状态无关，句意混乱。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要宾语（送什么、送给谁），单独放在空位里句子不完整。"}], "explanations": {"内省": "正确：“很少内省”与“总觉得错的是别人”相呼应，说明他不反思自己。", "下棋": "语义：下棋与“总觉得错的是别人”没有关系，句子不通。", "种菜": "语义：种菜与后半句的心理状态无关，句意混乱。", "送": "配价：“送”需要宾语（送什么、送给谁），单独放在空位里句子不完整。"}, "sentence_index": 6, "correct_answer": "内省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和朋友一起内省了这个方案。", "explanation": "这里应该用〈讨论〉。内省是一个人对自己的反思，不能用于和别人共同商议方案。"}, {"text": "我们在课上内省了这本小说。", "explanation": "这里应该用〈分析〉。内省只指对自身的反思，不能用于分析外部的作品。"}, {"text": "下午老师要去礼堂内省一场讲座。", "explanation": "这里应该用〈听〉。内省只指对自身的反思，不能用于听讲座。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在内省了自己的错误。", "corrected_sentence": "他正在内省自己的错误。", "error_description": "体标错误：“正在”表示动作进行，不能与“了”同用，应去掉“了”，说“正在内省自己的错误”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都内省了自己的行为。", "corrected_sentence": "他每天都内省自己的行为。", "error_description": "体标错误：表示习惯性动作的“每天都”句不能带“了”，应去掉“了”，说“每天都内省自己的行为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
