INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使某事物具有明确的结构或组织框架。", "primary_collocate": null, "pronunciation": "jié gòu huà", "ipa": "tɕjɛ˧˥ kou˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "研究者尝试将这批非正式的访谈记录结构化，以便进行跨样本比较。", "target_word": "结构化", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "我们要把这些资料结构化，方便查找。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结构化以后，这份报告清楚多了。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杂乱的笔记结构化成了一张表。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把客户信息结构化。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据结构化后，电脑就能很快处理。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么把想法结构化。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章内容太杂，得先把它结构化，读者才看得懂。", "target_word": "结构化", "complexity_tier": "T3", "furigana": "zhè piān wénzhāng nèiróng tài zá, děi xiān bǎ tā jiégòuhuà, dúzhě cái kàn de dǒng.", "sentence_source": "generated"}, {"text": "先结构化，再写作，文章会更清楚。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求把会议记录结构化。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结构化了", "label": "完成体"}, {"form": "结构化过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "使事物具有明确的结构或组织框架", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79065f31-2ba5-42e7-956e-ce5a49842aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结构化", "is_correct": true, "explanation": "正确：结构化指使事物具有明确的结构或组织框架。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻指低温保存，与使事物有条理的意思不符。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：晾晒指在阳光下晒干，与整理访谈记录无关。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干指去除水分，与结构化的意思无关。"}], "explanations": {"结构化": "正确：结构化指使事物具有明确的结构或组织框架。", "冷冻": "语义：冷冻指低温保存，与使事物有条理的意思不符。", "晾晒": "语义：晾晒指在阳光下晒干，与整理访谈记录无关。", "烘干": "语义：烘干指去除水分，与结构化的意思无关。"}, "sentence_index": 0, "correct_answer": "结构化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把头发结构化成了一个发髻。", "explanation": "这里应该用〈打扮〉。结构化指使资料、想法等有条理，不用于改变外形。"}, {"text": "工人把零件结构化成了一台机器。", "explanation": "这里应该用〈组装〉。结构化只说使抽象内容有条理，把零件变成机器要用组装。"}, {"text": "妈妈把米结构化成了粥。", "explanation": "这里应该用〈煮〉。结构化不指烹饪加热，米变成粥要用煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结构化", "is_correct": true, "explanation": "正确：结构化指使想法有条理，符合“把想法……”的用法。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：缝补用于衣物等布料，不能用于想法。"}, {"text": "冰镇", "is_correct": false, "explanation": "语义：冰镇指降温使饮料变凉，想法不能被冰镇。"}, {"text": "熨平", "is_correct": false, "explanation": "搭配：熨平针对织物或纸张的褶皱，不说熨平想法。"}], "explanations": {"结构化": "正确：结构化指使想法有条理，符合“把想法……”的用法。", "缝补": "搭配：缝补用于衣物等布料，不能用于想法。", "冰镇": "语义：冰镇指降温使饮料变凉，想法不能被冰镇。", "熨平": "搭配：熨平针对织物或纸张的褶皱，不说熨平想法。"}, "sentence_index": 6, "correct_answer": "结构化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶把毛线结构化成了围巾。", "explanation": "这里应该用〈织〉。结构化不指用线编成物品，毛线变成围巾要用织。"}, {"text": "他把苹果结构化成了小块。", "explanation": "这里应该用〈切〉。结构化不指分割实物，苹果切成小块要用切。"}, {"text": "他把书结构化成了一排。", "explanation": "这里应该用〈摆〉。结构化不指摆放，书排成一排要用摆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "结构化地数据更方便分析。", "corrected_sentence": "结构化的数据更方便分析。", "error_description": "错误：定语标记用错。“结构化”修饰名词“数据”，应用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理昨天要求我们把会议记录结构化着。", "corrected_sentence": "经理昨天要求我们把会议记录结构化。", "error_description": "错误：体标“着”用错。“把……结构化”表示要完成的处置动作，不表示持续状态，句末不能加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
