INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指具有人的特征或类似人的事物，如外形、行为或智能。", "primary_collocate": null, "pronunciation": "lèi rén", "ipa": "lei˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这种内省能力使得OpenClaw在复杂、非结构化的生活场景中展现出类人的问题解决韧性。", "target_word": "类人", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个机器人有类人的外形。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "类人机器人会像人一样走路。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在做类人的智能助手。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它的动作很自然，有类人的协调性，不像普通机器。", "target_word": "类人", "complexity_tier": "T3", "furigana": "tā de dòngzuò hěn zìrán, yǒu lèirén de xiétiáoxìng, bú xiàng pǔtōng jīqì.", "sentence_source": "generated"}, {"text": "展览上有一个类人的机器人，会笑也会说话。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "类人的表情让孩子们很喜欢。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想让电脑有类人的思考方式。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里的角色，行为有明显的类人特点。", "target_word": "类人", "complexity_tier": "T3", "furigana": "zhège yóuxì lǐ de juésè, xíngwéi yǒu míngxiǎn de lèirén tèdiǎn.", "sentence_source": "generated"}, {"text": "他设计了一个类人的玩具，会点头。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "类人的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "具有人的外形、行为或智能特征的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79065f31-2ba5-42e7-956e-ce5a49842aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类人", "is_correct": true, "explanation": "正确：类人指具有人的特征，符合“展现出类人的……”的用法。"}, {"text": "僵硬", "is_correct": false, "explanation": "语义：僵硬指不灵活，与韧性所指的灵活应变相反。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：迟钝指反应慢、不灵敏，与韧性的意思相反。"}, {"text": "方正", "is_correct": false, "explanation": "体貌：方正描写外形的棱角，不用来形容问题解决韧性。"}], "explanations": {"类人": "正确：类人指具有人的特征，符合“展现出类人的……”的用法。", "僵硬": "语义：僵硬指不灵活，与韧性所指的灵活应变相反。", "迟钝": "语义：迟钝指反应慢、不灵敏，与韧性的意思相反。", "方正": "体貌：方正描写外形的棱角，不用来形容问题解决韧性。"}, "sentence_index": 0, "correct_answer": "类人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工匠做了一张类人的桌子。", "explanation": "这里应该用〈木制〉。类人指像人的特征，不用于描述桌子等无人形的物品。"}, {"text": "这个盘子是类人的。", "explanation": "这里应该用〈圆形〉。类人说的是像人，不描述盘子的形状。"}, {"text": "她买了一条类人的裙子。", "explanation": "这里应该用〈深蓝色〉。类人不用于描述颜色或款式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类人", "is_correct": true, "explanation": "正确：类人形容像人的表情，符合句中语境。"}, {"text": "金属", "is_correct": false, "explanation": "语义：金属指材料，与表情的意思不符。"}, {"text": "陶瓷", "is_correct": false, "explanation": "语义：陶瓷指材料，与表情的意思不符。"}, {"text": "平整", "is_correct": false, "explanation": "体貌：平整描写表面是否平坦，不用于形容表情。"}], "explanations": {"类人": "正确：类人形容像人的表情，符合句中语境。", "金属": "语义：金属指材料，与表情的意思不符。", "陶瓷": "语义：陶瓷指材料，与表情的意思不符。", "平整": "体貌：平整描写表面是否平坦，不用于形容表情。"}, "sentence_index": 6, "correct_answer": "类人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面墙是类人的，摸起来很光滑。", "explanation": "这里应该用〈平整〉。类人指像人的外形、行为或智能，不用于描述墙面。"}, {"text": "这些花是类人的，不会谢。", "explanation": "这里应该用〈人工〉。人工指人造的物品，类人指像人的特征，不说明事物是否人造。"}, {"text": "这是一杯类人的牛奶，还是热的。", "explanation": "这里应该用〈新鲜〉。类人指像人的特征，不能用来形容牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机器人有类人地动作，看起来很自然。", "corrected_sentence": "这个机器人有类人的动作，看起来很自然。", "error_description": "错误：定语标记用错。类人修饰名词“动作”，应用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她设计了一个类人地小熊，会眨眼睛。", "corrected_sentence": "她设计了一个类人的小熊，会眨眼睛。", "error_description": "错误：定语标记用错。“类人”修饰名词“小熊”，应用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
