INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮助、辅助别人完成某项工作或活动。", "primary_collocate": null, "pronunciation": "xié zhù", "ipa": "ɕi̯ɛ˧˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "协助", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "同事协助我完成了这份报告。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你协助经理安排明天的会议。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察请大家协助调查这件事。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在朋友的协助下，他找到了工作。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生协助她整理资料。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派两个人协助我们做这个项目。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你协助我们完成任务。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾协助过很多新同事。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在护士的协助下做完了检查。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协助了", "label": "体标（完成）"}, {"form": "协助过", "label": "体标（经历）"}], "register": "书面", "sense_fingerprint": "协助：辅助他人完成工作或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助（xié zhù）：帮助他人完成工作或活动。"}, {"text": "截住", "is_correct": false, "explanation": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。"}, {"text": "邪术", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。"}, {"text": "借住", "is_correct": false, "explanation": "jiè（第四声）与 xié 声母和声调都不同，“借住”意思是暂时住在别人家里。"}], "explanations": {"协助": "协助（xié zhù）：帮助他人完成工作或活动。", "截住": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。", "邪术": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。", "借住": "jiè（第四声）与 xié 声母和声调都不同，“借住”意思是暂时住在别人家里。"}, "sentence_index": null, "correct_answer": "协助"}, "level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：辅助科研工作者梳理文献，与后文“认知协作者”的角色相合。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥讽他人，与帮人梳理文献、提出建议的助益功能相矛盾。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”是妨碍，与“提取证据、提出建议”的助益功能相矛盾。"}, {"text": "参与", "is_correct": false, "explanation": "配价：“参与”的宾语应是活动或事件，不能直接以“科研工作者”作宾语。"}], "explanations": {"协助": "协助：辅助科研工作者梳理文献，与后文“认知协作者”的角色相合。", "嘲笑": "语义：“嘲笑”是讥讽他人，与帮人梳理文献、提出建议的助益功能相矛盾。", "阻碍": "语义：“阻碍”是妨碍，与“提取证据、提出建议”的助益功能相矛盾。", "参与": "配价：“参与”的宾语应是活动或事件，不能直接以“科研工作者”作宾语。"}, "sentence_index": 0, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈始终协助我的选择。", "explanation": "这里应该用〈支持〉。协助指帮别人完成具体的工作或活动，不用于对选择表态；支持可以表示站在某人一边。"}, {"text": "妈妈每天协助我睡觉。", "explanation": "这里应该用〈哄〉。协助指帮别人完成具体工作或活动，不用于哄孩子入睡这类照料。"}, {"text": "我们要协助国家的利益。", "explanation": "这里应该用〈维护〉。协助是帮别人完成事务，利益需要的是维护，不能说协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：公司派人帮我们完成项目，正合语境。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”的对象是物品，不能带“我们做这个项目”这样的人加动作。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽的态度，与派人帮忙的正面语境不符。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”的宾语应是物体，“我们做这个项目”不能作其宾语。"}], "explanations": {"协助": "协助：公司派人帮我们完成项目，正合语境。", "修理": "配价：“修理”的对象是物品，不能带“我们做这个项目”这样的人加动作。", "嘲笑": "语义：“嘲笑”带有讥讽的态度，与派人帮忙的正面语境不符。", "搬运": "配价：“搬运”的宾语应是物体，“我们做这个项目”不能作其宾语。"}, "sentence_index": 6, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们协助远道而来的朋友吃了一顿饭。", "explanation": "这里应该用〈招待〉。协助是帮对方完成工作或事务，请客吃饭应说招待，不能说协助。"}, {"text": "朋友很伤心，他协助了她几句。", "explanation": "这里应该用〈安慰〉。协助指帮别人完成具体工作，不能用于用话语安抚情绪。"}, {"text": "老板协助员工的身体健康。", "explanation": "这里应该用〈关心〉。协助的对象是工作或事务，身体健康不能被协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他协助我了两次。", "corrected_sentence": "他协助了我两次。", "error_description": "错误：“了”放在宾语“我”之后。正确：“协助了我”，“了”紧跟动词“协助”，表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是协助做我家务。", "corrected_sentence": "他总是协助我做家务。", "error_description": "错误：“我”被放到了“做”后面，“做我家务”不成立。正确：“协助我做家务”，“我”是“协助”的对象，“做家务”是被协助的内容。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
