INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指从事某种职业或劳动的人。", "primary_collocate": null, "pronunciation": "gōng zuò zhě", "ipa": "kʊŋ˥ tswɔ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "例如，在协助从事科研的工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "工作者", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这些医务工作者每天很早就来上班。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育工作者们要按时完成手头的任务。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多环卫工作者在寒冷的天气里仍然坚持工作。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些社区工作者的收入不高，但他们很敬业。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里有许多服务工作者，他们默默为大家服务。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好的新闻工作者应该认真负责。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科技工作者需要不断学习新的知识。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的医务工作者都戴着口罩。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该支持年轻的文艺工作者。", "target_word": "工作者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "科技工作者", "label": "复合词"}, {"form": "医务工作者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "工作者：从事某种职业或劳动的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作者", "is_correct": true, "explanation": "工作者指从事某种职业或劳动的人，可以协助科研人员梳理文献。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是做饭的人，与“科研”及梳理跨学科文献的工作不符。"}, {"text": "设备", "is_correct": false, "explanation": "搭配：“协助”的对象应是人，不能说协助设备梳理文献。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人与科研工作无关，“协助科研”的对象不能是病人。"}], "explanations": {"工作者": "工作者指从事某种职业或劳动的人，可以协助科研人员梳理文献。", "厨师": "语义：厨师是做饭的人，与“科研”及梳理跨学科文献的工作不符。", "设备": "搭配：“协助”的对象应是人，不能说协助设备梳理文献。", "病人": "语义：病人与科研工作无关，“协助科研”的对象不能是病人。"}, "sentence_index": 0, "correct_answer": "工作者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司新来了一台工作者。", "explanation": "这里应该用〈名〉或〈位〉。台用于机器、设备，不用于人，工作者指人。"}, {"text": "他的工作者是一名医生。", "explanation": "这里应该用〈职业〉。职业指一个人长期从事的工作类别，应说“他的职业是医生”；工作者指做工作的人，不能用来指一个人的职业类别。"}, {"text": "工作者师傅正在修理水管。", "explanation": "这里应该用〈工人〉。工作者泛指做工作的人，不能与“师傅”这类对具体手艺人的称呼搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作者", "is_correct": true, "explanation": "工作者指从事职业的人，“认真负责”描述的正是从业人员的品质。"}, {"text": "机器", "is_correct": false, "explanation": "语义：“认真负责”描述的是人，机器不能认真负责。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：“认真负责”用于人的品质，不用于修饰文件。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是无生命的物体，不具备“认真负责”的品质。"}], "explanations": {"工作者": "工作者指从事职业的人，“认真负责”描述的正是从业人员的品质。", "机器": "语义：“认真负责”描述的是人，机器不能认真负责。", "文件": "搭配：“认真负责”用于人的品质，不用于修饰文件。", "窗户": "语义：窗户是无生命的物体，不具备“认真负责”的品质。"}, "sentence_index": 6, "correct_answer": "工作者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司有一座可靠的工作者。", "explanation": "这里应该用〈位〉或〈名〉。座多用于山、楼房等大型物体，不用于人。"}, {"text": "我家门口有一棵工作者。", "explanation": "这里应该用〈位〉或〈名〉。棵用于树木，不用于人，工作者指人。"}, {"text": "这辆工作者开得很快。", "explanation": "这里应该用〈位〉或〈名〉。辆用于车辆，不用于人，工作者指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅有一只工作者。", "corrected_sentence": "这家餐厅有一名工作者。", "error_description": "量词错误：“只”用于动物等，指人应说“一名”或“一位”，应改为“这家餐厅有一名工作者。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要一名工作者们。", "corrected_sentence": "我们需要一名工作者。", "error_description": "“们”表示复数，不能与数量词“一名”同用，应去掉“们”，说“我们需要一名工作者。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
