INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指或工具整理头发、毛羽等，使顺畅。", "primary_collocate": null, "pronunciation": "shū lǐ", "ipa": "ʂu˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "例如，在帮母亲打理长发时，她一缕一缕地梳理，直到每根头发都顺滑整齐，这比任何护理都更能让人安心。", "target_word": "梳理", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "妈妈在给女儿梳理长长的头发。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上起来，他先梳理一下头发。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟用嘴梳理自己的羽毛。", "target_word": "梳理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她坐在镜子前，慢慢梳理着头发。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风把头发吹乱了，我用手指梳理了几下。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫舔着爪子，梳理自己身上的毛。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理发师小心地梳理客人的头发，然后剪短。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的白头发很乱，我帮她梳理整齐。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完澡，她用梳子梳理湿头发。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "梳理了", "label": "完成体"}, {"form": "梳理着", "label": "持续体"}, {"form": "梳理过", "label": "经历体"}, {"form": "梳理梳理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用手指或梳子把头发、羽毛等理顺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梳理", "is_correct": true, "explanation": "正确：梳理（shū lǐ），用手或梳子把头发、羽毛理顺。"}, {"text": "树立", "is_correct": false, "explanation": "shù lì 与 shū lǐ 两个字声调都不同（第四声对第一声、第四声对第三声），树立意思是建立，与头发无关。"}, {"text": "数理", "is_correct": false, "explanation": "shù 与 shū 声调不同，数理指数学和物理，与整理头发无关。"}, {"text": "疏离", "is_correct": false, "explanation": "lí（第二声）与 lǐ（第三声）声调不同，疏离意思是关系疏远，与头发无关。"}], "explanations": {"梳理": "正确：梳理（shū lǐ），用手或梳子把头发、羽毛理顺。", "树立": "shù lì 与 shū lǐ 两个字声调都不同（第四声对第一声、第四声对第三声），树立意思是建立，与头发无关。", "数理": "shù 与 shū 声调不同，数理指数学和物理，与整理头发无关。", "疏离": "lí（第二声）与 lǐ（第三声）声调不同，疏离意思是关系疏远，与头发无关。"}, "sentence_index": null, "correct_answer": "梳理"}, "level_3": {"options": [{"text": "梳理", "is_correct": true, "explanation": "梳理：用梳子或手指一缕一缕理顺头发，正合语境。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是栽种植物，不能用于理顺头发，与句意不符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于清除脏物，不用于理顺头发。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，头发不能被煮，与句意不符。"}], "explanations": {"梳理": "梳理：用梳子或手指一缕一缕理顺头发，正合语境。", "种植": "语义：种植是栽种植物，不能用于理顺头发，与句意不符。", "打扫": "搭配：“打扫”用于清除脏物，不用于理顺头发。", "煮": "语义：“煮”是烹饪动作，头发不能被煮，与句意不符。"}, "sentence_index": 0, "correct_answer": "梳理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把房间梳理得很干净。", "explanation": "这里应该用〈整理〉。整理可用于房间、物品，梳理只用于理顺头发、羽毛等，不用于房间。"}, {"text": "她用毛巾梳理干头发。", "explanation": "这里应该用〈擦〉。毛巾用于擦干，梳理是用梳子或手指理顺，不用于吸干水分。"}, {"text": "她用肥皂梳理脏衣服。", "explanation": "这里应该用〈洗〉。洗用于去除污垢，梳理只表示理顺，不表示去脏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "梳理", "is_correct": true, "explanation": "梳理指用手或梳子理顺毛发，与猫用舌头整理身上的毛相符。"}, {"text": "熨", "is_correct": false, "explanation": "语义：熨是用熨斗烫平，猫不能熨自己身上的毛。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤需要火源加热，与猫舔毛的动作不符。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“舔着爪子”的动作与“剪”不搭配，猫整理毛不用剪。"}], "explanations": {"梳理": "梳理指用手或梳子理顺毛发，与猫用舌头整理身上的毛相符。", "熨": "语义：熨是用熨斗烫平，猫不能熨自己身上的毛。", "烤": "语义：烤需要火源加热，与猫舔毛的动作不符。", "剪": "搭配：“舔着爪子”的动作与“剪”不搭配，猫整理毛不用剪。"}, "sentence_index": 6, "correct_answer": "梳理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用砂纸梳理粗糙的木板。", "explanation": "这里应该用〈打磨〉。梳理只用于理顺头发、羽毛等，不用于打磨木板。"}, {"text": "他把树枝梳理得很整齐。", "explanation": "这里应该用〈修剪〉。修剪用于树枝、草木，梳理用于头发、羽毛等，不能用于树枝。"}, {"text": "他用刀梳理掉了胡子。", "explanation": "这里应该用〈刮〉。梳理只表示理顺，不表示去掉、剪掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把长发梳理很整齐。", "corrected_sentence": "她把长发梳理得很整齐。", "error_description": "补语标记错误：“很整齐”作结果补语时需要用“得”引出，应说“梳理得很整齐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在梳理过湿头发。", "corrected_sentence": "她正在梳理湿头发。", "error_description": "“过”表示经历，与“正在”表示进行冲突，应去掉“过”，说“她正在梳理湿头发。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了进行推理或论述，暂时认定某种情况为真的想法或前提。", "primary_collocate": null, "pronunciation": "jiǎ shè", "ipa": "tɕja˨˩˦ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "假设", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个假设很有意思。", "target_word": "假设", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师请我们先提出一个假设。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做实验以前，我们要先有假设。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个假设后来被实验证明是对的。", "target_word": "假设", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "他的假设没有证据，所以大家不同意。", "target_word": "假设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果假设错了，结论就不对。", "target_word": "假设", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "科学家先提出假设，再做实验验证。", "target_word": "假设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一个假设，还不是事实。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生用数据检验自己的假设。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个假设", "label": "量词"}, {"form": "假設", "label": "繁体"}], "register": "中性", "sense_fingerprint": "推理或研究中暂时认定为真的前提或想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "假设", "is_correct": true, "explanation": "正确：假设是研究中暂时认定为真的前提，可以被提取，与“实验证据”配合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：文献中提取的应是前提与证据等学术内容，“颜色”与此无关，句意说不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“提取”的对象应是学术内容，“钥匙”与此无关，句意说不通。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“提取”通常接要点、数据、证据，不接“名声”。"}], "explanations": {"假设": "正确：假设是研究中暂时认定为真的前提，可以被提取，与“实验证据”配合。", "颜色": "语义：文献中提取的应是前提与证据等学术内容，“颜色”与此无关，句意说不通。", "钥匙": "语义：“提取”的对象应是学术内容，“钥匙”与此无关，句意说不通。", "名声": "搭配：“提取”通常接要点、数据、证据，不接“名声”。"}, "sentence_index": 0, "correct_answer": "假设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个假设很有创意，要在下个月实施。", "explanation": "这里应该用〈设想〉。设想是对未来做法的构想，可以付诸实施；假设是用来推理论证的前提，不能“实施”。"}, {"text": "我把这个假设放进冰箱里了。", "explanation": "这里应该用〈饮料〉。饮料是实物，可以放进冰箱；假设是推理用的前提，是抽象的想法，不能放进冰箱。"}, {"text": "我们先制定假设，再开始实验。", "explanation": "这里应该用〈计划〉。制定的是计划或方案，假设应说“提出”，不能“制定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假设", "is_correct": true, "explanation": "正确：假设是暂时认定为真的前提，“如果……错了，结论就不对”正说明它的作用。"}, {"text": "口味", "is_correct": false, "explanation": "语义：“口味”不是推理的前提，“如果口味错了，结论就不对”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的器物，不是推理的前提，“如果书包错了，结论就不对”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是日用物品，不能作为推理的前提，“如果雨伞错了，结论就不对”说不通。"}], "explanations": {"假设": "正确：假设是暂时认定为真的前提，“如果……错了，结论就不对”正说明它的作用。", "口味": "语义：“口味”不是推理的前提，“如果口味错了，结论就不对”说不通。", "书包": "语义：“书包”是装东西的器物，不是推理的前提，“如果书包错了，结论就不对”说不通。", "雨伞": "语义：“雨伞”是日用物品，不能作为推理的前提，“如果雨伞错了，结论就不对”说不通。"}, "sentence_index": 6, "correct_answer": "假设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他算出了这道题的假设。", "explanation": "这里应该用〈答案〉。算出的是答案或结果；假设是尚未证实的前提，不能“算出”。"}, {"text": "这个假设可以降低成本。", "explanation": "这里应该用〈方案〉。方案是可以付诸实施的做法，能降低成本；假设是推理论证的前提，不能用来降低成本。"}, {"text": "他把假设装进书包，带去了学校。", "explanation": "这里应该用〈课本〉。课本是实物，可以装进书包；假设是推理用的前提，是抽象的想法，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了一只新的假设。", "corrected_sentence": "他提出了一个新的假设。", "error_description": "错误：量词“只”用错。“假设”是抽象名词，量词应用“个”；“只”多用于动物或成对的小物件。正确：他提出了一个新的假设。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把假设需要我们认真检验。", "corrected_sentence": "这个假设需要我们认真检验。", "error_description": "错误：量词“把”用错。“假设”不是可以手拿的器具，量词应用“个”。正确：这个假设需要我们认真检验。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
