INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于方法的理论体系，研究如何认识世界和改造世界的根本方法。", "primary_collocate": null, "pronunciation": "fāng fǎ lùn", "ipa": "faŋ˥ fa˨˩˦ lwən˥˩", "syllable_count": 3, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "方法论", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这本书讲的是科学方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上介绍了新的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的方法论，会得到不同的结果。", "target_word": "方法论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学的是哲学，常常谈方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授的方法论很有名。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花了十年时间，终于总结出一套认识世界的方法论。", "target_word": "方法论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位科学家的方法论完全不同。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的方法论能帮人少走弯路。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门课讲历史研究的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套方法论", "label": "量词"}, {"form": "方法論", "label": "繁体"}], "register": "书面", "sense_fingerprint": "关于认识和改造世界的方法的理论体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884d9f3f-532e-4ab3-9ab1-95e22aa6b1de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是关于方法的理论体系，可以产生“冲突”，与前文“识别”相合。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：文献研究中的冲突指观点、方法或证据之间的对立，“旋律冲突”与此无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，用在这样的学术描述中不协调。"}, {"text": "面貌", "is_correct": false, "explanation": "搭配：“冲突”多指观点、利益或目标之间的对立，不说“面貌冲突”。"}], "explanations": {"方法论": "正确：方法论是关于方法的理论体系，可以产生“冲突”，与前文“识别”相合。", "旋律": "语义：文献研究中的冲突指观点、方法或证据之间的对立，“旋律冲突”与此无关。", "玩意儿": "语域：“玩意儿”是口语，用在这样的学术描述中不协调。", "面貌": "搭配：“冲突”多指观点、利益或目标之间的对立，不说“面貌冲突”。"}, "sentence_index": 0, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法论解释了行星为什么绕太阳转。", "explanation": "这里应该用〈理论〉。理论用于解释现象；方法论是研究方法的理论体系，不能用来解释行星的运动。"}, {"text": "这套方法论修好了我的自行车。", "explanation": "这里应该用〈工具〉。修车要靠扳手等工具；方法论是理论体系，不能用来修车。"}, {"text": "他把方法论洗干净，放进冰箱。", "explanation": "这里应该用〈碗〉。碗可以洗，也能放进冰箱；方法论是抽象的理论，没有实体，不能当作器物处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是关于认识世界的方法的理论体系，可以“总结出一套”，正合“认识世界的”这一修饰。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“总结出”的对象应是理论或规律，“味道”无法被总结为认识世界的方法，句意不通。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：“认识世界的”修饰的应是理论或方法，“鞋码”只是尺寸，不能被总结出来，句意不通。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”是外在的形式，不是可以总结出的认识方法，“总结出一套……包装”句意不通。"}], "explanations": {"方法论": "正确：方法论是关于认识世界的方法的理论体系，可以“总结出一套”，正合“认识世界的”这一修饰。", "味道": "语义：“总结出”的对象应是理论或规律，“味道”无法被总结为认识世界的方法，句意不通。", "鞋码": "语义：“认识世界的”修饰的应是理论或方法，“鞋码”只是尺寸，不能被总结出来，句意不通。", "包装": "语义：“包装”是外在的形式，不是可以总结出的认识方法，“总结出一套……包装”句意不通。"}, "sentence_index": 6, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课的方法论很甜，同学们都爱吃。", "explanation": "这里应该用〈糖果〉。糖果有甜味、可以吃；方法论是抽象的理论，没有味道，也不能吃。"}, {"text": "这套方法论很重，我搬不动。", "explanation": "这里应该用〈石头〉。石头有重量，搬得动或搬不动；方法论是抽象的理论，没有重量，不能这样形容。"}, {"text": "他用方法论把门擦干净了。", "explanation": "这里应该用〈抹布〉。擦门要用抹布等清洁用具；方法论是理论体系，不能用来擦门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的研究遵循一颗严谨的方法论。", "corrected_sentence": "他的研究遵循一套严谨的方法论。", "error_description": "错误：量词“颗”用错。“颗”用于颗粒状的小物，方法论是抽象的理论体系，应用“套”。正确：他的研究遵循一套严谨的方法论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把这套方法论讲完着。", "corrected_sentence": "老师把这套方法论讲完了。", "error_description": "体标错误：“讲完”是结果补语，表示动作已完成，应接完成体“了”；“着”表示持续状态，与已完成的结果不相容。正确：老师把这套方法论讲完了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965f70a5-eb80-4321-9df5-249b724f76ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
