INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指带有尝试性质的行为或态度，目的是观察结果或对方反应。", "primary_collocate": null, "pronunciation": "shì tàn xìng", "ipa": "ʂɻ̩˥˩ tʰan˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "试探性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他先问了一个试探性的问题，想看看老板怎么想。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司先做了试探性的调整，再看客户有什么反应。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她试探性地问我：“你想不想换工作？”", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是试探性的做法，大家不用太紧张。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用试探性的语气说话，怕朋友不高兴。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先做了一个试探性的小测验，看看学生会不会。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次试探性的投票，结果会决定我们下一步怎么做。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子试探性地碰了碰小狗，发现它不咬人。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店先卖少量新产品，这是试探性的销售。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "带有尝试性质、用来观察反应的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350e46f9-b0cc-46b5-afe7-c34cc96c73df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "试探性", "is_correct": true, "explanation": "正确：“试探性”修饰“建议”，表示带有尝试性质的建议，与前文“融合路径”的谨慎提议相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”说的是说话风格，修饰“融合路径”的建议时，与前文严谨的科研分析语境冲突。"}, {"text": "老掉牙", "is_correct": false, "explanation": "语域：“老掉牙”是口语色彩很强的说法，与这段书面化的学术表述不合。"}, {"text": "圆滚滚", "is_correct": false, "explanation": "体貌：“圆滚滚”描述外形，不能用来修饰“建议”这样的抽象事物。"}], "explanations": {"试探性": "正确：“试探性”修饰“建议”，表示带有尝试性质的建议，与前文“融合路径”的谨慎提议相符。", "幽默": "语义：“幽默”说的是说话风格，修饰“融合路径”的建议时，与前文严谨的科研分析语境冲突。", "老掉牙": "语域：“老掉牙”是口语色彩很强的说法，与这段书面化的学术表述不合。", "圆滚滚": "体貌：“圆滚滚”描述外形，不能用来修饰“建议”这样的抽象事物。"}, "sentence_index": 0, "correct_answer": "试探性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大桥是试探性的，已经通车多年。", "explanation": "“试探性”形容先试一试、看反应的做法或态度，不能用来形容已经建成、长期使用的大桥。"}, {"text": "他的身高是试探性的，已经有一米八了。", "explanation": "“试探性”形容做事的尝试态度，身高是固定的属性，不能用它来形容。"}, {"text": "这份合同的签字是试探性的，双方都很确定。", "explanation": "签字是有法律效力的正式行为，不能说成“试探性”；“试探性”只用来形容尝试性的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试探性", "is_correct": true, "explanation": "正确：“试探性”修饰“小测验”，表示先试一下、观察学生反应的测验，与“看看学生会不会”相合。"}, {"text": "圆滚滚", "is_correct": false, "explanation": "体貌：“圆滚滚”描述外形，不能用来修饰“小测验”这样的事物。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”表示情绪，与“小测验”的做法和用途不合。"}, {"text": "绿油油", "is_correct": false, "explanation": "体貌：“绿油油”描述颜色和外观，不能用来修饰测验。"}], "explanations": {"试探性": "正确：“试探性”修饰“小测验”，表示先试一下、观察学生反应的测验，与“看看学生会不会”相合。", "圆滚滚": "体貌：“圆滚滚”描述外形，不能用来修饰“小测验”这样的事物。", "悲伤": "语义：“悲伤”表示情绪，与“小测验”的做法和用途不合。", "绿油油": "体貌：“绿油油”描述颜色和外观，不能用来修饰测验。"}, "sentence_index": 6, "correct_answer": "试探性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他试探性地一口气吃完了一整个西瓜，连皮都没剩。", "explanation": "这里应该用〈痛快〉。“试探性”只指先尝一尝，吃完一整个西瓜是尽兴地吃，应说“痛快”。"}, {"text": "他试探性地解开了全部谜题，给出了标准答案。", "explanation": "这里应该用〈确定〉。解开谜题并给出标准答案是确定的结果，“试探性”强调的是先试一试。"}, {"text": "这场比赛的冠军是试探性的，大家都已经认定了。", "explanation": "冠军是确定的结果，不能用“试探性”形容；“试探性”只用于尚在尝试的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她试探性的问了我一个问题。", "corrected_sentence": "她试探性地问了我一个问题。", "error_description": "错误在“试探性”后的“的”。“试探性”修饰动词“问”时要用“地”，“的”用于修饰名词，应改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们先做了一把试探性的改版，再观察用户的反应。", "corrected_sentence": "他们先做了一次试探性的改版，再观察用户的反应。", "error_description": "错误在“改版”前的量词。“改版”要用“次”计量，“把”用于有柄的器具，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
