INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20033, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在同一个项目或任务中共同工作的人。", "primary_collocate": null, "pronunciation": "xié zuò zhě", "ipa": "ɕje˧˥ tsuo˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "在这个跨学科课题中，不同领域的人需要互相补位：有人梳理文献，有人设计实验，真正能推动进展的，往往是那位既懂数据又肯分享思路的协作者。", "target_word": "协作者", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他是我们项目里最可靠的协作者。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位协作者每天都准时完成自己的任务。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和协作者一起写了这份报告。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要找一位懂设计的协作者。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们既是好朋友，也是很好的协作者。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目结束后，协作者们一起吃了饭。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这个课题组里经验最多的协作者。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协作者一直不回消息，工作没法继续。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个小组安排了一位协作者。", "target_word": "协作者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "协作者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "在同一项目或任务中与人共同工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20033, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "协作者", "is_correct": true, "explanation": "正确：“协作者”指共同做事的人，句中“既懂数据又肯分享思路的”描述的正是合作伙伴。"}, {"text": "对手", "is_correct": false, "explanation": "语义：“对手”与“肯分享思路”的合作态度相反。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众只看不参与，与“肯分享思路”的合作语境不符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客与课题无关，不会“分享思路”，与合作者的语境不符。"}], "explanations": {"协作者": "正确：“协作者”指共同做事的人，句中“既懂数据又肯分享思路的”描述的正是合作伙伴。", "对手": "语义：“对手”与“肯分享思路”的合作态度相反。", "观众": "语义：观众只看不参与，与“肯分享思路”的合作语境不符。", "乘客": "语义：乘客与课题无关，不会“分享思路”，与合作者的语境不符。"}, "sentence_index": 0, "correct_answer": "协作者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的协作者很热情，经常帮我们照看孩子。", "explanation": "这里应该用〈邻居〉。协作者指在同一个项目中共同工作的人，不指住在附近、帮忙照看孩子的人。"}, {"text": "这家店的协作者很多，每天都排长队。", "explanation": "这里应该用〈顾客〉。协作者指共同工作的人，不指来店里买东西的人。"}, {"text": "医院里的协作者都在等医生叫号。", "explanation": "这里应该用〈病人〉。协作者指共同做事的人，不指在医院看病、等待叫号的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协作者", "is_correct": true, "explanation": "正确：指共同做事的人，“项目结束后一起吃饭”说的是项目成员。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物体，不能吃饭，“窗户们一起吃了饭”不成立。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：路灯是物体，不能吃饭，与句中项目成员聚餐的语境不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不能吃饭，与句中项目成员聚餐的语境不符。"}], "explanations": {"协作者": "正确：指共同做事的人，“项目结束后一起吃饭”说的是项目成员。", "窗户": "语义：窗户是物体，不能吃饭，“窗户们一起吃了饭”不成立。", "路灯": "语义：路灯是物体，不能吃饭，与句中项目成员聚餐的语境不符。", "石头": "语义：石头是物体，不能吃饭，与句中项目成员聚餐的语境不符。"}, "sentence_index": 6, "correct_answer": "协作者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位协作者每个月都来收房租，我们很烦。", "explanation": "这里应该用〈房东〉。协作者指在同一个项目中共同工作的人，不指出租房子、收房租的人。"}, {"text": "那支球队的协作者一直在和我们抢分，我们压力很大。", "explanation": "这里应该用〈对手〉。协作者是一起工作的人，与我们抢分的是对手。"}, {"text": "景区里的协作者很多，大家排队买票。", "explanation": "这里应该用〈游客〉。协作者指共同做事的人，不指到景区参观、排队买票的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的项目来了一只协作者，帮我整理了文献。", "corrected_sentence": "我的项目来了一位协作者，帮我整理了文献。", "error_description": "量词错误：“只”用于动物，指人的“协作者”应用“位”。应为“来了一位协作者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我协作者一起工作，项目进展很快。", "corrected_sentence": "我和协作者一起工作，项目进展很快。", "error_description": "缺少介词“和”：表示共同做事的对象要用“和”引出，应为“我和协作者一起工作”；“我协作者”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
