INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "悖论指表面上自相矛盾或荒谬，但实际可能包含正确逻辑的陈述或命题。", "primary_collocate": null, "pronunciation": "bèi lùn", "ipa": "pei˥˩ luən˥˩", "syllable_count": 2, "sentences": [{"text": "然而，其范式革命性亦伴随深刻的风险悖论。", "target_word": "悖论", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一个有名的逻辑悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一个有趣的悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我在说谎”是一个著名的悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话听起来对，其实是个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，还是解不开这个悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有很多关于时间的悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了解释这个悖论，科学家做了实验。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越想自由，越被规则困住，这是一种悖论。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个悖论让很多哲学家想了几百年。", "target_word": "悖论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "逻辑悖论", "label": "复合词"}], "register": "书面", "sense_fingerprint": "表面矛盾或荒谬却可能蕴含正确逻辑的命题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悖论", "is_correct": true, "explanation": "正确：“悖论”是抽象的命题，可以被“深刻的”修饰，与“风险”搭配，符合句子语境。"}, {"text": "奇迹", "is_correct": false, "explanation": "语义：“奇迹”指令人惊叹的好事，与“风险”的负面含义冲突，不能作“伴随”的结果。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与书面语体的“范式革命性”不协调。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：“疾病”指身体的病痛，不是抽象的风险，不能与“风险”并列作后果。"}], "explanations": {"悖论": "正确：“悖论”是抽象的命题，可以被“深刻的”修饰，与“风险”搭配，符合句子语境。", "奇迹": "语义：“奇迹”指令人惊叹的好事，与“风险”的负面含义冲突，不能作“伴随”的结果。", "玩意儿": "语域：“玩意儿”是口语说法，与书面语体的“范式革命性”不协调。", "疾病": "语义：“疾病”指身体的病痛，不是抽象的风险，不能与“风险”并列作后果。"}, "sentence_index": 0, "correct_answer": "悖论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家在实验室里摔了一个悖论。", "explanation": "这里应该用〈试管〉。“摔”的对象是试管、杯子之类的器物，悖论是抽象的命题，不能摔。"}, {"text": "他拿起一个悖论，放进了冰箱。", "explanation": "这里应该用〈牛奶〉。“放进冰箱”的对象是食物或饮料，悖论是抽象的命题，不能放进冰箱。"}, {"text": "他拍了一个悖论。", "explanation": "这里应该用〈照片〉。“拍”的对象是照片、视频，悖论是抽象的命题，不能拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悖论", "is_correct": true, "explanation": "正确：“悖论”是抽象的命题，书中讲的关于时间的内容正是悖论，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指视觉属性，不能作为“关于时间”的内容。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是买卖中的数字，与“关于时间”的内容无关。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人的体形，不能用来指书中讲的内容。"}], "explanations": {"悖论": "正确：“悖论”是抽象的命题，书中讲的关于时间的内容正是悖论，符合语境。", "颜色": "语义：“颜色”指视觉属性，不能作为“关于时间”的内容。", "价格": "语义：“价格”是买卖中的数字，与“关于时间”的内容无关。", "身材": "语义：“身材”指人的体形，不能用来指书中讲的内容。"}, "sentence_index": 6, "correct_answer": "悖论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天吃了一个悖论。", "explanation": "这里应该用〈蛋糕〉。“吃”的对象是食物，悖论是抽象的命题，不能吃。"}, {"text": "昨天晚上天上下了一场悖论。", "explanation": "这里应该用〈雨〉。“下了一场”的对象是雨、雪等天气现象，悖论是抽象的命题，不能说“下”。"}, {"text": "这个悖论的电池很耐用。", "explanation": "这里应该用〈手机〉。“电池”属于手机、电脑等电器，悖论是抽象的命题，没有电池，不能说“电池耐用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把这只悖论讲得很清楚。", "corrected_sentence": "老师把这个悖论讲得很清楚。", "error_description": "“悖论”是抽象的命题，量词应用“个”。“只”多用于动物，不能修饰“悖论”。应改为：老师把这个悖论讲得很清楚。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了很长时间才想通这张悖论。", "corrected_sentence": "他花了很长时间才想通这个悖论。", "error_description": "“张”用于纸、桌子等平面的东西，“悖论”是抽象的命题，量词应用“个”。应改为：他花了很长时间才想通这个悖论。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
