INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20037, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "加密技术是利用数学和计算机算法，将普通信息（明文）转换为无法直接理解的密文，只有持有正确密钥的人才能解密还原信息的技术。", "primary_collocate": null, "pronunciation": "jiā mì jì shù", "ipa": "tɕja˥ mi˥˩ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "尽管系统采用了加密技术与联邦学习，但代理在多设备间同步的“意图模型”本身可能成为新型敏感信息载体。", "target_word": "加密技术", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "银行用加密技术保护客户的信息。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加密技术能让别人看不懂你的消息。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件用了最新的加密技术。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的照片也需要加密技术来保护。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里研究加密技术。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有加密技术，网上购物就不安全。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的加密技术很先进。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聊天软件靠加密技术保护我们的隐私。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学过加密技术的人知道什么是密钥。", "target_word": "加密技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项加密技术", "label": "量词"}], "register": "科技", "sense_fingerprint": "用算法把明文变成密文，只有持密钥者才能还原的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350e46f9-b0cc-46b5-afe7-c34cc96c73df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建材，不是加密方法，与“联邦学习”并列不成立，句子不通。"}, {"text": "老大", "is_correct": false, "explanation": "语义：“老大”指人或排行第一的人，不是一种技术，不能与“联邦学习”并列被系统采用。"}, {"text": "加密技术", "is_correct": true, "explanation": "正确。“采用了加密技术与联邦学习”中，“加密技术”是与“联邦学习”并列的技术手段，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是加密手段，句子无法理解。"}], "explanations": {"水泥": "语义：水泥是建材，不是加密方法，与“联邦学习”并列不成立，句子不通。", "老大": "语义：“老大”指人或排行第一的人，不是一种技术，不能与“联邦学习”并列被系统采用。", "加密技术": "正确。“采用了加密技术与联邦学习”中，“加密技术”是与“联邦学习”并列的技术手段，符合句意。", "冰箱": "语义：冰箱是家电，不是加密手段，句子无法理解。"}, "sentence_index": 0, "correct_answer": "加密技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把手机的加密技术当成了门票，直接拿去检票。", "explanation": "此处应用〈门票〉。“加密技术”是方法，不能当门票拿去检票。"}, {"text": "我家大门的加密技术生锈了，打不开。", "explanation": "此处应用〈锁〉。会生锈、打不开的是“锁”；“加密技术”不是实物，不会生锈。"}, {"text": "他刷了加密技术，进了大楼。", "explanation": "此处应用〈门禁卡〉。刷的是“门禁卡”；“加密技术”是方法，不能被刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”不能作为网络安全的内容，“没有午饭，网上购物就不安全”句意不通。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是运动器材，与网上购物的安全无关，句子不通。"}, {"text": "加密技术", "is_correct": true, "explanation": "正确。“没有加密技术，网上购物就不安全”，“加密技术”是保障网上交易安全的手段。"}, {"text": "老头", "is_correct": false, "explanation": "语义：“老头”指老年男性，不能作为网上购物安全的保障，句子不通。"}], "explanations": {"午饭": "语义：“午饭”不能作为网络安全的内容，“没有午饭，网上购物就不安全”句意不通。", "篮球": "语义：篮球是运动器材，与网上购物的安全无关，句子不通。", "加密技术": "正确。“没有加密技术，网上购物就不安全”，“加密技术”是保障网上交易安全的手段。", "老头": "语义：“老头”指老年男性，不能作为网上购物安全的保障，句子不通。"}, "sentence_index": 6, "correct_answer": "加密技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把加密技术装进了书包，背着去上学了。", "explanation": "此处应用〈书〉。“加密技术”是方法，不能装进书包；装进书包的是书。"}, {"text": "我的电脑中了加密技术，只好重装系统。", "explanation": "此处应用〈病毒〉。电脑可以“中病毒”，“加密技术”不能被电脑“中”。"}, {"text": "他用加密技术打开了箱子。", "explanation": "此处应用〈钥匙〉。用“钥匙”开锁，“加密技术”不能用来打开箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件用了一条加密技术。", "corrected_sentence": "这个软件用了一项加密技术。", "error_description": "量词错误：“加密技术”应用“项”或“种”，“条”用于细长的东西，不能修饰“加密技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学过加密技术过。", "corrected_sentence": "他学过加密技术。", "error_description": "错误：经历体“过”重复出现，句末多了一个“过”。正确：只保留紧跟动词的一个“过”，写作“他学过加密技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb3844a-d98c-4257-86ea-b1110a3aa7df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
