INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "希望达到某种目的的想法或打算。", "primary_collocate": null, "pronunciation": "yì tú", "ipa": "i˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "他的意图很简单，就是想多赚点钱。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不明白他这样做的意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师看出了他的真实意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他隐藏着自己的意图。", "target_word": "意图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告的意图很明显。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在调查他的意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话没有恶意，我理解她的意图。", "target_word": "意图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先说清楚你的意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写这本书的意图是帮助孩子学习。", "target_word": "意图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友早就猜到了我的意图。", "target_word": "意图", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "意图：想要达到某种目的的打算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c08a22b5-1600-4fdc-bce0-99a670ecd18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意图", "is_correct": true, "explanation": "意图 yìtú：正确答案，指想达到某种目的的打算。"}, {"text": "议题", "is_correct": false, "explanation": "议题 yìtí 与 yìtú 第二音节韵母不同（í 与 ú），意思是讨论的问题。"}, {"text": "地图", "is_correct": false, "explanation": "地图 dìtú（第四声）与 yìtú 声母不同（d 与零声母），意思是地图。"}, {"text": "异读", "is_correct": false, "explanation": "异读 yìdú 第二音节声母为 d，yìtú 为 t，意思是同一个字的不同读音。"}, {"text": "一途", "is_correct": false, "explanation": "一途 yītú（第一声）与 yìtú 声调不同，意思是一条道路。"}], "explanations": {"意图": "意图 yìtú：正确答案，指想达到某种目的的打算。", "议题": "议题 yìtí 与 yìtú 第二音节韵母不同（í 与 ú），意思是讨论的问题。", "地图": "地图 dìtú（第四声）与 yìtú 声母不同（d 与零声母），意思是地图。", "异读": "异读 yìdú 第二音节声母为 d，yìtú 为 t，意思是同一个字的不同读音。", "一途": "一途 yītú（第一声）与 yìtú 声调不同，意思是一条道路。"}, "sentence_index": null, "correct_answer": "意图"}, "level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不能说“体重……就是想多赚点钱”。"}, {"text": "意图", "is_correct": true, "explanation": "意图：指他想达到的目的，后句“就是想多赚点钱”正说明这个打算。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是身体的高度，与“想多赚点钱”的打算无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指滋味或气味，不能表示人的打算。"}], "explanations": {"体重": "语义：“体重”是身体的重量，不能说“体重……就是想多赚点钱”。", "意图": "意图：指他想达到的目的，后句“就是想多赚点钱”正说明这个打算。", "身高": "语义：“身高”是身体的高度，与“想多赚点钱”的打算无关。", "味道": "语义：“味道”指滋味或气味，不能表示人的打算。"}, "sentence_index": 0, "correct_answer": "意图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他制定了一个意图，明年开始执行。", "explanation": "这里应该用〈计划〉。“制定”搭配计划、方案；意图指心里想做某事的想法，不说“制定意图”。"}, {"text": "他想出了一个意图，大家都很赞同。", "explanation": "这里应该用〈主意〉。“想出”搭配主意、办法；意图是心里的想法，与“想出”不搭。"}, {"text": "他定下了一个意图，要在考试前完成。", "explanation": "这里应该用〈目标〉。“定下”搭配目标；意图指想做某事的想法，不能用“定下”来限定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20038, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意图", "is_correct": true, "explanation": "意图 yìtú：正确答案，指想达到某种目的的打算。"}, {"text": "试图", "is_correct": false, "explanation": "试图 shìtú 与 yìtú 声母不同（sh 与零声母），意思是尝试做某事。"}, {"text": "力图", "is_correct": false, "explanation": "力图 lìtú 与 yìtú 声母不同（l 与零声母），意思是努力想要做到。"}, {"text": "地图", "is_correct": false, "explanation": "地图 dìtú（第四声）与 yìtú 声母不同（d 与零声母），意思是地图。"}], "explanations": {"意图": "意图 yìtú：正确答案，指想达到某种目的的打算。", "试图": "试图 shìtú 与 yìtú 声母不同（sh 与零声母），意思是尝试做某事。", "力图": "力图 lìtú 与 yìtú 声母不同（l 与零声母），意思是努力想要做到。", "地图": "地图 dìtú（第四声）与 yìtú 声母不同（d 与零声母），意思是地图。"}, "sentence_index": null, "correct_answer": "意图"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“理解”后接“身高”不合语境，人的身高无法被“理解”成她的打算。"}, {"text": "意图", "is_correct": true, "explanation": "意图：指她说话时的打算，与前句“没有恶意”前后呼应。"}, {"text": "恶意", "is_correct": false, "explanation": "语义：前句说“没有恶意”，“恶意”与之矛盾，无法被理解。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“理解”通常接心思或打算，不能接“嗓音”。"}], "explanations": {"身高": "搭配：“理解”后接“身高”不合语境，人的身高无法被“理解”成她的打算。", "意图": "意图：指她说话时的打算，与前句“没有恶意”前后呼应。", "恶意": "语义：前句说“没有恶意”，“恶意”与之矛盾，无法被理解。", "嗓音": "搭配：“理解”通常接心思或打算，不能接“嗓音”。"}, "sentence_index": 6, "correct_answer": "意图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心里藏着一只意图，谁也不知道。", "explanation": "这里的量词应为〈个〉或〈种〉。“只”多用于动物或成对的东西，抽象的意图不用“只”计量。"}, {"text": "他一直揣着一条意图，不肯说出来。", "explanation": "这里的量词应为〈个〉或〈种〉。“条”用于细长的物体，抽象的意图不能用“条”计量。"}, {"text": "他手里握着一把意图，随时准备使用。", "explanation": "这里的量词应为〈个〉或〈种〉。“把”用于有柄的器具，抽象的意图不用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他那只意图谁也没看透。", "corrected_sentence": "他那个意图谁也没看透。", "error_description": "量词错误：“意图”的量词应为“个”或“种”，不能用“只”；“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我终于看出了他的意图的。", "corrected_sentence": "我终于看出了他的意图。", "error_description": "句末多出“的”，“意图”后不能再接“的”结束句子。错误形式：意图的；正确形式：意图。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20039, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“相似”相对，指事物之间共同点少、差别大，是反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”形容质地硬，与“相似”没有反义关系。"}, {"text": "清澈", "is_correct": false, "explanation": "“清澈”形容水或眼神清亮透明，与“相似”不构成反义。"}, {"text": "遥远", "is_correct": false, "explanation": "“遥远”形容距离大，与“相似”所说的共同点无关。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“相似”相对，指事物之间共同点少、差别大，是反义关系。", "坚硬": "“坚硬”形容质地硬，与“相似”没有反义关系。", "清澈": "“清澈”形容水或眼神清亮透明，与“相似”不构成反义。", "遥远": "“遥远”形容距离大，与“相似”所说的共同点无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20039, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“相似”相对，指事物之间共同点少、差别大，是反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“相似”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容地势倾斜度大，与“相似”无关。"}, {"text": "宽广", "is_correct": false, "explanation": "“宽广”形容面积或范围大，与“相似”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“相似”相对，指事物之间共同点少、差别大，是反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“相似”没有反义关系。", "陡峭": "“陡峭”形容地势倾斜度大，与“相似”无关。", "宽广": "“宽广”形容面积或范围大，与“相似”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20039, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物之间具有共同点或相近的特征。", "primary_collocate": null, "pronunciation": "xiāng sì", "ipa": "ɕjɑŋ˥ sɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "更严峻的是，若大量代理基于相似优化目标自发演化，可能催生群体性的行为趋同，进而形成“分布式认知霸权”——表面上去中心化的系统，实质上演变为隐蔽的价值导向网络。", "target_word": "相似", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两个字的写法非常相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩的性格很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的爱好相似，所以常常聊天。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书的内容有很多相似的地方。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司卖的东西很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和他爸爸长得很相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种方法看起来相似，用法却不同。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们遇到过相似的问题。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个故事的开头十分相似。", "target_word": "相似", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相似度", "label": "复合词"}, {"form": "相似性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "事物之间有共同点或特征相近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相似", "is_correct": true, "explanation": "正确：“相似”指事物有共同点，可以用在“基于……优化目标”中，符合语境。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道或声音令人愉悦，不能修饰“优化目标”。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”形容温度或态度，与“优化目标”的意思不搭。"}, {"text": "圆滑", "is_correct": false, "explanation": "搭配：“圆滑”多形容人处事或物体表面，不能修饰“优化目标”。"}], "explanations": {"相似": "正确：“相似”指事物有共同点，可以用在“基于……优化目标”中，符合语境。", "甜美": "语义：“甜美”形容味道或声音令人愉悦，不能修饰“优化目标”。", "冰冷": "语义：“冰冷”形容温度或态度，与“优化目标”的意思不搭。", "圆滑": "搭配：“圆滑”多形容人处事或物体表面，不能修饰“优化目标”。"}, "sentence_index": 0, "correct_answer": "相似"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩相似已经好多年了，关系很好。", "explanation": "这里应该用〈相识〉。“相识”指彼此认识，“相似”指事物有共同点，说认识多年要用“相识”。"}, {"text": "两个孩子相似了整整三年，直到毕业才分开。", "explanation": "这里应该用〈相伴〉。“相似”指事物有共同点，不表示两人长期在一起。"}, {"text": "我家和学校离得很相似，走路只要五分钟。", "explanation": "这里应该用〈近〉。“相似”指事物有共同点或特征接近，说距离短要用“离得很近”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相似", "is_correct": true, "explanation": "正确：“相似”形容两人外貌相近，符合“长得很”的搭配。"}, {"text": "悠久", "is_correct": false, "explanation": "语义：“悠久”形容时间长，不能形容长相。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容面积大，不能形容长相。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：“饱满”多用于果实或脸色，不说人“长得很饱满”。"}], "explanations": {"相似": "正确：“相似”形容两人外貌相近，符合“长得很”的搭配。", "悠久": "语义：“悠久”形容时间长，不能形容长相。", "辽阔": "语义：“辽阔”形容面积大，不能形容长相。", "饱满": "搭配：“饱满”多用于果实或脸色，不说人“长得很饱满”。"}, "sentence_index": 6, "correct_answer": "相似"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩相似得很好，每天一起去上学。", "explanation": "这里应该用〈相处〉。“相似”指事物有共同点，不能用来说人与人之间的相处。"}, {"text": "两个城市相似很远，坐车要五个小时。", "explanation": "这里应该用〈相隔〉。“相似”指事物的共同点，不能表示空间上的距离。"}, {"text": "我们在车站相似了，谁也没认出谁。", "explanation": "这里应该用〈相遇〉。“相似”指事物有共同点，不指碰到人；偶然碰面要用“相遇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个方案的思路没相似，各有优点。", "corrected_sentence": "这两个方案的思路不相似，各有优点。", "error_description": "“相似”是形容词，否定要用“不”，不用“没”。应改为：这两个方案的思路不相似，各有优点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩的兴趣向他们相似。", "corrected_sentence": "我们俩的兴趣跟他们相似。", "error_description": "“相似”连接比较对象时用“跟”或“和”，不用“向”。应改为：我们俩的兴趣跟他们相似。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
