INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20040, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20040, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指涉及或具有群体特征的性质，常形容事件、行为等由多人参与或表现出群体共同特点。", "primary_collocate": null, "pronunciation": "qún tǐ xìng", "ipa": "tɕʰyn˧˥ tʰi˨˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "更严峻的是，若大量代理基于相似优化目标自发演化，可能催生群体性的行为趋同，进而形成“分布式认知霸权”——表面上去中心化的系统，实质上演变为隐蔽的价值导向网络。", "target_word": "群体性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一起群体性事件，警察很快赶到了现场。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年秋天都会举办群体性的体育活动。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生提醒大家，疫情期间不要参加群体性活动。", "target_word": "群体性", "complexity_tier": "T3", "furigana": "yī shēng tí xǐng dà jiā, yì qíng qī jiān bú yào cān jiā qún tǐ xìng huó dòng.", "sentence_source": "generated"}, {"text": "老师说，合唱是一种群体性的艺术。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的抗议是群体性的，不是一个人的想法。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的群体性特点非常明显。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁里出现了群体性的恐慌，大家都很紧张。", "target_word": "群体性", "complexity_tier": "T3", "furigana": "dì tiě lǐ chū xiàn le qún tǐ xìng de kǒng huāng, dà jiā dōu hěn jǐn zhāng.", "sentence_source": "generated"}, {"text": "这种群体性行为很少发生在安静的小镇。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节看电影已经成了群体性的习惯。", "target_word": "群体性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "群體性", "label": "繁体"}, {"form": "群体性事件", "label": "复合"}], "register": "书面语", "sense_fingerprint": "群体性|形容词|事件或行为由多人参与、具有群体共同特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d698ce0-810b-4db1-bf3a-88dde9784e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体性", "is_correct": true, "explanation": "正确：“群体性”指由多人共同表现的特点，与“大量代理基于相似目标趋同”的语境一致。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：“随机性”指无规律、偶然，与“基于相似优化目标”的系统性相矛盾。"}, {"text": "分散性", "is_correct": false, "explanation": "搭配：“分散性”指各自散开，不能修饰表示收敛的“行为趋同”。"}, {"text": "个体性", "is_correct": false, "explanation": "语义：“个体性”强调单个主体的特征，与“大量代理”共同趋同的意思相反。"}], "explanations": {"群体性": "正确：“群体性”指由多人共同表现的特点，与“大量代理基于相似目标趋同”的语境一致。", "随机性": "语义：“随机性”指无规律、偶然，与“基于相似优化目标”的系统性相矛盾。", "分散性": "搭配：“分散性”指各自散开，不能修饰表示收敛的“行为趋同”。", "个体性": "语义：“个体性”强调单个主体的特征，与“大量代理”共同趋同的意思相反。"}, "sentence_index": 0, "correct_answer": "群体性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个人都应该保持自己的群体性。", "explanation": "这里应该用〈个体性〉。群体性指多人共同表现的特点，个人的独特性要说个体性。"}, {"text": "这个孩子很有群体性，做事从不跟别人商量。", "explanation": "这里应该用〈个性〉。个性指人独特的性格，群体性描述多人共同的行为，不能用来形容一个人的性格。"}, {"text": "我一个人在家练习钢琴，这是一种群体性的活动。", "explanation": "这里不能用〈群体性〉，它要求多人共同参与；一个人练琴应说“个人的活动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体性", "is_correct": true, "explanation": "正确：“群体性”说明比赛具有多人共同参与、共同表现的特点，与“特点非常明显”相符。"}, {"text": "晴朗的", "is_correct": false, "explanation": "搭配：“晴朗”形容天气，不能修饰“比赛的特点”。"}, {"text": "私人的", "is_correct": false, "explanation": "搭配：“私人的”多修饰物品或场所，不能修饰“特点”。"}, {"text": "潮湿的", "is_correct": false, "explanation": "搭配：“潮湿”形容环境，不能修饰“比赛的特点”。"}], "explanations": {"群体性": "正确：“群体性”说明比赛具有多人共同参与、共同表现的特点，与“特点非常明显”相符。", "晴朗的": "搭配：“晴朗”形容天气，不能修饰“比赛的特点”。", "私人的": "搭配：“私人的”多修饰物品或场所，不能修饰“特点”。", "潮湿的": "搭配：“潮湿”形容环境，不能修饰“比赛的特点”。"}, "sentence_index": 6, "correct_answer": "群体性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生的群体性很强，不喜欢依赖别人。", "explanation": "这里应该用〈独立性〉。群体性说明多人共同的特点，描述一个人不依赖他人的特点要用独立性。"}, {"text": "这把椅子的群体性很强。", "explanation": "这里应该用〈结实〉。群体性指多人一起参与或表现的特点，不能形容物品的坚固程度，椅子应说“很结实”。"}, {"text": "这个答案的群体性很高，几乎没有错误。", "explanation": "这里应该用〈准确性〉。群体性指多人一起做的事，答案的正确程度要说“准确性”，不能用群体性形容答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场运动是群体性地，很多城市都有人参加。", "corrected_sentence": "这场运动是群体性的，很多城市都有人参加。", "error_description": "结构助词用错：“群体性”作表语时，句末应用“的”（是群体性的），不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演出的群体性没强，只有几个人参加。", "corrected_sentence": "这次演出的群体性不强，只有几个人参加。", "error_description": "否定词用错：形容词“强”作谓语的否定应用“不”，不能用“没”，应说“群体性不强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
