INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20042, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20042, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指有两个轴线的机械部件或结构，常见于车辆、机床等领域。", "primary_collocate": null, "pronunciation": "shuāng zhóu", "ipa": "ʂuaŋ˥˥ ʈʂou˧˥", "syllable_count": 2, "sentences": [{"text": "该精密机床采用双轴结构，两个轴线的同步精度直接决定了加工误差的大小。", "target_word": "双轴", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这辆卡车是双轴的。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双轴车比单轴车更稳。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂买了一台双轴机床。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双轴拖车可以拉很重的东西。", "target_word": "双轴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器是双轴设计。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种双轴结构很结实。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅正在检查双轴的零件。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双轴的车转弯时比较慢。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板想要双轴的，不要单轴的。", "target_word": "双轴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "双轴：有两个轴线的机械部件或结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c08a22b5-1600-4fdc-bce0-99a670ecd18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单轴", "is_correct": false, "explanation": "语义：句中说“两个轴线”，“单轴”只有一个轴，与之相悖。"}, {"text": "双眼", "is_correct": false, "explanation": "搭配：“双眼”指眼睛，不能用来修饰机床的结构。"}, {"text": "双手", "is_correct": false, "explanation": "语义：“双手”指人的两只手，不能用来修饰机械结构。"}, {"text": "双轴", "is_correct": true, "explanation": "双轴：指有两个轴线的机械结构，与“两个轴线”的描述相对应。"}], "explanations": {"单轴": "语义：句中说“两个轴线”，“单轴”只有一个轴，与之相悖。", "双眼": "搭配：“双眼”指眼睛，不能用来修饰机床的结构。", "双手": "语义：“双手”指人的两只手，不能用来修饰机械结构。", "双轴": "双轴：指有两个轴线的机械结构，与“两个轴线”的描述相对应。"}, "sentence_index": 0, "correct_answer": "双轴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条隧道是双轴的，两头都能通车。", "explanation": "这里应该用〈双向〉。隧道的两个通行方向说“双向”；“双轴”指有两个轴线的机械部件或结构，不用来形容隧道。"}, {"text": "这个背包是双轴的，背起来很舒服。", "explanation": "这里应该用〈双肩〉。背包的两条背带说“双肩”；“双轴”指有两个轴线的机械部件或结构，不用于背包。"}, {"text": "这张床是双轴的，两人都睡得下。", "explanation": "这里应该用〈双人〉。床按可睡人数说“双人”；“双轴”指有两个轴线的机械部件或结构，不用于床。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海绵", "is_correct": false, "explanation": "语义：海绵质地松软，与“结实”相悖，不能用来描述结构。"}, {"text": "豆腐", "is_correct": false, "explanation": "语义：豆腐易碎，与“结实”的语义矛盾。"}, {"text": "双手", "is_correct": false, "explanation": "语义：“双手”指人的两只手，不能用来修饰“结构”。"}, {"text": "双轴", "is_correct": true, "explanation": "双轴：指有两个轴的机械结构，与“结实”搭配自然。"}], "explanations": {"海绵": "语义：海绵质地松软，与“结实”相悖，不能用来描述结构。", "豆腐": "语义：豆腐易碎，与“结实”的语义矛盾。", "双手": "语义：“双手”指人的两只手，不能用来修饰“结构”。", "双轴": "双轴：指有两个轴的机械结构，与“结实”搭配自然。"}, "sentence_index": 6, "correct_answer": "双轴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗是双轴的，读起来很顺口。", "explanation": "这里应该用〈押韵〉。诗句的韵脚相押说“押韵”；“双轴”指有两个轴线的机械部件或结构，不用于诗。"}, {"text": "这条铁路是双轴的，两边都能走车。", "explanation": "这里应该用〈双轨〉。铁路的两条轨道说“双轨”，“双轴”指有两个轴的机械结构。"}, {"text": "这个班级是双轴的，大家都很认真。", "explanation": "这里应该用〈优秀〉。班级的好坏说“优秀”；“双轴”指有两个轴线的机械部件或结构，不用于班级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把双轴换。", "corrected_sentence": "工人把双轴换好了。", "error_description": "把字句错误：“把”字句的谓语动词后要有补语或“了”等成分，应说“把双轴换好了”，不能只说“把双轴换”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂里新买了一只双轴机床。", "corrected_sentence": "厂里新买了一台双轴机床。", "error_description": "量词错误：机床等机器用“台”，不用“只”。错误形式：一只双轴机床；正确形式：一台双轴机床。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
