INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "表示截止到某个时间点。", "primary_collocate": null, "pronunciation": "jié zhì", "ipa": "tɕjɛ˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "截至昨天，已经有三百人报名了。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至今年六月，这家店已经开了五年。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至目前，我们还没有收到他的消息。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至下午五点，学生都交了作业。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至周五，图书馆借出了两千本书。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至上个月底，我一共存了一万块钱。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至昨晚，这部电影的票房已经超过一亿元。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至去年，这个城市有八所大学。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至三月十号，已经有五十人报名了。", "target_word": "截至", "complexity_tier": "T3", "furigana": "jié zhì sān yuè shí hào, yǐ jīng yǒu wǔ shí rén bào míng le.", "sentence_source": "generated"}, {"text": "截至今天早上，雨还没有停。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "截至目前", "label": "固定搭配"}], "register": "书面语", "sense_fingerprint": "截至|介词|截止到某个时间点（常用于统计、通知）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d698ce0-810b-4db1-bf3a-88dde9784e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "截至", "is_correct": true, "explanation": "正确：“截至”表示截止到某个时间点，与“昨天”搭配，句意完整。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据或标准，与“昨天”这样的时间点不搭配。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”后面接对象，不能直接接“昨天”这样的时间词。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后面要接受处置的对象，不能接时间词。"}], "explanations": {"截至": "正确：“截至”表示截止到某个时间点，与“昨天”搭配，句意完整。", "按照": "语义：“按照”表示依据或标准，与“昨天”这样的时间点不搭配。", "对": "搭配：“对”后面接对象，不能直接接“昨天”这样的时间词。", "把": "配价：“把”后面要接受处置的对象，不能接时间词。"}, "sentence_index": 0, "correct_answer": "截至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "截至三天，大家一直在打扫教室。", "explanation": "这里应该用〈这〉，说“这三天”。截至只接某个时间点，不能接一段时间。"}, {"text": "截至健康，我每天都跑步。", "explanation": "这里应该用〈为了〉。截至接时间点，不能表示目的；“为了健康”才表示目的。"}, {"text": "截至我，已经有三百人报名了。", "explanation": "这里应该用〈算上〉。截至只接时间点，不能接人；“算上我”才表示把我也算进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "截至", "is_correct": true, "explanation": "正确：“截至”表示截止到某个时间点，与“昨晚”搭配，句意完整。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后面要接受处置的对象，不能接时间词。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，与“昨晚”这样的时间不搭配。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替他人做事，与票房的统计时间不搭配。"}], "explanations": {"截至": "正确：“截至”表示截止到某个时间点，与“昨晚”搭配，句意完整。", "把": "配价：“把”后面要接受处置的对象，不能接时间词。", "向": "语义：“向”表示方向或对象，与“昨晚”这样的时间不搭配。", "替": "语义：“替”表示代替他人做事，与票房的统计时间不搭配。"}, "sentence_index": 6, "correct_answer": "截至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "截至桌子，大家都坐好了。", "explanation": "这里应该用〈围着〉。截至只接时间点，不能接物品；表示位置要说“围着桌子”。"}, {"text": "截至一个小时，他一直在等公交车。", "explanation": "这里应该用〈整整〉。截至只接某个时间点，不能接“一个小时”这样的一段时间。"}, {"text": "截至晴天，我们就去爬山。", "explanation": "这里应该用〈如果〉。截至接的是时间点，“晴天”是条件，不能用截至来引出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "截至在上周，我们班已经有五个人请假了。", "corrected_sentence": "截至上周，我们班已经有五个人请假了。", "error_description": "多余成分：“截至”是介词，后面直接接时间词，不能加“在”，应说“截至上周，我们班已经有……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "截至了今晚，大家都把作业交上来了。", "corrected_sentence": "截至今晚，大家都把作业交上来了。", "error_description": "时态标记错误：“截至”是介词，后面不能加“了”，应说“截至今晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愉快", "is_correct": false, "explanation": "愉快形容心情好，与“相关”没有反义关系。"}, {"text": "无关", "is_correct": true, "explanation": "无关指彼此没有联系，与“相关”意义相反。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“相关”没有反义关系。"}, {"text": "笨重", "is_correct": false, "explanation": "笨重形容体积或动作，与“相关”没有反义关系。"}], "correct_answer": "无关", "explanations": {"愉快": "愉快形容心情好，与“相关”没有反义关系。", "无关": "无关指彼此没有联系，与“相关”意义相反。", "明亮": "明亮形容光线或颜色，与“相关”没有反义关系。", "笨重": "笨重形容体积或动作，与“相关”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": false, "explanation": "紧张形容心理或气氛，与“相关”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容明白或分明，与“相关”没有反义关系。"}, {"text": "无关", "is_correct": true, "explanation": "无关指彼此没有联系，与“相关”意义相反。"}, {"text": "辽阔", "is_correct": false, "explanation": "辽阔形容地域广大，与“相关”没有反义关系。"}], "correct_answer": "无关", "explanations": {"紧张": "紧张形容心理或气氛，与“相关”没有反义关系。", "清楚": "清楚形容明白或分明，与“相关”没有反义关系。", "无关": "无关指彼此没有联系，与“相关”意义相反。", "辽阔": "辽阔形容地域广大，与“相关”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "彼此关联；互相牵连。", "primary_collocate": null, "pronunciation": "xiāng guān", "ipa": "ɕiɑŋ˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "请把相关的材料交给老师。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟和肺病密切相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读的书都和历史相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想查一些相关的资料。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题与天气相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相关部门已经开始调查这件事。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习成绩和睡觉时间相关吗？", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我相关的情况。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多相关的图片。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有相关的新闻，你去看看。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不相关", "label": "否定"}, {"form": "相关性", "label": "复合"}, {"form": "相关部门", "label": "复合"}, {"form": "相關", "label": "繁体"}], "register": "书面", "sense_fingerprint": "彼此之间有关联、互相牵连", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c08a22b5-1600-4fdc-bce0-99a670ecd18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：材料没有甜味，“甜的材料”说不通。"}, {"text": "相关", "is_correct": true, "explanation": "相关作形容词，表示材料与所办的事有关联，修饰“材料”正确。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容人或动物的性格，不用来形容材料。"}, {"text": "暴躁", "is_correct": false, "explanation": "语义：“暴躁”形容人的脾气，材料不能有脾气。"}], "explanations": {"甜": "语义：材料没有甜味，“甜的材料”说不通。", "相关": "相关作形容词，表示材料与所办的事有关联，修饰“材料”正确。", "活泼": "语义：“活泼”形容人或动物的性格，不用来形容材料。", "暴躁": "语义：“暴躁”形容人的脾气，材料不能有脾气。"}, "sentence_index": 0, "correct_answer": "相关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩相关得很好。", "explanation": "这里应该用〈相处〉。“相关”只说彼此有联系，人与人一起生活、往来要用相处。"}, {"text": "他很相关我，常常帮我做事。", "explanation": "这里应该用〈关心〉。“相关”说事物彼此有联系，人对人的挂念要用关心。"}, {"text": "他的鼻子很相关，闻得出很远的味道。", "explanation": "这里应该用〈灵〉。“相关”说事物彼此有联系，形容感官敏锐要用“灵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高", "is_correct": false, "explanation": "搭配：“高”说高低，时间要说长短，不说“时间高”。"}, {"text": "溜", "is_correct": false, "explanation": "语域：“溜”是口语，不合书面的问句。"}, {"text": "相关", "is_correct": true, "explanation": "相关表示两者有联系，此处问成绩与睡眠时间是否有关联。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说物体的厚度，不能用来说成绩和时间的关系。"}], "explanations": {"高": "搭配：“高”说高低，时间要说长短，不说“时间高”。", "溜": "语域：“溜”是口语，不合书面的问句。", "相关": "相关表示两者有联系，此处问成绩与睡眠时间是否有关联。", "厚": "语义：“厚”说物体的厚度，不能用来说成绩和时间的关系。"}, "sentence_index": 6, "correct_answer": "相关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣相关得很暖和。", "explanation": "这里应该用〈保暖〉。“相关”只说彼此有联系，衣物的暖和程度要用“保暖”。"}, {"text": "两条河在这里相关了。", "explanation": "这里应该用〈相遇〉。“相关”只说彼此有联系，两条河汇到一处要用相遇。"}, {"text": "我们早已相关。", "explanation": "这里应该用〈相识〉。“相关”说事物有联系，早就认识的人要用相识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事和我没相关。", "corrected_sentence": "这件事和我不相关。", "error_description": "否定形容词“相关”要用“不”，说“不相关”。错误形式：没相关；正确形式：不相关。“没”一般用于动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两件事的情况密切地相关。", "corrected_sentence": "两件事的情况密切相关。", "error_description": "“密切相关”是固定搭配，“密切”直接修饰“相关”，中间不加“地”。错误形式：密切地相关；正确形式：密切相关。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
