INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20046, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指较简单的事物发展出较复杂的新事物。", "primary_collocate": null, "pronunciation": "yǎn shēng", "ipa": "jɛn˨˩˦ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这个小游戏后来衍生出很多新玩法。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个简单的想法衍生出了大计划。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影衍生出了电视剧和游戏。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言在使用中不断衍生出新词。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一种新技术衍生出新的行业。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小生意慢慢衍生出一个大公司。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事衍生了好几个版本。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多新工作都是从网络衍生出来的。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一首老歌衍生出许多不同的曲子。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玩具衍生出一整套产品。", "target_word": "衍生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衍生了", "label": "体标"}, {"form": "衍生过", "label": "体标"}, {"form": "衍生物", "label": "复合"}, {"form": "衍生品", "label": "复合"}], "register": "书面", "sense_fingerprint": "简单的事物发展出复杂的新事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c08a22b5-1600-4fdc-bce0-99a670ecd18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩减", "is_correct": false, "explanation": "语义：“缩减”指压缩、减少，与“发展出很多新玩法”的方向相反"}, {"text": "衍生", "is_correct": true, "explanation": "正确：“衍生出”表示由小游戏发展出许多新玩法"}, {"text": "吞并", "is_correct": false, "explanation": "语义：“吞并”指把他物并入自己，不能用来指产生新玩法"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”的对象多是时间、能量，不说“消耗新玩法”"}], "explanations": {"缩减": "语义：“缩减”指压缩、减少，与“发展出很多新玩法”的方向相反", "衍生": "正确：“衍生出”表示由小游戏发展出许多新玩法", "吞并": "语义：“吞并”指把他物并入自己，不能用来指产生新玩法", "消耗": "搭配：“消耗”的对象多是时间、能量，不说“消耗新玩法”"}, "sentence_index": 0, "correct_answer": "衍生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案的内容被衍生了一半。", "explanation": "这里应该用〈删减〉。衍生指产生新事物，不表示减少已有内容；“减少了一半”应说删减。"}, {"text": "她衍生出了三个孩子。", "explanation": "这里应该用〈生育〉。衍生用于事物发展出新事物，不用于人的生育。"}, {"text": "他在新班级里衍生出了很多朋友。", "explanation": "这里应该用〈收获〉。衍生指事物发展出新事物，不用于交到朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”指把东西咽下去，与“故事衍生出版本”无关"}, {"text": "衍生", "is_correct": true, "explanation": "正确：“衍生了”表示由这个故事发展出好几个版本"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”的对象多是钱财、时间，不说“挥霍版本”"}, {"text": "耗尽", "is_correct": false, "explanation": "搭配：“耗尽”指用完，多用于能量、资源，不说“耗尽版本”"}], "explanations": {"吃掉": "语义：“吃掉”指把东西咽下去，与“故事衍生出版本”无关", "衍生": "正确：“衍生了”表示由这个故事发展出好几个版本", "挥霍": "搭配：“挥霍”的对象多是钱财、时间，不说“挥霍版本”", "耗尽": "搭配：“耗尽”指用完，多用于能量、资源，不说“耗尽版本”"}, "sentence_index": 6, "correct_answer": "衍生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大火衍生了一整套产品。", "explanation": "这里应该用〈销毁〉。衍生指由较简单的事物发展出较复杂的新事物，不表示毁坏已有的东西。"}, {"text": "顾客衍生了一整套产品。", "explanation": "这里应该用〈消费〉。衍生用于事物发展出新事物，不用于人使用商品。"}, {"text": "警察衍生了一整套产品。", "explanation": "这里应该用〈没收〉。衍生指产生新事物，不表示把别人的东西收走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个节目衍生了出很多周边产品。", "corrected_sentence": "这个节目衍生出了很多周边产品。", "error_description": "补语“出”应紧跟在“衍生”之后，应说“衍生出了”，不说“衍生了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款饮料衍生出着几种新口味。", "corrected_sentence": "这款饮料衍生出了几种新口味。", "error_description": "“衍生出”表示变化已经完成，应用“了”，不用“着”；“着”表示持续的状态，不能接在已完成的变化上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b78d34-1ff3-4211-b59f-884fce69a9bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
