INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20047, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一种物体遮住另一种物体，使其不被看到或接触到。", "primary_collocate": null, "pronunciation": "fù gài", "ipa": "fu˥˩ kai˥˩", "syllable_count": 2, "sentences": [{"text": "大雪覆盖了整个山村。", "target_word": "覆盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上覆盖着一层厚厚的落叶。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乌云覆盖了天空，月亮看不见了。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，白雪覆盖着大地。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，青苔覆盖了石头。", "target_word": "覆盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厚厚的灰尘覆盖了桌子。", "target_word": "覆盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绿树覆盖了这座小山。", "target_word": "覆盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河面上覆盖着一层薄冰。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子覆盖了路，车开不过去。", "target_word": "覆盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾覆盖了整个城市。", "target_word": "覆盖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "覆盖了", "label": "体标"}, {"form": "覆盖着", "label": "体标"}, {"form": "覆盖过", "label": "体标"}, {"form": "覆盖面", "label": "复合"}, {"form": "覆蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一种东西盖在另一种东西上面，使下面的东西被遮住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90eedc6c-01dd-4f05-9096-cfdfdc3231d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覆盖", "is_correct": true, "explanation": "正确：“覆盖”表示雪盖满整个山村，符合句意。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”指把物体从一处移到另一处，大雪不能把整个山村搬走。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与大雪落在山村上无关。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能以“整个山村”作宾语。"}], "explanations": {"覆盖": "正确：“覆盖”表示雪盖满整个山村，符合句意。", "搬运": "语义：“搬运”指把物体从一处移到另一处，大雪不能把整个山村搬走。", "翻译": "语义：“翻译”指转换语言，与大雪落在山村上无关。", "增加": "搭配：“增加”说数量，不能以“整个山村”作宾语。"}, "sentence_index": 0, "correct_answer": "覆盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他覆盖在椅子上坐下了。", "explanation": "这里应该用〈坐〉。覆盖指盖在某物表面，人坐在椅子上要用坐，不能说覆盖在椅子上。"}, {"text": "敌人覆盖了这座城市。", "explanation": "这里应该用〈包围〉。覆盖指一物盖在另一物表面；敌军从四面把城市围住要用包围。"}, {"text": "这堵墙覆盖了风。", "explanation": "这里应该用〈挡住〉。覆盖的对象是可以盖住的表面，风是气流，不能被覆盖；墙挡住风要用挡住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覆盖", "is_correct": true, "explanation": "正确：“覆盖”表示绿树盖满小山，符合句意。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：“赶走”指把人或东西驱离，绿树不能把小山赶走。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指人工建造，树木不能修建小山。"}, {"text": "欺负", "is_correct": false, "explanation": "配价：“欺负”要求有意志的人作施事，绿树不能欺负小山。"}], "explanations": {"覆盖": "正确：“覆盖”表示绿树盖满小山，符合句意。", "赶走": "语义：“赶走”指把人或东西驱离，绿树不能把小山赶走。", "修建": "语义：“修建”指人工建造，树木不能修建小山。", "欺负": "配价：“欺负”要求有意志的人作施事，绿树不能欺负小山。"}, "sentence_index": 6, "correct_answer": "覆盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在合同上覆盖了章。", "explanation": "这里应该用〈盖〉。“盖章”的“盖”指加印，覆盖指盖在某物表面，不表示加盖印章，合同上盖章要说盖。"}, {"text": "她覆盖上了墨镜，走出了房间。", "explanation": "这里应该用〈戴〉。戴墨镜是把眼镜架在脸上，覆盖指盖在某物表面，不能用来说戴上眼镜。"}, {"text": "他把书覆盖进了书包。", "explanation": "这里应该用〈放〉。覆盖表示盖在表面，不表示把东西装进某处，把书装进书包要说放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "浓雾覆盖了着整个湖面，看不清对岸。", "corrected_sentence": "浓雾覆盖着整个湖面，看不清对岸。", "error_description": "错误：动词“覆盖”后同时用了“了”和“着”。“着”表示状态持续，不能与“了”并用，应删去“了”，写作“覆盖着整个湖面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "浓烟覆盖得整片天空。", "corrected_sentence": "浓烟覆盖了整片天空。", "error_description": "错误：“了”写成了“得”。“得”引出补语，此处没有补语，应用“了”表示完成，写作“浓烟覆盖了整片天空”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
