INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将系统或产品设计成由独立、可互换的模块组成的方式。", "primary_collocate": null, "pronunciation": "mó kuài huà", "ipa": "mo˧˥ kʰuai˥˩ xua˥˩", "syllable_count": 3, "sentences": [{"text": "GitHub数据显示，截至2025年末，相关衍生项目已覆盖教育、心理健康、城市治理等十六个领域，其模块化设计允许多主体在不侵犯核心协议的前提下进行价值创新。", "target_word": "模块化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台电脑采用模块化设计，坏了可以换零件。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化让软件更容易修改。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的新手机用模块化的方法生产。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的模块化建造可以节省时间。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化的好处是每个部分都能单独更换。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在研究汽车的模块化。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统的模块化做得很好。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化使大型程序更容易管理。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化的家具可以自由组合。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模块化设计", "label": "复合"}, {"form": "模块化生产", "label": "复合"}, {"form": "模組化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把系统或产品设计成由独立、可互换的模块组成的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90eedc6c-01dd-4f05-9096-cfdfdc3231d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模块化", "is_correct": true, "explanation": "正确。原句说“模块化设计”，指把系统设计成可互换的模块组合，符合句中“允许多主体在前提下创新”的语境。"}, {"text": "集中化", "is_correct": false, "explanation": "语义：集中化与“允许多主体参与价值创新”的意思相反，句中强调开放，不能说集中。"}, {"text": "封闭化", "is_correct": false, "explanation": "语义：封闭化会阻止多主体进入，与“允许多主体在不侵犯核心协议的前提下进行创新”相矛盾。"}, {"text": "单一化", "is_correct": false, "explanation": "搭配：“单一化”指事物变得单一，与“多主体进行价值创新”的语境搭配不通。"}], "explanations": {"模块化": "正确。原句说“模块化设计”，指把系统设计成可互换的模块组合，符合句中“允许多主体在前提下创新”的语境。", "集中化": "语义：集中化与“允许多主体参与价值创新”的意思相反，句中强调开放，不能说集中。", "封闭化": "语义：封闭化会阻止多主体进入，与“允许多主体在不侵犯核心协议的前提下进行创新”相矛盾。", "单一化": "搭配：“单一化”指事物变得单一，与“多主体进行价值创新”的语境搭配不通。"}, "sentence_index": 0, "correct_answer": "模块化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很模块化。", "explanation": "这里把〈模块化〉当成“性格可以拆分、各部分可互换”的意思来形容人，但它只指系统或产品的设计方式。"}, {"text": "这款平板的外壳模块化，屏幕和主机无法拆分。", "explanation": "这里应该用〈一体化〉。模块化指各部分可拆分、可互换，与“无法拆分”相矛盾；合为一体才用一体化。"}, {"text": "这座山的模块化很陡峭。", "explanation": "这里应该用〈陡峭〉。模块化只指系统或产品的设计方式，不能用来形容山的形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模块化", "is_correct": true, "explanation": "正确。“研究汽车的模块化”指研究汽车的模块化设计，符合句意。"}, {"text": "口味", "is_correct": false, "explanation": "语义：汽车没有口味，“研究汽车的口味”在语义上不通。"}, {"text": "感情", "is_correct": false, "explanation": "语义：汽车是无生命的物体，不存在感情，句子不成立。"}, {"text": "饮食", "is_correct": false, "explanation": "搭配：“研究”的对象是汽车，“汽车的饮食”不能作为研究对象。"}], "explanations": {"模块化": "正确。“研究汽车的模块化”指研究汽车的模块化设计，符合句意。", "口味": "语义：汽车没有口味，“研究汽车的口味”在语义上不通。", "感情": "语义：汽车是无生命的物体，不存在感情，句子不成立。", "饮食": "搭配：“研究”的对象是汽车，“汽车的饮食”不能作为研究对象。"}, "sentence_index": 6, "correct_answer": "模块化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫的模块化很可爱。", "explanation": "这里把〈模块化〉误当成“身体各部件可拆换”的意思来形容猫，但它只指系统或产品的设计方式，不能用于动物。"}, {"text": "这杯咖啡的模块化很浓。", "explanation": "这里把〈模块化〉误当成“味道浓淡”的意思来用，但它只指系统或产品的设计方式，不能形容咖啡。"}, {"text": "这几段代码模块化，改一处就得全部重写。", "explanation": "这里说的是代码互相紧密依赖（耦合）的状态，而模块化指各部分彼此独立、可单独修改，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个团队用模块化地方式设计产品。", "corrected_sentence": "这个团队用模块化的方式设计产品。", "error_description": "错误：“模块化”修饰名词“方式”时要用“的”，写成“地”不对。“地”用于修饰动词，应写作“模块化的方式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团队把系统模块化很彻底。", "corrected_sentence": "这个团队把系统模块化得很彻底。", "error_description": "错误：“把系统模块化”后漏了补语标记“得”，应为“模块化得很彻底”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "正确。“禁止”与“允许”是反义词，“公司允许员工在家工作”的反面是“公司禁止员工在家工作”。"}, {"text": "购买", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "思考", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "搬运", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}], "correct_answer": "禁止", "explanations": {"禁止": "正确。“禁止”与“允许”是反义词，“公司允许员工在家工作”的反面是“公司禁止员工在家工作”。", "购买": "与“允许”没有反义关系，只是同为动词的干扰项。", "思考": "与“允许”没有反义关系，只是同为动词的干扰项。", "搬运": "与“允许”没有反义关系，只是同为动词的干扰项。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "正确。“禁止”与“允许”是反义词，“老师允许了他迟到”的反面是“老师禁止他迟到”。"}, {"text": "游泳", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "思索", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "修理", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}], "correct_answer": "禁止", "explanations": {"禁止": "正确。“禁止”与“允许”是反义词，“老师允许了他迟到”的反面是“老师禁止他迟到”。", "游泳": "与“允许”没有反义关系，只是同为动词的干扰项。", "思索": "与“允许”没有反义关系，只是同为动词的干扰项。", "修理": "与“允许”没有反义关系，只是同为动词的干扰项。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示同意、许可。", "primary_collocate": null, "pronunciation": "yǔn xǔ", "ipa": "yn˨˩˦ ɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师允许我们在课上用手机。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不允许我晚上出去玩。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸终于允许我养小狗了。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司允许员工在家工作。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不允许他喝酒。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理允许我明天请假。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校允许学生带水进教室。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板允许过我们提前下班。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的父母不允许她一个人去旅行。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师允许了他迟到。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "允许了", "label": "体标（了）"}, {"form": "允许过", "label": "体标（过）"}, {"form": "不允许", "label": "否定形式"}, {"form": "允許", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有权的人表示同意，让别人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90eedc6c-01dd-4f05-9096-cfdfdc3231d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "允许", "is_correct": true, "explanation": "正确。“老师允许我们在课上用手机”表示老师准许学生做某事，符合句意。"}, {"text": "承认", "is_correct": false, "explanation": "语义：“承认”的对象是事实，不能用来表示准许学生做某事。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”后接的是人或事，不能带“我们在课上用手机”这个兼语结构。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的对象是地方，不能带“我们在课上用手机”这样的兼语结构。"}], "explanations": {"允许": "正确。“老师允许我们在课上用手机”表示老师准许学生做某事，符合句意。", "承认": "语义：“承认”的对象是事实，不能用来表示准许学生做某事。", "感谢": "配价：“感谢”后接的是人或事，不能带“我们在课上用手机”这个兼语结构。", "打扫": "配价：“打扫”的对象是地方，不能带“我们在课上用手机”这样的兼语结构。"}, "sentence_index": 0, "correct_answer": "允许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我允许他的建议。", "explanation": "这里应该用〈同意〉。“允许”表示准许某人做某事，不能直接以“建议”为宾语。"}, {"text": "我允许这本书。", "explanation": "这里把〈允许〉误当成“同意、接受某物”的意思，但它后面只能接可以做的动作，不能以“这本书”这样的物作宾语。"}, {"text": "一场大雨允许我们回家。", "explanation": "这里把〈允许〉误当成“使某事可能发生”的意思，但它只表示有权决定的人或机构准许，“大雨”不能这样作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "允许", "is_correct": true, "explanation": "正确。“学校允许学生带水进教室”表示学校准许学生做某事，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”的对象是坏了的东西，不能带“学生带水进教室”这样的兼语结构。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，不能表示准许学生做某事。"}, {"text": "同情", "is_correct": false, "explanation": "搭配：“同情”的对象是人的遭遇，不能接“带水进教室”这样的行为。"}], "explanations": {"允许": "正确。“学校允许学生带水进教室”表示学校准许学生做某事，符合句意。", "修理": "配价：“修理”的对象是坏了的东西，不能带“学生带水进教室”这样的兼语结构。", "种植": "语义：“种植”指栽种植物，不能表示准许学生做某事。", "同情": "搭配：“同情”的对象是人的遭遇，不能接“带水进教室”这样的行为。"}, "sentence_index": 6, "correct_answer": "允许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板允许了我们的眼泪。", "explanation": "这里把〈允许〉误当成“容纳、接受某种情绪”的意思，但它只能表示准许别人做某件事，不能用于“眼泪”。"}, {"text": "妈妈允许我感冒。", "explanation": "这里把〈允许〉误当成“任由某种状况发生”的意思，但它只表示准许别人做某件事，不能准许身体生病。"}, {"text": "我们允许了他的粗鲁，希望他改正。", "explanation": "这里应该用〈容忍〉。允许表示准许做某事，对不好的行为勉强接受要用容忍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校不允许了学生在教室里吃东西。", "corrected_sentence": "学校不允许学生在教室里吃东西。", "error_description": "错误：“了”不能紧跟在否定形式“不允许”之后，应去掉“了”，写作“学校不允许学生在教室里吃东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理允许了了我们提前走。", "corrected_sentence": "经理允许了我们提前走。", "error_description": "错误：“了”重复出现，“允许”后只能用一个“了”，应写作“经理允许了我们提前走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45fd609-c469-4c52-9ccd-364c2aa20591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
