INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20056, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "值得信任，能够依靠。", "primary_collocate": null, "pronunciation": "kě xìn lài", "ipa": "kʰɤ˨˩ ɕin˥˩ lai˥˩", "syllable_count": 3, "sentences": [{"text": "倘若此趋势持续，2026年或将见证一场静默的认知民主化浪潮——个体不再被算法凝视，而是通过可信赖的代理，主动参与数字身份的建构与协商。", "target_word": "可信赖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他是一个可信赖的朋友。", "target_word": "可信赖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们需要一位可信赖的医生。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司一直是可信赖的合作伙伴。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在困难的时候，他是我最可信赖的伙伴。", "target_word": "可信赖", "complexity_tier": "T3", "furigana": "kě xìn lài", "sentence_source": "generated"}, {"text": "老板觉得小李最可信赖，就把钱交给他保管。", "target_word": "可信赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是团队里最可信赖的人。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个可信赖的领导，会说到做到。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选保姆时，我只找可信赖的熟人。", "target_word": "可信赖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子遇到危险时，会找可信赖的大人帮忙。", "target_word": "可信赖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可信赖", "label": "否定"}, {"form": "最可信赖", "label": "程度"}, {"form": "可信賴", "label": "繁体"}], "register": "书面", "sense_fingerprint": "值得信任，能够依靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可信赖", "is_correct": true, "explanation": "正确：“可信赖的代理”指值得依靠的中介，与“主动参与”的积极语境相符。"}, {"text": "可疑", "is_correct": false, "explanation": "语义：“可疑”含有怀疑的意思，与“主动参与”的积极语境矛盾。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”多形容事物过时，不用来修饰“代理”。"}, {"text": "不可靠", "is_correct": false, "explanation": "语义：“不可靠”与“可信赖”意思相反，会使整句的积极语境断裂。"}], "explanations": {"可信赖": "正确：“可信赖的代理”指值得依靠的中介，与“主动参与”的积极语境相符。", "可疑": "语义：“可疑”含有怀疑的意思，与“主动参与”的积极语境矛盾。", "陈旧": "搭配：“陈旧”多形容事物过时，不用来修饰“代理”。", "不可靠": "语义：“不可靠”与“可信赖”意思相反，会使整句的积极语境断裂。"}, "sentence_index": 0, "correct_answer": "可信赖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料的口感很可信赖，喝一口就想再来一杯。", "explanation": "这里应该用〈好喝〉。“可信赖”指值得依靠，不能用来形容口感，口感好要说“好喝”。"}, {"text": "这首诗很可信赖，读完让人感动。", "explanation": "这里应该用〈感人〉。“可信赖”指值得依靠，不用来评价诗歌；诗歌让人感动，应说〈感人〉。"}, {"text": "他的心情很可信赖，大家都不敢和他说话。", "explanation": "这里应该用〈阴沉〉。“可信赖”指人或事物值得依靠，不能用来形容心情，心情阴沉、让人不敢接近要说“阴沉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可信赖", "is_correct": true, "explanation": "正确：“团队里最……的人”是称赞某人值得依靠，与“可信赖”相符。"}, {"text": "可口", "is_correct": false, "explanation": "搭配：“可口”形容食物好吃，不用来形容人。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”形容体形臃肿或行动迟缓，是贬义，与“团队里最……的人”的称赞语境相反，句意不通。"}, {"text": "液态", "is_correct": false, "explanation": "语义：“液态”指物质的状态，与团队里的人无关。"}], "explanations": {"可信赖": "正确：“团队里最……的人”是称赞某人值得依靠，与“可信赖”相符。", "可口": "搭配：“可口”形容食物好吃，不用来形容人。", "笨重": "语义：“笨重”形容体形臃肿或行动迟缓，是贬义，与“团队里最……的人”的称赞语境相反，句意不通。", "液态": "语义：“液态”指物质的状态，与团队里的人无关。"}, "sentence_index": 6, "correct_answer": "可信赖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他生气时的表情很可信赖，大家都在笑。", "explanation": "这里应该用〈可笑〉。“可信赖”指值得依靠，不能用来形容表情，表情滑稽要说“可笑”。"}, {"text": "这部电影的节奏很可信赖，看了一半就睡着了。", "explanation": "这里应该用〈拖沓〉。“可信赖”指值得依靠，不能用来形容影片节奏，节奏慢要说“拖沓”。"}, {"text": "这次考试的题目很可信赖，同学们都觉得很难。", "explanation": "这里应该用〈难〉。“可信赖”指值得依靠，不用来形容题目；题目难要说〈难〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们找到了一位可信赖翻译。", "corrected_sentence": "他们找到了一位可信赖的翻译。", "error_description": "错误形式“一位可信赖翻译”，正确形式“一位可信赖的翻译”。“可信赖”作定语修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师很非常可信赖，学生都愿意找她。", "corrected_sentence": "这位老师非常可信赖，学生都愿意找她。", "error_description": "错误形式“很非常可信赖”，正确形式“非常可信赖”。程度副词“很”和“非常”不能叠用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
