INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指可供学习或模仿的榜样、样本。", "primary_collocate": null, "pronunciation": "fàn běn", "ipa": "fan˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "此情此景下，OpenClaw是否成为范本已非核心议题；真正关键的是，人类能否在智能代理的镜像中，重新确认自身存在的主体性。", "target_word": "范本", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这篇文章是写作课上的好范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们发了一份范本，让我们照着写作文。", "target_word": "范本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这幅字当作练习的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学书法的人常常照着名家的范本练字。", "target_word": "范本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的管理方法成了同行的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你先看看范本，再自己写一遍。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份简历是求职者学习的好范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的演讲清楚又有力，是很好的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店里有很多信件写作的范本。", "target_word": "范本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份范本", "label": "量词"}, {"form": "一个范本", "label": "量词"}, {"form": "範本", "label": "繁体"}], "register": "通用", "sense_fingerprint": "可供学习、模仿的榜样或样本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "范本", "is_correct": true, "explanation": "正确：“范本”指可供学习模仿的样子，作“成为”的宾语，与句意相合。"}, {"text": "车间", "is_correct": false, "explanation": "语义：车间是生产场所，不能作为“成为”的宾语来指 OpenClaw 的身份。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“成为”后接身份或角色，不能说“成为天气”。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：OpenClaw不可能“成为雨水”，与讨论智能代理的语境不合。"}], "explanations": {"范本": "正确：“范本”指可供学习模仿的样子，作“成为”的宾语，与句意相合。", "车间": "语义：车间是生产场所，不能作为“成为”的宾语来指 OpenClaw 的身份。", "天气": "搭配：“成为”后接身份或角色，不能说“成为天气”。", "雨水": "语义：OpenClaw不可能“成为雨水”，与讨论智能代理的语境不合。"}, "sentence_index": 0, "correct_answer": "范本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边跑步一边吃范本。", "explanation": "这里应该用〈面包〉。“吃”的对象须是食物，“范本”指可学习模仿的样子，不能吃。"}, {"text": "这道数学题的范本是三。", "explanation": "语义：这里应该用〈答案〉。范本指可照着学的样子，不能用来指题目的结果，应说“这道数学题的答案是三”。"}, {"text": "他把坏掉的范本拿去修理了。", "explanation": "这里应该用〈机器〉。“修理”的对象是坏掉的器械，“范本”指可学习模仿的样子，不能修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "范本", "is_correct": true, "explanation": "正确：“范本”指可照着学的样子，作“看看”的宾语，与“再自己写一遍”相合。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报与“再自己写一遍”的学习语境无关。"}, {"text": "电视剧", "is_correct": false, "explanation": "语义：看电视剧不能作为动笔写作的参照，句意不通。"}, {"text": "电冰箱", "is_correct": false, "explanation": "语义：电冰箱不能作为动笔写作的参照，与“再自己写一遍”不合。"}], "explanations": {"范本": "正确：“范本”指可照着学的样子，作“看看”的宾语，与“再自己写一遍”相合。", "天气预报": "语义：天气预报与“再自己写一遍”的学习语境无关。", "电视剧": "语义：看电视剧不能作为动笔写作的参照，句意不通。", "电冰箱": "语义：电冰箱不能作为动笔写作的参照，与“再自己写一遍”不合。"}, "sentence_index": 6, "correct_answer": "范本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渴了，想喝一杯范本。", "explanation": "语义：这里应该用〈水〉。“喝”的对象是饮品，范本指可照着学的样子，不能喝。"}, {"text": "他每天早上都给范本浇水。", "explanation": "这里应该用〈花〉。“浇水”的对象是植物，“范本”不能浇水。"}, {"text": "他每天晚上都把范本叠得整整齐齐。", "explanation": "这里应该用〈衣服〉。“叠”的对象是衣物等织物，“范本”不能叠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给我们一把范本，让我们照着写。", "corrected_sentence": "老师给我们一份范本，让我们照着写。", "error_description": "量词错误：“把”用于有柄的器物，范本是纸质样品，应该用“份”。正确说法是“一份范本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份简历写得很规范，可以作为的范本。", "corrected_sentence": "这份简历写得很规范，可以作为范本。", "error_description": "多余的“的”：“作为”后直接接“范本”，不能在中间加“的”。正确说法是“可以作为范本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
