INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20059, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示询问或怀疑事物是否可能或可行。", "primary_collocate": null, "pronunciation": "néng fǒu", "ipa": "nɤŋ˧˥ fou˨˩˦", "syllable_count": 2, "sentences": [{"text": "此情此景下，OpenClaw是否成为范本已非核心议题；真正关键的是，人类能否在智能代理的镜像中，重新确认自身存在的主体性。", "target_word": "能否", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我想知道他明天能否来。", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项计划能否如期完成，目前还难以判断。", "target_word": "能否", "complexity_tier": "T3", "furigana": "néng fǒu", "sentence_source": "generated"}, {"text": "比赛能否举行，要看明天的天气。", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事能否成功，现在还不知道。", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货能否按时到达，还要看路上的天气。", "target_word": "能否", "complexity_tier": "T3", "furigana": "néng fǒu", "sentence_source": "generated"}, {"text": "老师问我们能否完成作业。", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在想自己能否考上大学。", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同能否在下周生效，还需要双方确认。", "target_word": "能否", "complexity_tier": "T3", "furigana": "néng fǒu", "sentence_source": "generated"}, {"text": "孩子能否健康长大，父母最关心。", "target_word": "能否", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "能不能", "label": "口语形式"}], "register": "书面", "sense_fingerprint": "书面语，表示能不能、是否可行的疑问或不确定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42af6dd8-76df-4128-9f4d-41a929127788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能否", "is_correct": true, "explanation": "正确。“能否”表示是否可能，符合“关键的是……能否……”这一询问语境。"}, {"text": "被", "is_correct": false, "explanation": "句法：“被”后需接动词或被动结构，“人类被在……”不成立。"}, {"text": "把", "is_correct": false, "explanation": "句法：“把”后需接处置对象与动词，“人类把在……”不成立。"}, {"text": "让", "is_correct": false, "explanation": "句法：“让”后需接使役对象和动词，“人类让在……镜像中”不成立。"}], "explanations": {"能否": "正确。“能否”表示是否可能，符合“关键的是……能否……”这一询问语境。", "被": "句法：“被”后需接动词或被动结构，“人类被在……”不成立。", "把": "句法：“把”后需接处置对象与动词，“人类把在……”不成立。", "让": "句法：“让”后需接使役对象和动词，“人类让在……镜像中”不成立。"}, "sentence_index": 0, "correct_answer": "能否"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天一定能否来学校。", "explanation": "“能否”表示不确定地询问能不能，不能与“一定”这类表示确定的词连用；表示有把握能做到应说〈能够〉，即“我明天一定能够来学校”。"}, {"text": "我妹妹已经能否画好这幅画了。", "explanation": "“能否”表示还不确定能不能，与“已经画好”的事实矛盾；表示已经具备能力应说〈能够〉，即“我妹妹已经能够画好这幅画了”。"}, {"text": "这条路肯定能否开车。", "explanation": "“能否”表示不确定的询问，不能与“肯定”连用；表示确定可以开车应说〈可以〉，即“这条路肯定可以开车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能否", "is_correct": true, "explanation": "正确。“能否”表示询问能不能完成，符合老师的提问语境。"}, {"text": "关于", "is_correct": false, "explanation": "句法：“关于”是介词，后接名词性成分作话题，“老师问我们关于完成作业”缺少宾语中心，不成立。"}, {"text": "因为", "is_correct": false, "explanation": "句法：“因为”引出原因分句，“老师问我们因为完成作业”没有询问内容，不成立。"}, {"text": "从", "is_correct": false, "explanation": "句法：“从”是介词，表示起点，后接处所或时间，“老师问我们从完成作业”不成立。"}], "explanations": {"能否": "正确。“能否”表示询问能不能完成，符合老师的提问语境。", "关于": "句法：“关于”是介词，后接名词性成分作话题，“老师问我们关于完成作业”缺少宾语中心，不成立。", "因为": "句法：“因为”引出原因分句，“老师问我们因为完成作业”没有询问内容，不成立。", "从": "句法：“从”是介词，表示起点，后接处所或时间，“老师问我们从完成作业”不成立。"}, "sentence_index": 6, "correct_answer": "能否"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事能否属实，我们还要调查。", "explanation": "“能否”表示能不能做到、行不行，不用来表示事情真假；判断真假应说〈是否〉，即“这件事是否属实”。"}, {"text": "这块地能否种出庄稼，已经收获三次了。", "explanation": "“能否”表示还不确定能不能，与“已经收获三次”的事实矛盾；陈述已经能种出来应说〈能够〉。"}, {"text": "这个孩子能否学会游泳，他已经游了一公里。", "explanation": "“能否”表示还不知道能不能做到，与“已经游了一公里”的事实矛盾；陈述已经能做到应说〈能够〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天会能否来，我还不确定。", "corrected_sentence": "他明天能否来，我还不确定。", "error_description": "情态叠用错误：“会”与“能否”两个情态成分叠在一起。“能否”已表示可能性，前面不能再加“会”，应为“他明天能否来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器能否修好吗，师傅还不确定。", "corrected_sentence": "这台机器能否修好，师傅还不确定。", "error_description": "错误在于句末多加了疑问语气词“吗”。“能否”本身已是疑问形式，不能再与“吗”叠用；正确为“这台机器能否修好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20060, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "正确：“有”与“没有”构成反义关系，表示存在。"}, {"text": "跑", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“跑”指快速移动。"}, {"text": "洗", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“洗”指清洁。"}, {"text": "笑", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“笑”指发出笑声。"}], "correct_answer": "有", "explanations": {"有": "正确：“有”与“没有”构成反义关系，表示存在。", "跑": "与“没有”无反义或近义关系：“跑”指快速移动。", "洗": "与“没有”无反义或近义关系：“洗”指清洁。", "笑": "与“没有”无反义或近义关系：“笑”指发出笑声。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20060, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "正确：“有问题”与“没有问题”构成反义关系。"}, {"text": "借", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“借”指借入。"}, {"text": "找", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“找”指寻求。"}, {"text": "唱", "is_correct": false, "explanation": "与“没有”无反义或近义关系：“唱”指歌唱。"}], "correct_answer": "有", "explanations": {"有": "正确：“有问题”与“没有问题”构成反义关系。", "借": "与“没有”无反义或近义关系：“借”指借入。", "找": "与“没有”无反义或近义关系：“找”指寻求。", "唱": "与“没有”无反义或近义关系：“唱”指歌唱。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示不存在或不具有。", "primary_collocate": null, "pronunciation": "méi yǒu", "ipa": "mei˧˥ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "桌子上没有书。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里没有人。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路上没有车。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰箱里没有牛奶了。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市没有地铁。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上没有云，月亮很亮。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里没有空位了。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的包里没有钥匙。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里没有你要找的人。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事没有问题。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "沒有", "label": "繁体"}, {"form": "没", "label": "省略形式"}, {"form": "有没有", "label": "正反问"}], "register": "口语", "sense_fingerprint": "没有：某处不存在某人或某物，或事物不具有某种性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有", "is_correct": true, "explanation": "正确：“没有”表示桌上不存在书，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说吃书。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只接衣物，不能用于“书”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能说唱书。"}], "explanations": {"没有": "正确：“没有”表示桌上不存在书，符合语境。", "吃": "语义：“吃”的对象是食物，不能说吃书。", "穿": "搭配：“穿”只接衣物，不能用于“书”。", "唱": "语义：“唱”的对象是歌曲，不能说唱书。"}, "sentence_index": 0, "correct_answer": "没有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个冰箱没有那个大，我们换一个吧。", "explanation": "这里的“没有”表示“不如”，用于比较，是另一个意思，不表示不存在。"}, {"text": "饭还没有做好，你再等一下。", "explanation": "这里的“没有”表示“尚未”，是另一个意思，不表示不存在。"}, {"text": "他没有想到事情会这样，很惊讶。", "explanation": "这里的“没有想到”表示“未曾预料”，是另一个意思，不表示不存在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有", "is_correct": true, "explanation": "正确：“没有空位了”表示空位已经不存在，符合语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品，不能说洗空位。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能说煮空位。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能说喝空位。"}], "explanations": {"没有": "正确：“没有空位了”表示空位已经不存在，符合语境。", "洗": "搭配：“洗”的对象是物品，不能说洗空位。", "煮": "语义：“煮”的对象是食物，不能说煮空位。", "喝": "语义：“喝”的对象是饮品，不能说喝空位。"}, "sentence_index": 6, "correct_answer": "没有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题没有那么难，你很快就能做出来。", "explanation": "这里的“没有”表示“不太”，用于程度，是另一个意思，不表示不存在。"}, {"text": "你没有必要道歉，这不是你的错。", "explanation": "这里的“没有必要”表示“不必”，是另一个意思，不表示不存在。"}, {"text": "我从来没有见过这么大的雪。", "explanation": "这里的“没有”表示“从未”，是另一个意思，不表示不存在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区里很没有超市。", "corrected_sentence": "这个小区里没有超市。", "error_description": "错误：“很没有”。正确：“没有”。表示某处不存在某物时，“没有”前不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天公园里没人有。", "corrected_sentence": "今天公园里没有人。", "error_description": "错误：“没人有”。正确：“没有人”。“没有”是一个整体，后面接名词，“有”不能放在“人”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
