INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20061, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分得指在分配中获得自己应得的部分。", "primary_collocate": null, "pronunciation": "fēn dé", "ipa": "fən˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他在这次分配中分得了一套小房子。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和我各自分得一半的遗产。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司赚钱以后，每个股东都分得了利润。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个孩子平分了水果，每人分得四个苹果。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王在村里分得一块土地。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟分家时，小弟分得一张旧桌子。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，我们队分得了一部分奖金。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在遗产分配中分得的钱最少。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加工作的人都能分得一份年终奖。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想多分得一些，但是别人不同意。", "target_word": "分得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分得了", "label": "体标"}], "register": "书面", "sense_fingerprint": "在分配中得到应得的份额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bfbe3a8-7aeb-4ee1-8a32-ba6db3e80028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20061, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分得", "is_correct": true, "explanation": "分得：在分配中拿到自己的一份，与句中“分配”的语境一致。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”是拆掉，与在分配中得到房子的意思相反，不合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语应是食物，不能说吃掉一套房子。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是烧坏，与在分配中得到房子的意思不符。"}], "explanations": {"分得": "分得：在分配中拿到自己的一份，与句中“分配”的语境一致。", "拆除": "语义：“拆除”是拆掉，与在分配中得到房子的意思相反，不合句意。", "吃掉": "搭配：“吃掉”的宾语应是食物，不能说吃掉一套房子。", "烧毁": "语义：“烧毁”是烧坏，与在分配中得到房子的意思不符。"}, "sentence_index": 0, "correct_answer": "分得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的演讲分得了大家的掌声。", "explanation": "这里应该用〈博得〉。分得指在分配中拿到份额，掌声是博得的，不能说分得。"}, {"text": "比赛结束后，她分得了金牌。", "explanation": "这里应该用〈赢得〉。分得只用于分配所得，金牌是比赛赢来的，要用赢得。"}, {"text": "他分得了老师的表扬。", "explanation": "这里应该用〈得到〉。分得指在分配中拿到份额，表扬是得到的，不能说分得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20061, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分得", "is_correct": true, "explanation": "分得：在比赛后得到自己应得的一部分，与句意一致。"}, {"text": "踢掉", "is_correct": false, "explanation": "搭配：“踢掉”的宾语应是球类等物体，不能说踢掉奖金。"}, {"text": "喝掉", "is_correct": false, "explanation": "搭配：“喝掉”的宾语应是饮品或食物，不能用于奖金。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”是把东西撕成碎片，与比赛后分得奖金的语境不符。"}], "explanations": {"分得": "分得：在比赛后得到自己应得的一部分，与句意一致。", "踢掉": "搭配：“踢掉”的宾语应是球类等物体，不能说踢掉奖金。", "喝掉": "搭配：“喝掉”的宾语应是饮品或食物，不能用于奖金。", "撕碎": "语义：“撕碎”是把东西撕成碎片，与比赛后分得奖金的语境不符。"}, "sentence_index": 6, "correct_answer": "分得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分得一个新方案，但是别人不同意。", "explanation": "这里应该用〈提出〉。分得指在分配中拿到份额，方案是提出来的，不能说分得。"}, {"text": "这次考试他分得了好成绩。", "explanation": "这里应该用〈取得〉。分得只用于分配所得，成绩要靠考试取得，不能说分得。"}, {"text": "他在决赛中分得了冠军。", "explanation": "这里应该用〈夺得〉。分得是在分配中拿到份额，冠军要靠比赛夺得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "分配结束后，他分得过了一份奖金。", "corrected_sentence": "分配结束后，他分得了一份奖金。", "error_description": "体标错误：“分得”后已用“了”，不能再加“过”，应说“分得了一份奖金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱由三人平分，他的分得了三分之一。", "corrected_sentence": "这笔钱由三人平分，他分得了三分之一。", "error_description": "错误：“分得”前多加了“的”。“的”不能接在主语“他”和动词之间，应说“他分得了三分之一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
