INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指刚学会的一种能力或技巧。", "primary_collocate": null, "pronunciation": "xīn jì néng", "ipa": "ɕin˥ tɕi˥˩ nɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "这些新技能可以帮助他们找到新工作。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "不是每个人都能快速学会新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "政府可以让这些人学习新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他在学校学了一个新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作以后，我想学新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技能可以让生活更好。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机学会了新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷也在学习新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请老师教大家新技能。", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最近学到什么新技能？", "target_word": "新技能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项新技能", "label": "量词"}, {"form": "一个新技能", "label": "量词"}], "register": "中性", "sense_fingerprint": "刚学会的能力或技巧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '228a4112-dbe4-4f55-9364-4edc773aa3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新技能", "is_correct": true, "explanation": "正确：技能可以帮助人找到新工作。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不能帮人找到工作。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具与找工作没有关系。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“帮助他们找到工作”的主语应是能力或途径，窗户不能充当。"}], "explanations": {"新技能": "正确：技能可以帮助人找到新工作。", "食物": "语义：食物不能帮人找到工作。", "家具": "语义：家具与找工作没有关系。", "窗户": "搭配：“帮助他们找到工作”的主语应是能力或途径，窗户不能充当。"}, "sentence_index": 0, "correct_answer": "新技能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在学校学了一本新技能。", "explanation": "这里应该用〈个〉或〈项〉。〈本〉用于书册，不用于技能。"}, {"text": "她的书包里装着一项新技能。", "explanation": "这里是把〈技能〉当成了〈物品〉来用。技能是人学会的本领，不能像东西一样装进包里。"}, {"text": "他把新技能放进了冰箱。", "explanation": "这里是把〈技能〉当成了〈东西〉。技能是人学会的本领，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新技能", "is_correct": true, "explanation": "正确：“用手机学会了”后接的是能力或知识，与“新技能”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“学会”后接技能、知识、语言一类，不接桌子。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“学会”不接天气。"}, {"text": "手机", "is_correct": false, "explanation": "语义：与前文“用手机”重复，学会的不能是手机本身。"}], "explanations": {"新技能": "正确：“用手机学会了”后接的是能力或知识，与“新技能”相合。", "桌子": "搭配：“学会”后接技能、知识、语言一类，不接桌子。", "天气": "搭配：“学会”不接天气。", "手机": "语义：与前文“用手机”重复，学会的不能是手机本身。"}, "sentence_index": 6, "correct_answer": "新技能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我最近学到了一首新技能。", "explanation": "这里应该用〈项〉或〈个〉。〈首〉用于诗歌、歌曲，不用于技能。"}, {"text": "他们这个夏天参加了一个新技能。", "explanation": "这里应该用〈项目〉。“参加”的对象是活动或比赛，技能不能参加。"}, {"text": "他的新技能是一本词典。", "explanation": "这里应该用〈工具〉。技能是人学会的本领，“一本词典”是物品，不能作为技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她学会了一条新技能。", "corrected_sentence": "她学会了一项新技能。", "error_description": "“一条新技能”应为“一项新技能”。“条”用于细长的物件，技能要用“项”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥新技能是修电脑。", "corrected_sentence": "哥哥的新技能是修电脑。", "error_description": "“哥哥新技能”应为“哥哥的新技能”。表示所属的人（哥哥）修饰后面的名词短语时要加“的”，“新”作定语则不需要“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20063, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20063, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20063, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经济状况差，缺乏足够金钱或物质财富的人。", "primary_collocate": null, "pronunciation": "qióng rén", "ipa": "tɕʰjʊŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "穷人买不起新房子，只能租房住。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位富人常常帮助穷人。", "target_word": "穷人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "以前这里的穷人很多，生活很苦。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，穷人也应该有看病的机会。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是穷人，可是他很节省。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店为穷人免费提供午饭。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在那个年代，穷人一天只吃两顿饭。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小时候是穷人，现在是老板了。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生免费给穷人看病，大家都很感谢他。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多穷人冬天没有钱买厚衣服。", "target_word": "穷人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "窮人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经济困难、缺少财富的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穷人", "is_correct": true, "explanation": "正确。「穷人买不起新房子，只能租房住」描述经济困难的人，只有「穷人」能填入空格。"}, {"text": "富人", "is_correct": false, "explanation": "语义：富人一般买得起房子，「富人买不起新房子，只能租房住」与句意矛盾。"}, {"text": "房东", "is_correct": false, "explanation": "搭配：房东是出租房子的人，不会「只能租房住」，与后半句搭配不当。"}, {"text": "富翁", "is_correct": false, "explanation": "语义：富翁通常不会因为买不起房子而只能租房，与句子的语境矛盾。"}], "explanations": {"穷人": "正确。「穷人买不起新房子，只能租房住」描述经济困难的人，只有「穷人」能填入空格。", "富人": "语义：富人一般买得起房子，「富人买不起新房子，只能租房住」与句意矛盾。", "房东": "搭配：房东是出租房子的人，不会「只能租房住」，与后半句搭配不当。", "富翁": "语义：富翁通常不会因为买不起房子而只能租房，与句子的语境矛盾。"}, "sentence_index": 0, "correct_answer": "穷人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府计划用五年时间消除穷人。", "explanation": "这里应该用「贫困」。「穷人」指人，不能用「消除」来修饰；要消灭的是「贫困」这种状况。"}, {"text": "这个穷人国家的经济在十年内翻了一番。", "explanation": "「穷人」指人，形容国家经济落后应说「穷国」，「穷人国家」不是固定说法。"}, {"text": "我们公司是穷人，去年赚了很多钱。", "explanation": "「穷人」只指人，不能用来形容公司；说公司经济困难要用「经营困难」等说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穷人", "is_correct": true, "explanation": "正确。「在那个年代，穷人一天只吃两顿饭」描述贫困的生活，只有「穷人」能填入空格。"}, {"text": "富豪", "is_correct": false, "explanation": "语义：富豪不会「一天只吃两顿饭」，与句中的贫困语境矛盾。"}, {"text": "地主", "is_correct": false, "explanation": "语义：地主一般是有田产的富人，“一天只吃两顿饭”的困苦语境与之矛盾。"}, {"text": "财主", "is_correct": false, "explanation": "语义：财主是富有的人，“一天只吃两顿饭”的困苦语境与之矛盾。"}], "explanations": {"穷人": "正确。「在那个年代，穷人一天只吃两顿饭」描述贫困的生活，只有「穷人」能填入空格。", "富豪": "语义：富豪不会「一天只吃两顿饭」，与句中的贫困语境矛盾。", "地主": "语义：地主一般是有田产的富人，“一天只吃两顿饭”的困苦语境与之矛盾。", "财主": "语义：财主是富有的人，“一天只吃两顿饭”的困苦语境与之矛盾。"}, "sentence_index": 6, "correct_answer": "穷人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的目标是彻底摆脱穷人。", "explanation": "这里应该用「贫困」。「摆脱」的对象是「贫困」这种状况，不能是人。"}, {"text": "我们小区东边有一片很大的穷人窟。", "explanation": "表示贫困的居住区要说「贫民窟」，「穷人窟」不是固定说法，「穷人」只指人。"}, {"text": "这所中学的穷人生有三百多名，学校每年都发补助。", "explanation": "「穷人」不能缩略成「生」，表示家境困难的学生应说「贫困生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只穷人很热心，常常帮助邻居。", "corrected_sentence": "那位穷人很热心，常常帮助邻居。", "error_description": "错误形式「那只穷人」，量词「只」用于指人错误。正确形式「那位穷人」，指人应该用「位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把钱分给了很穷人。", "corrected_sentence": "他把钱分给了很穷的人。", "error_description": "错误形式「很穷人」，「穷」是形容词，直接修饰名词时要加「的」。正确形式「很穷的人」，形容词修饰名词需用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20064, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工作", "is_correct": true, "explanation": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。"}, {"text": "散步", "is_correct": false, "explanation": "散步是一种轻松的活动，与“休息”并不构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是一种运动，并不与“休息”相对，不构成反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行是一种活动，与“休息”没有反义关系，不能作为其反义词。"}], "correct_answer": "工作", "explanations": {"工作": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。", "散步": "散步是一种轻松的活动，与“休息”并不构成反义关系。", "游泳": "游泳是一种运动，并不与“休息”相对，不构成反义关系。", "旅行": "旅行是一种活动，与“休息”没有反义关系，不能作为其反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20064, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工作", "is_correct": true, "explanation": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是一种运动，并不与“休息”相对，不构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是一种娱乐活动，与“休息”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书是一种学习活动，并不是“休息”的反义词。"}], "correct_answer": "工作", "explanations": {"工作": "正确。“工作”与“休息”构成反义：工作是做事，休息是停下来不做事。", "跑步": "跑步是一种运动，并不与“休息”相对，不构成反义关系。", "唱歌": "唱歌是一种娱乐活动，与“休息”没有反义关系。", "读书": "读书是一种学习活动，并不是“休息”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "暂时停止工作、学习或活动，使身体和精神得到恢复。", "primary_collocate": null, "pronunciation": "xiū xi", "ipa": "ɕjoʊ˥ ɕi", "syllable_count": 2, "sentences": [{"text": "人可以休息多一点，或做喜欢的事。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "工作了一上午，我们去休息一下吧。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说你太累了，应该多休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我在家休息，哪儿也不去。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天不上班，你可以好好休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他睡得太晚，今天上课没有精神，要多休息。", "target_word": "休息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑了一个小时，大家坐下来休息了十分钟。", "target_word": "休息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人需要在安静的房间里休息。", "target_word": "休息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经学了三个小时，该休息了。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上十一点了，爸爸还没休息。", "target_word": "休息", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "休息了", "label": "体标"}, {"form": "休息过", "label": "体标"}, {"form": "休息休息", "label": "重叠"}], "register": "中性", "sense_fingerprint": "暂停工作或学习，恢复身体精神", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的不自主反应，不是可以多做的活动，“人可以咳嗽多一点”句意不通。"}, {"text": "讨厌", "is_correct": false, "explanation": "配价：“讨厌”要带宾语（讨厌什么），“讨厌多一点”没有宾语，搭配不成立。"}, {"text": "休息", "is_correct": true, "explanation": "正确。“休息”指暂停活动以恢复精力，“人可以休息多一点”与后句“或做喜欢的事”的语境相合。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是情绪反应，不是可以“多做”的事，与后句“做喜欢的事”的选择语境相悖。"}], "explanations": {"咳嗽": "语义：“咳嗽”是身体的不自主反应，不是可以多做的活动，“人可以咳嗽多一点”句意不通。", "讨厌": "配价：“讨厌”要带宾语（讨厌什么），“讨厌多一点”没有宾语，搭配不成立。", "休息": "正确。“休息”指暂停活动以恢复精力，“人可以休息多一点”与后句“或做喜欢的事”的语境相合。", "生气": "语义：“生气”是情绪反应，不是可以“多做”的事，与后句“做喜欢的事”的选择语境相悖。"}, "sentence_index": 0, "correct_answer": "休息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车在路上突然休息，司机只好停下来修理。", "explanation": "这里应该用〈熄火〉。休息用于人或动物，指停下来恢复身心；发动机停转应说熄火，汽车不能“休息”。"}, {"text": "生产线出了故障，只能休息检修。", "explanation": "这里应该用〈停机〉。休息用于人，指恢复精力；生产线停下来检修应说停机。"}, {"text": "这个软件的更新休息了一周，用户只能等待。", "explanation": "这里应该用〈暂停〉。休息指人停下活动、恢复精力，更新工作不会累，应说暂停。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：“坐下来游泳”前后矛盾，与句中“跑了一个小时”后大家停下歇息的语境不合。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“坐下来跳舞”自相矛盾，不符合句意中大家停下来歇一歇的情境。"}, {"text": "休息", "is_correct": true, "explanation": "正确。“坐下来休息”指坐下歇一歇，与“跑了一个小时”和“十分钟”的语境相合。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”需要带宾语（买什么），“坐下来买了十分钟”缺少宾语，句子不成立。"}], "explanations": {"游泳": "语义：“坐下来游泳”前后矛盾，与句中“跑了一个小时”后大家停下歇息的语境不合。", "跳舞": "语义：“坐下来跳舞”自相矛盾，不符合句意中大家停下来歇一歇的情境。", "休息": "正确。“坐下来休息”指坐下歇一歇，与“跑了一个小时”和“十分钟”的语境相合。", "买": "配价：“买”需要带宾语（买什么），“坐下来买了十分钟”缺少宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "休息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱每天晚上都休息。", "explanation": "这里应该用〈停转〉。休息用于人或动物，指停下活动、恢复精力；冰箱不会累，不能说休息。"}, {"text": "这辆电动车昨晚休息了，今天早上骑不动。", "explanation": "这里应该用〈没电〉。休息用于人或动物，指恢复精力；电动车电量耗尽应说没电。"}, {"text": "这个水龙头每天晚上都休息。", "explanation": "这里应该用〈关闭〉。休息用于人或动物，水龙头不会累，应说关闭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑了半天，现在想休息了一下。", "corrected_sentence": "他跑了半天，现在想休息一下。", "error_description": "体标错误：“想”表示意愿，后面的动作还没发生，不能用“了”，应说“想休息一下”，不能说“想休息了一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨晚休息很好，今天精神很足。", "corrected_sentence": "他昨晚休息得很好，今天精神很足。", "error_description": "补语错误：“休息”后接程度补语时要用“得”，应说“休息得很好”，不能说“休息很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
