INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20065, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公司或单位因经营困难等原因，辞退部分员工。", "primary_collocate": null, "pronunciation": "cái yuán", "ipa": "tsʰaɪ˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "很多科技公司已经开始裁员，员工们需要学习新的技能来适应变化。", "target_word": "裁员", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "公司生意不好，今年要裁员。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济不好，很多工厂开始裁员。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说下个月公司会裁员一百人。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为经营困难，这家公司不得不裁员。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司裁员以后，留下的人工作更忙了。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的公司裁员了，所以他在找新工作。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说公司要裁员，同事们都很担心。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家银行去年裁员两千人。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司没有钱发工资，只好裁员。", "target_word": "裁员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "裁员潮", "label": "复合"}, {"form": "裁员计划", "label": "复合"}, {"form": "裁員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "企业因经营困难辞退部分员工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁员", "is_correct": true, "explanation": "裁员：公司因经营困难辞退部分员工，与“员工需要学习新技能来适应变化”的语境相合。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：公司不会下雪，「公司开始下雪」句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与公司的经营变化无关，“公司开始游泳”不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与公司的经营变化无关，“公司开始散步”不通。"}], "explanations": {"裁员": "裁员：公司因经营困难辞退部分员工，与“员工需要学习新技能来适应变化”的语境相合。", "下雪": "语义：公司不会下雪，「公司开始下雪」句意不通。", "游泳": "语义：游泳与公司的经营变化无关，“公司开始游泳”不通。", "散步": "语义：散步与公司的经营变化无关，“公司开始散步”不通。"}, "sentence_index": 0, "correct_answer": "裁员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为身体不好，决定裁员，回家休养。", "explanation": "这里应该用〈辞职〉。裁员的主体是公司，员工因身体原因主动离职要用辞职。"}, {"text": "老板因为他经常迟到，今天把他裁员了。", "explanation": "这里应该用〈开除〉。裁员指因经营原因大批辞退员工，因个人过错辞退一人要用开除。"}, {"text": "我爷爷六十岁就裁员了，现在每天在公园下棋。", "explanation": "这里应该用〈退休〉。裁员是单位辞退员工，到了年龄离开工作要用退休。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁员", "is_correct": true, "explanation": "裁员：公司辞退员工，所以他要找新工作。"}, {"text": "加薪", "is_correct": false, "explanation": "语义：加薪是好事，与“所以他在找新工作”的因果不合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与公司人事和找工作无关，“他的公司唱歌了”不通。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“修车”的宾语是车辆，“他的公司修车了”与“找新工作”之间没有关联。"}], "explanations": {"裁员": "裁员：公司辞退员工，所以他要找新工作。", "加薪": "语义：加薪是好事，与“所以他在找新工作”的因果不合。", "唱歌": "语义：唱歌与公司人事和找工作无关，“他的公司唱歌了”不通。", "修车": "搭配：“修车”的宾语是车辆，“他的公司修车了”与“找新工作”之间没有关联。"}, "sentence_index": 6, "correct_answer": "裁员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂今年裁员了三台旧机器，节省了不少电费。", "explanation": "这里应该用〈报废〉。裁员的对象必须是员工，旧机器要用报废。"}, {"text": "他去年被裁员到了上海分公司。", "explanation": "这里应该用〈调动〉。裁员是单位辞退员工，把员工派到外地工作要用调动。"}, {"text": "我们班裁员了三个同学，他们都转到别的学校去了。", "explanation": "这里应该用〈转学〉。裁员用于单位辞退员工；学生转到别的学校要用转学，不能说裁员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把员工裁员了，大家都很难过。", "corrected_sentence": "公司裁员了，大家都很难过。", "error_description": "宾语重复：“裁员”本身已包含“员”，不能再带“员工”作宾语，也不能加“把”结构。错误形式是“把员工裁员了”，正确形式是“裁员了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听说这个月公司很裁员五十人，老板先和大家开会。", "corrected_sentence": "听说这个月公司会裁员五十人，老板先和大家开会。", "error_description": "副词错误：「很」不能直接修饰动词「裁员」，表示将要发生应用能愿动词「会」。错误形式是「公司很裁员五十人」，正确形式是「公司会裁员五十人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
