INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有价值的物品和金钱的总和。", "primary_collocate": null, "pronunciation": "cái fù", "ipa": "tsʰaɪ˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "政府也在讨论新的政策，想找到公平分配财富的方法。", "target_word": "财富", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "健康比财富更重要。", "target_word": "财富", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一生创造了很多财富。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人把全部财富捐给了学校。", "target_word": "财富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家族的财富主要来自房地产。", "target_word": "财富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠努力工作积累了不少财富。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家的财富来自人民的劳动。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的财富很多，但是一点也不快乐。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把大部分财富都投在了房产上。", "target_word": "财富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人拥有的财富让人羡慕。", "target_word": "财富", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔财富", "label": "量词"}, {"form": "财富观", "label": "复合"}, {"form": "財富", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有价值的物品与金钱的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财富", "is_correct": true, "explanation": "正确：“财富”指有价值的物品和金钱的总和，可以被公平分配。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体的特征，无法被“公平分配”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是个人的特点，不是可以分配的东西。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“分配”不与“颜色”搭配，“颜色”也不是可以分配的对象。"}], "explanations": {"财富": "正确：“财富”指有价值的物品和金钱的总和，可以被公平分配。", "身高": "体貌：身高是身体的特征，无法被“公平分配”。", "性格": "语义：性格是个人的特点，不是可以分配的东西。", "颜色": "搭配：“分配”不与“颜色”搭配，“颜色”也不是可以分配的对象。"}, "sentence_index": 0, "correct_answer": "财富"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去超市买菜，一共花了不少财富。", "explanation": "这里应该用〈钱〉。财富指积累的大量财物，日常买菜的开销要说“花钱”。"}, {"text": "他在公司的财富很高。", "explanation": "这里应该用〈地位〉。财富指财物的总和，不能用来说明一个人在公司中的社会位置。"}, {"text": "他今年财富很好，买彩票中了奖。", "explanation": "这里应该用〈财运〉。财运指一段时间的运气，财富是已拥有财物的总和，不能说“很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财富", "is_correct": true, "explanation": "正确：“财富”指一个国家积累的财物与金钱的总和，来自人民的劳动。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是时间的累积，不是劳动所得，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的特征，不能说“来自人民的劳动”。"}, {"text": "面积", "is_correct": false, "explanation": "语义：国土面积是自然形成的，不来自人民的劳动，句意不通。"}], "explanations": {"财富": "正确：“财富”指一个国家积累的财物与金钱的总和，来自人民的劳动。", "年龄": "语义：年龄是时间的累积，不是劳动所得，与句意不符。", "体重": "体貌：体重是身体的特征，不能说“来自人民的劳动”。", "面积": "语义：国土面积是自然形成的，不来自人民的劳动，句意不通。"}, "sentence_index": 6, "correct_answer": "财富"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看问题的财富很独到，常能看到别人看不到的机会。", "explanation": "这里应该用〈眼光〉。财富指财物和金钱的总和，不用来说明看问题的角度和见解。"}, {"text": "他的财富每个月都会打到卡里。", "explanation": "这里应该用〈工资〉。财富是积累的财物总和，不是每月定期发放的款项。"}, {"text": "这本书的财富很高，值得一读。", "explanation": "这里应该用〈价值〉。财富指财物和金钱的总和，不用来评价一本书的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他继承了一个财富。", "corrected_sentence": "他继承了一笔财富。", "error_description": "错误：量词“个”；正确：量词“笔”。“财富”的量词是“笔”，用“个”是泛用量词的误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位企业家是很多财富。", "corrected_sentence": "这位企业家拥有很多财富。", "error_description": "错误：“是”把人说成财物，句意不通；“财富”是可拥有的财物，应与“拥有”搭配作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20067, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就业", "is_correct": true, "explanation": "就业：指有工作、进入工作岗位，与“失业”意义相反。"}, {"text": "辞职", "is_correct": false, "explanation": "辞职指主动离开现有工作，与“失业”不是反义关系。"}, {"text": "退休", "is_correct": false, "explanation": "退休指到了规定年龄不再工作，与“失业”不是反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指随意走走、活动身体，与“失业”不是反义关系。"}], "correct_answer": "就业", "explanations": {"就业": "就业：指有工作、进入工作岗位，与“失业”意义相反。", "辞职": "辞职指主动离开现有工作，与“失业”不是反义关系。", "退休": "退休指到了规定年龄不再工作，与“失业”不是反义关系。", "散步": "散步：指随意走走、活动身体，与“失业”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20067, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就业", "is_correct": true, "explanation": "就业：指有工作、进入工作岗位，与“失业”意义相反。"}, {"text": "休息", "is_correct": false, "explanation": "休息指停下来放松，与“失业”不是反义关系。"}, {"text": "旅游", "is_correct": false, "explanation": "旅游指外出游览，与“失业”不是反义关系。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚指建立婚姻关系，与“失业”不是反义关系。"}], "correct_answer": "就业", "explanations": {"就业": "就业：指有工作、进入工作岗位，与“失业”意义相反。", "休息": "休息指停下来放松，与“失业”不是反义关系。", "旅游": "旅游指外出游览，与“失业”不是反义关系。", "结婚": "结婚指建立婚姻关系，与“失业”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a5ded58-6004-4c0b-b250-389fa523ecfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
